  const MAXI_CATEGORY_LABELS = {
    acting: "ACTING",
    comedy: "COMEDY",
    improv: "IMPROV",
    ads: "ADVERTISING",
    dance: "DANCE",
    design: "DESIGN",
    runway: "RUNWAY",
    girl_group: "GIRL GROUPS",
    rusical: "RUSICAL",
    ball: "BALL",
    makeover: "MAKEOVER",
    rumix: "RUMIX",
    singing: "SINGING",
    lipsync: "LIP SYNC",
    snatch_game: "SNATCH GAME",
    talent_show: "TALENT SHOW",
  };

  function maxiChallengeTypeLabel(challengeOrMaxi, fallbackCategory = "") {
    const item = challengeOrMaxi || {};
    const haystack = `${item.name || ""} ${item.description || ""}`.toLowerCase();
    if (/rapping\s+roast/.test(haystack)) return "Rapping Roast";
    if (/\brdr\s+live\b/.test(haystack)) return "RDR Live";
    if (/stand[\s-]*up/.test(haystack)) return "Stand Up";
    if (/\broast\b/.test(haystack)) return "Roast";
    return MAXI_CATEGORY_LABELS[fallbackCategory || item.category || item.type] ||
      String(fallbackCategory || item.category || item.type || "").toUpperCase();
  }

  const NORMAL_MAXI_CATEGORIES = [
    "acting",
    "comedy",
    "improv",
    "ads",
    "dance",
    "design",
    "runway",
    "girl_group",
    "rusical",
    "singing",
  ];

  const SPECIAL_ONLY_MAXI_CATEGORIES = new Set([
    "ball",
    "makeover",
    "rumix",
    "snatch_game",
    "lipsync",
  ]);

  const NO_SEPARATE_RUNWAY_CATEGORIES = new Set(["makeover", "design", "ball", "runway"]);

