  const dragRaceSetupSelectHTML = {
    eliminationFormat: document.querySelector('[data-setup-select="eliminationFormat"]')?.innerHTML || "",
    premiereFormat: document.querySelector('[data-setup-select="premiereFormat"]')?.innerHTML || "",
    comebackFormat: document.querySelector('[data-setup-select="comebackFormat"]')?.innerHTML || "",
  };

  function isDragulaMode() {
    return state.simulatorMode === "dragula";
  }

  function isDragulaResurrectionFormat() {
    return isDragulaMode() && String(state.seasonSetup?.eliminationFormat || "regular") === "resurrection";
  }

  function isDragulaTitansFormat() {
    return isDragulaMode() && String(state.seasonSetup?.eliminationFormat || "regular") === "titans";
  }

  function dragulaSonicTransducerEnabled() {
    return Boolean(
      isDragulaMode() &&
      !isDragulaResurrectionFormat() &&
      state.seasonSetup?.productionControls?.has?.("sonic-transducer")
    );
  }

  function dragulaFrightFeatImmunityEnabled() {
    return Boolean(
      isDragulaMode() &&
      !isDragulaResurrectionFormat() &&
      state.seasonSetup?.productionControls?.has?.("fright-feat-immunity")
    );
  }

  function runtimeHasDragulaTitansFormat() {
    return Boolean(
      state.seasonRuntime?.dragulaTitans ||
      (state.seasonRuntime?.episodes || []).some((episode) => Boolean(episode?.dragulaTitans))
    );
  }

  function runtimeHasDragulaResurrectionFormat() {
    return Boolean(
      state.seasonRuntime?.dragulaResurrection ||
      (state.seasonRuntime?.episodes || []).some((episode) => Boolean(episode?.dragulaResurrection))
    );
  }

  function runtimeHasDragulaFormat() {
    return Boolean(
      state.seasonRuntime?.dragula ||
      (state.seasonRuntime?.episodes || []).some((episode) => Boolean(episode?.dragula))
    );
  }

  function dragulaExterminationRiggoryDisabled() {
    const controls = state.seasonSetup?.productionControls;
    return Boolean(
      state.seasonSetup?.disableExterminationRiggory ||
      controls?.has?.("disable-extermination-riggory")
    );
  }

  function rupaulModeEnabled() {
    return !isDragulaMode() && !isHoliSlayMode() && !isCallMeMother() && Boolean(state.seasonSetup?.rupaulMode);
  }

  function bouletsModeEnabled() {
    return isDragulaMode() && Boolean(state.seasonSetup?.bouletsMode);
  }

  function directorModeEnabled() {
    return rupaulModeEnabled() || bouletsModeEnabled();
  }

  function syncRuPaulModeUi() {
    const dragula = isDragulaMode();
    if (dragula) state.seasonSetup.rupaulMode = false;
    else state.seasonSetup.bouletsMode = false;
    const enabled = dragula ? Boolean(state.seasonSetup.bouletsMode) : Boolean(state.seasonSetup.rupaulMode);
    (els.rupaulModeButtons || []).forEach((button) => {
      const active = button.dataset.rupaulMode === (enabled ? "rupaul" : "standard");
      button.classList.toggle("is-selected", active);
      button.setAttribute("aria-pressed", active ? "true" : "false");
      if (button.dataset.rupaulMode === "rupaul") button.textContent = dragula ? "BOULETS MODE" : "RUPAUL MODE";
      else button.textContent = "STANDARD";
      button.closest('[role="group"]')?.setAttribute("aria-label", dragula ? "Boulets mode" : "RuPaul mode");
    });
  }

  function setRuPaulMode(mode) {
    const enabled = mode === "rupaul";
    if (isDragulaMode()) {
      if (Boolean(state.seasonSetup.bouletsMode) === enabled) return;
      state.seasonSetup.bouletsMode = enabled;
      state.seasonSetup.rupaulMode = false;
    } else {
      if (Boolean(state.seasonSetup.rupaulMode) === enabled) return;
      state.seasonSetup.rupaulMode = enabled;
      state.seasonSetup.bouletsMode = false;
    }
    invalidateSeasonRuntime();
    syncRuPaulModeUi();
    persistState();
  }

