  function lalaparuzaComebackTriggerActiveCount() {
    return Math.floor(Math.max(0, Number(state.castSize || 0)) / 2) + 1;
  }

  function lalaparuzaComebackFormatConflict() {
    const format = String(state.seasonSetup?.eliminationFormat || "regular");
    if (state.castSize < 6) return true;
    if (["team", "all-winners", "all-stars-9", "tournament", "golden-baguette", "heart-successor"].includes(format)) {
      return true;
    }
    const competitionStop = selectedFinalistSizeForComeback() + (musicVideoSemifinalEnabled() ? 1 : 0);
    return lalaparuzaComebackTriggerActiveCount() < competitionStop;
  }

  function syncLaLaPaRuZaComebackSetupControls({ resetInvalid = true, alertOnReset = false } = {}) {
    const select = document.querySelector("#comebackFormat");
    if (!select) return;

    const option = [...select.options].find((item) => item.value === "lalaparuza-comeback");
    const unavailable = lalaparuzaComebackFormatConflict();
    if (option) option.disabled = unavailable;

    if (resetInvalid && isLaLaPaRuZaComebackFormat() && unavailable) {
      state.seasonSetup.comebackFormat = "none";
      select.value = "none";
      if (alertOnReset) {
        const format = String(state.seasonSetup?.eliminationFormat || "regular");
        let message = "LaLaPaRuZa is not available with the current setup.";
        if (state.castSize < 6) {
          message = "LaLaPaRuZa requires a cast of at least 6 contestants.";
        } else if (["team", "all-winners", "all-stars-9", "tournament", "golden-baguette", "heart-successor"].includes(format)) {
          message = "LaLaPaRuZa is not compatible with Team, All Winners, All Stars 9, Tournament, Golden Baguette, or Heart Successor Format.";
        } else {
          message = "LaLaPaRuZa needs enough competitive episodes to reach its midseason active-vs-eliminated trigger before the finale.";
        }
        window.alert(message);
      }
    }
  }

  function fameGamesEnabled() {
    return Boolean(state.seasonSetup?.seasonTwists?.has?.("fame-games"));
  }

  function fameGamesReturningChallengeConflict() {
    const comeback = String(state.seasonSetup?.comebackFormat || "").toLowerCase();
    return comeback.includes("reading") && comeback !== "none";
  }

  function fameGamesFormatConflict() {
    return isTeamsFormat() || isAllWinnersSeason();
  }

  function classicImmunityEnabled() {
    return Boolean(
      state.seasonSetup?.immunityTwist ||
      state.seasonSetup?.seasonTwists?.has?.("immunity")
    );
  }

  function classicImmunityAwardCutoff(originalCastSize) {
    const size = Math.max(0, Math.floor(Number(originalCastSize) || 0));

    if (size <= 9) return Math.max(0, size - 2);
    if (size <= 11) return Math.max(0, size - 3);
    if (size <= 17) return Math.max(0, size - 4);
    return Math.max(0, size - 5);
  }

  function classicImmunityBlockedPremiere(episode) {
    if (!episode?.isPremiere) return false;
    const format = String(episode?.premiereFormat || "").toLowerCase();
    return ["season6", "season14", "philippines2", "philippines-2"].includes(format);
  }

  function classicImmunitySupportedForEpisode(episode) {
    if (!classicImmunityEnabled()) return false;
    if (!episode || episode.isFinale) return false;
    if (isTeamsFormat() || episode.teamFormat || episode.fromTeamsFormat) return false;
    if (classicImmunityBlockedPremiere(episode)) return false;
    return true;
  }

  function classicImmunityContainsId(ids, id) {
    const key = normalizeContestantId(id);
    return (ids || []).some((candidate) => normalizeContestantId(candidate) === key);
  }

  function classicImmunityData(episode) {
    if (!episode) return null;
    if (!episode.classicImmunity || typeof episode.classicImmunity !== "object") {
      episode.classicImmunity = {
        version: 1,
        activeIds: [],
        awardedIds: [],
        savedIds: [],
        savedId: null,
        used: false,
        preSaveBottomIds: [],
        finalBottomIds: [],
      };
    }
    return episode.classicImmunity;
  }

  function classicImmunityActiveIdsForEpisode(episode, participants, priorEpisodes) {
    if (!classicImmunitySupportedForEpisode(episode)) return [];

    const prior = Array.isArray(priorEpisodes) ? priorEpisodes : [];
    const currentParticipantKeys = new Set(
      (participants || []).map((queen) => normalizeContestantId(queen.id))
    );
    const activeIds = [];
    const resolvedKeys = new Set();

    for (let index = prior.length - 1; index >= 0; index -= 1) {
      const sourceEpisode = prior[index];
      const awardedIds = sourceEpisode?.classicImmunity?.awardedIds || sourceEpisode?.classicImmunityAwardedIds || [];

      for (const awardedId of awardedIds) {
        const key = normalizeContestantId(awardedId);
        if (!key || resolvedKeys.has(key) || !currentParticipantKeys.has(key)) continue;
        resolvedKeys.add(key);

        const competedSinceAward = prior.slice(index + 1).some((laterEpisode) => {
          if (!laterEpisode?.maxiChallenge || laterEpisode?.isFinale) return false;
          const competitorIds = laterEpisode.competitionCastIds?.length
            ? laterEpisode.competitionCastIds
            : laterEpisode.castIds;
          return (competitorIds || []).some(
            (id) => normalizeContestantId(id) === key
          );
        });

        if (!competedSinceAward) activeIds.push(awardedId);
      }
    }

    return uniqueValidParticipantIds(activeIds, participants || []);
  }

  function classicImmunityPreliminaryBottomIds(episode, participants) {
    if (episode?.allStarsLegacy) {
      return uniqueValidParticipantIds(episode.legacyJudging?.preliminaryBottomIds || [], participants);
    }
    if (episode?.allStarsAssassin) {
      return uniqueValidParticipantIds(episode.assassinJudging?.preliminaryBottomIds || [], participants);
    }
    return uniqueValidParticipantIds(episode?.maxiChallenge?.bottomPoolIds || [], participants);
  }

  function applyClassicImmunityToAllStars(episode, participants, savedIds) {
    const maxi = episode?.maxiChallenge;
    const legacy = episode?.allStarsLegacy;
    const data = legacy ? episode?.legacyJudging : episode?.assassinJudging;
    if (!maxi || !data) return [];

    const preliminaryBottomIds = uniqueValidParticipantIds(data.preliminaryBottomIds || [], participants);
    const savedKeys = new Set((savedIds || []).map((id) => normalizeContestantId(id)));
    const remaining = preliminaryBottomIds.filter((id) => !savedKeys.has(normalizeContestantId(id)));
    const placements = maxi.placements || {};

    preliminaryBottomIds.forEach((id) => { placements[id] = "SAFE"; });
    (savedIds || []).forEach((id) => { placements[id] = "LOW"; });

    let lowIds = [];
    let eligibleBottomIds = [...remaining];

    if (legacy) {
      const wasForcedTop5Bottom3 = Boolean(
        participants.length === 5 &&
        (data.lowIds || []).length === 0 &&
        (data.eligibleBottomIds || []).length === preliminaryBottomIds.length
      );
      if (
        !wasForcedTop5Bottom3 &&
        eligibleBottomIds.length > 2 &&
        allStarsLegacyPerformanceScore(maxi, eligibleBottomIds[0]) < 20
      ) {
        lowIds = [eligibleBottomIds.shift()];
      }
    } else if (participants.length > 5 && eligibleBottomIds.length >= 3) {
      lowIds = [eligibleBottomIds.shift()];
    }

    lowIds.forEach((id) => { placements[id] = "LOW"; });
    const bottomLabel = eligibleBottomIds.length > 1
      ? `BTM${eligibleBottomIds.length}`
      : (eligibleBottomIds.length === 1 ? "BTM1" : "");
    eligibleBottomIds.forEach((id) => { placements[id] = bottomLabel || "BTM"; });

    data.lowIds = [
      ...(savedIds || []),
      ...lowIds.filter((id) => !savedKeys.has(normalizeContestantId(id))),
    ];
    data.eligibleBottomIds = [...eligibleBottomIds];
    data.bottomLabel = bottomLabel;

    if (legacy) {
      maxi.legacyLowIds = [...data.lowIds];
      maxi.legacyEligibleBottomIds = [...eligibleBottomIds];
      maxi.legacyBottomLabel = bottomLabel;
    } else {
      maxi.assassinLowIds = [...data.lowIds];
      maxi.assassinEligibleBottomIds = [...eligibleBottomIds];
      maxi.assassinBottomLabel = bottomLabel;
    }

    maxi.placements = placements;
    return [...eligibleBottomIds];
  }

  function applyClassicImmunityToStandardJudging(episode, participants, savedIds, preliminaryBottomIds) {
    const maxi = episode?.maxiChallenge;
    if (!maxi) return [];
    const savedKeys = new Set((savedIds || []).map((id) => normalizeContestantId(id)));
    const remaining = preliminaryBottomIds.filter((id) => !savedKeys.has(normalizeContestantId(id)));
    const placements = maxi.placements || {};

    preliminaryBottomIds.forEach((id) => { placements[id] = "SAFE"; });
    (savedIds || []).forEach((id) => { placements[id] = "LOW"; });

    if (episode?.specialJudgingEvent?.kind === "bottom6") {
      const label = `BTM${remaining.length}`;
      remaining.forEach((id) => { placements[id] = label; });
      episode.specialBottomGroupIds = [...remaining];
    } else if (episode?.specialJudgingEvent?.kind === "lalaparuza") {
      remaining.forEach((id) => { placements[id] = "BTM"; });
      episode.lalaparuzaBottomIds = [...remaining];
    } else {
      const adjusted = immunityAdjustedScoreMap(maxi);
      const orderedBottom = [...remaining].sort(
        (a, b) => (adjusted.get(normalizeContestantId(a)) ?? 999) - (adjusted.get(normalizeContestantId(b)) ?? 999)
      );
      if (orderedBottom.length >= 3) {
        orderedBottom.slice(0, -2).forEach((id) => { placements[id] = "LOW"; });
        orderedBottom.slice(-2).forEach((id) => { placements[id] = "BTM2"; });
      } else if (orderedBottom.length === 2) {
        orderedBottom.forEach((id) => { placements[id] = "BTM2"; });
      } else if (orderedBottom.length === 1) {
        placements[orderedBottom[0]] = "LOW";
      }
    }

    maxi.placements = placements;
    return Object.entries(placements)
      .filter(([, placement]) => /^BTM(?:\d+)?$/.test(String(placement || "")))
      .map(([id]) => canonicalParticipantId(id, participants))
      .filter((id) => id !== null && id !== undefined && !savedKeys.has(normalizeContestantId(id)));
  }

  function applyClassicImmunityForEpisode(episode, participants, priorEpisodes) {
    if (!classicImmunitySupportedForEpisode(episode)) return;
    const info = classicImmunityData(episode);
    const activeIds = classicImmunityActiveIdsForEpisode(episode, participants, priorEpisodes);
    info.activeIds = [...activeIds];
    episode.classicImmunityActiveIds = [...activeIds];
    if (!activeIds.length) return;

    const preliminaryBottomIds = classicImmunityPreliminaryBottomIds(episode, participants);
    info.preSaveBottomIds = [...preliminaryBottomIds];

    let remainingBottomIds = [...preliminaryBottomIds];
    const activeKeys = new Set(activeIds.map((id) => normalizeContestantId(id)));
    const savedIds = [];

    for (const bottomId of preliminaryBottomIds) {
      if (remainingBottomIds.length <= 2) break;
      if (!activeKeys.has(normalizeContestantId(bottomId))) continue;
      savedIds.push(bottomId);
      remainingBottomIds = remainingBottomIds.filter(
        (id) => normalizeContestantId(id) !== normalizeContestantId(bottomId)
      );
    }

    if (!savedIds.length) return;

    info.savedIds = [...savedIds];
    info.savedId = savedIds[0];
    info.used = true;
    episode.classicImmunitySavedIds = [...savedIds];
    episode.classicImmunitySavedId = savedIds[0];

    const finalBottomIds = (episode.allStarsLegacy || episode.allStarsAssassin)
      ? applyClassicImmunityToAllStars(episode, participants, savedIds)
      : applyClassicImmunityToStandardJudging(episode, participants, savedIds, preliminaryBottomIds);

    info.finalBottomIds = [...finalBottomIds];
  }

  function classicImmunityWinnerIdsForEpisode(episode) {
    if (!episode?.maxiChallenge) return [];

    if (episode.allStarsAssassin) {
      return episode.assassinJudging?.topAllStarId ? [episode.assassinJudging.topAllStarId] : [];
    }

    if (episode.thailandFormat) {
      return [...(episode.maxiChallenge?.thailand?.runwayWinnerIds || [])];
    }

    if (
      episode.topLipSync?.purpose === "win" &&
      Array.isArray(episode.topLipSync?.winnerIds)
    ) {
      return [...episode.topLipSync.winnerIds];
    }
    if (
      episode.lipSync?.purpose === "win" &&
      Array.isArray(episode.lipSync?.winnerIds)
    ) {
      return [...episode.lipSync.winnerIds];
    }

    if (
      episode.allStarsLegacy &&
      episode.lipSync?.purpose === "legacy" &&
      Array.isArray(episode.lipSync?.winnerIds)
    ) {
      return [...episode.lipSync.winnerIds];
    }

    return Object.entries(episode.maxiChallenge?.placements || {})
      .filter(([, placement]) => String(placement || "").trim() === "WIN")
      .map(([id]) => id);
  }

  function awardClassicImmunityForEpisode(episode, participants, originalCastSize, activeCastSize) {
    if (!classicImmunitySupportedForEpisode(episode)) return;
    const info = classicImmunityData(episode);
    const cutoffCastSize = classicImmunityAwardCutoff(originalCastSize);
    const castSizeAtChallenge = Math.max(
      0,
      Math.floor(Number(activeCastSize) || 0)
    );

    info.awardCutoffCastSize = cutoffCastSize;
    info.castSizeAtChallenge = castSizeAtChallenge;
    info.awardedIds = [];
    episode.classicImmunityAwardedIds = [];

    if (castSizeAtChallenge < cutoffCastSize) return;

    const winnerIds = uniqueValidParticipantIds(classicImmunityWinnerIdsForEpisode(episode), participants);
    if (winnerIds.length !== 1) return;

    info.awardedIds = [winnerIds[0]];
    info.protectsNextChallenge = true;
    episode.classicImmunityAwardedIds = [winnerIds[0]];
  }

  function classicImmunityAwardedTo(episode, queenId) {
    return classicImmunityContainsId(
      episode?.classicImmunity?.awardedIds || episode?.classicImmunityAwardedIds || [],
      queenId
    );
  }

  function classicImmunitySavedQueenId(episode) {
    return episode?.classicImmunity?.savedId || episode?.classicImmunitySavedId || null;
  }

  function classicImmunitySavedQueenIds(episode) {
    const ids = episode?.classicImmunity?.savedIds || episode?.classicImmunitySavedIds || [];
    if (ids.length) return [...ids];
    const single = classicImmunitySavedQueenId(episode);
    return single ? [single] : [];
  }

  function isThailandFormat() {
    const format = String(state.seasonSetup?.eliminationFormat || "").toLowerCase();
    return format === "thailand" || format === "thailand-format" || format === "thailand format";
  }

  function syncThailandFormatState() {
    const enabled = isThailandFormat();
    const premiereSelect = document.querySelector('#premiereFormat');
    state.seasonSetup.thailand = enabled;
    window.thailandFormat = enabled;

    if (enabled) {
      state.seasonSetup.premiereFormat = "regular";
      if (premiereSelect) {
        premiereSelect.value = "regular";
        premiereSelect.disabled = true;
      }
      resetPremiereSetupForFormat("regular");
    } else if (!isTeamsFormat()) {
      if (premiereSelect) premiereSelect.disabled = false;
    }
  }

  function syncTeamsFormatState() {
    const enabled = isTeamsFormat();
    const premiereSelect = document.querySelector('#premiereFormat');
    const finaleSelect = document.querySelector('#finaleFormat');

    if (enabled) {
      state.seasonSetup.premiereFormat = "regular";
      state.seasonSetup.finaleFormat = "regular";
      if (premiereSelect) {
        premiereSelect.value = "regular";
        premiereSelect.disabled = true;
      }
      if (finaleSelect) {
        finaleSelect.value = "regular";
        finaleSelect.disabled = true;
      }
      resetPremiereSetupForFormat("regular");
    } else {
      if (premiereSelect) premiereSelect.disabled = false;
      if (finaleSelect && !isAllWinnersSeason() && !isAllStars9Season()) finaleSelect.disabled = false;
    }
    syncLipSyncForTheCrownState();
  }

  function syncAssassinFormatState() {
    const enabled = isLipSyncAssassinFormat();
    state.seasonSetup.lipsync_assassin = enabled;
    window.lipsync_assassin = enabled;
    if (els.assassinFilterControl) els.assassinFilterControl.hidden = !enabled;
    renderAssassinFilterSummary();
  }

  function syncAllWinnersFormatState() {
    const enabled = isAllWinnersSeason();
    const as9 = isAllStars9Season();
    state.seasonSetup.all_winners = enabled;
    state.seasonSetup.all_stars_9 = as9;
    window.all_winners = enabled;
    window.all_stars_9 = as9;

    const finaleSelect = document.querySelector('#finaleFormat');
    const awardInputs = [...document.querySelectorAll('[data-setup-check="award"]')];
    if (enabled) {
      state.seasonSetup.finaleFormat = "lftc";
      state.seasonSetup.awards = new Set();
      if (finaleSelect) { finaleSelect.value = "lftc"; finaleSelect.disabled = true; }
      awardInputs.forEach((input) => { input.checked = false; input.disabled = true; input.closest('.setup-check')?.classList.add('setup-check--disabled'); });
    } else if (as9) {
      state.seasonSetup.finaleFormat = "regular";
      if (finaleSelect) { finaleSelect.value = "regular"; finaleSelect.disabled = true; }
      awardInputs.forEach((input) => { input.disabled = false; input.closest('.setup-check')?.classList.remove('setup-check--disabled'); });
    } else {
      if (finaleSelect) finaleSelect.disabled = false;
      awardInputs.forEach((input) => { input.disabled = false; input.closest('.setup-check')?.classList.remove('setup-check--disabled'); });
    }
    syncLipSyncForTheCrownState();
  }

  function syncFinaleCutOptions() {
    const finaleSelect = document.querySelector('#finaleFormat');
    if (!finaleSelect) return;

    const finalistCount = Math.max(2, Number(state.finalistsSize) || 3);
    const cutTop2 = finaleSelect.querySelector('option[value="cut-top2"]');
    const cutTop3 = finaleSelect.querySelector('option[value="cut-top3"]');

    if (cutTop2) cutTop2.disabled = finalistCount <= 2;
    if (cutTop3) cutTop3.disabled = finalistCount <= 3;

    const current = String(state.seasonSetup?.finaleFormat || "regular").toLowerCase();
    const invalidCut =
      (current === "cut-top2" && finalistCount <= 2) ||
      (current === "cut-top3" && finalistCount <= 3);

    if (invalidCut) {
      state.seasonSetup.finaleFormat = "regular";
      finaleSelect.value = "regular";
      syncLipSyncForTheCrownState();
    }
  }

  function syncFinalistsSizeForFormat() {
    if (!els.finalistsSize) return;
    const allWinners = isAllWinnersSeason();
    const allStars9 = isAllStars9Season();
    const lftc = isLipSyncForTheCrownFinale();
    const lftf = isLipSyncForTheFinaleFinale();
    const jury = isJuryFinale();
    const cuntTest = isCuntTestFinale();
    const teams = isTeamsFormat();
    const hellbound = isHellboundShowdownFormat();
    const titans = isDragulaTitansFormat();
    const minimum = titans ? (hellbound ? 4 : 3) : ((allWinners || lftc || lftf || cuntTest || teams || hellbound) ? 4 : ((allStars9 || isAllStarsLegacyFormat() || jury) ? 3 : 2));
    const maximum = titans ? minimum : (hellbound && Number(state.castSize || 0) < 7 ? 4 : 5);
    els.finalistsSize.min = String(minimum);
    els.finalistsSize.max = String(maximum);
    els.finalistsSize.disabled = allWinners || allStars9 || lftc || lftf || cuntTest || teams || titans;

    const current = titans
      ? minimum
      : ((allWinners || lftc || lftf || cuntTest || teams)
        ? 4
        : (allStars9 ? 3 : Math.max(minimum, Math.min(maximum, Number(state.finalistsSize) || 3))));
    state.finalistsSize = current;
    els.finalistsSize.value = String(current);
    els.finalistsSizeValue.textContent = String(current);
    setRangeFill(els.finalistsSize);
    syncFinaleCutOptions();
    syncMusicVideoSemifinalAvailability();
  }

  function challengeRiggoryDisabled() {
    const controls = state.seasonSetup?.productionControls;
    return Boolean(
      state.seasonSetup?.disableChallengeRiggory ||
      state.seasonSetup?.riggory ||
      controls?.has?.("disable-challenge-riggory") ||
      controls?.has?.("riggory") ||
      controls?.has?.("riggory-challenge")
    );
  }

  function allStarsLegacyPerformanceScore(maxi, id) {
    const key = normalizeContestantId(id);
    const item = (maxi?.performances || []).find(
      (performance) => normalizeContestantId(performance.id) === key
    );
    return Number(item?.score ?? 999);
  }

  function allStarsLegacyRunwayModifier(maxi, id) {
    const key = normalizeContestantId(id);
    const item = (maxi?.runwayResults || []).find(
      (result) => normalizeContestantId(result.id) === key
    );
    return Number(item?.modifier || 0);
  }

  function allStarsLegacyPreliminaryPools(maxi, participants) {
    const sorted = [...(maxi?.performances || [])]
      .filter((performance) => participants.some(
        (queen) => normalizeContestantId(queen.id) === normalizeContestantId(performance.id)
      ))
      .sort((a, b) => Number(a.score) - Number(b.score));
    const count = sorted.length;
    const ids = sorted.map((item) => item.id);
    const score = (id) => allStarsLegacyPerformanceScore(maxi, id);

    let top = [];
    let bottom = [];

    if (count >= 14) {
      top = ids.slice(0, 4);
      bottom = ids.slice(-4);
    } else if (count >= 6) {
      top = ids.slice(0, 3);
      bottom = ids.slice(-3);
    } else if (count === 5) {
      top = ids.slice(0, 2);
      bottom = ids.slice(-2);
      const middle = ids[2];
      if (middle) {
        if (score(middle) < 16) top.push(middle);
        else bottom.unshift(middle);
      }
    } else if (count === 4) {
      top = ids.slice(0, 2);
      bottom = ids.slice(-2);
    } else if (count === 3) {
      top = ids.slice(0, 2);
      bottom = ids.slice(-1);
    } else if (count === 2) {
      top = [...ids];
      bottom = [];
    } else {
      top = [...ids];
      bottom = [];
    }

    if (count >= 6) {
      if (top.length >= 3 && score(top[top.length - 1]) > 18) {
        top.pop();
      }

      const initialTopTarget = count >= 14 ? 4 : 3;
      const nextTopCandidate = ids[initialTopTarget];
      if (nextTopCandidate && score(nextTopCandidate) < 12) {
        bottom = bottom.filter(
          (id) => normalizeContestantId(id) !== normalizeContestantId(nextTopCandidate)
        );
        if (!top.some(
          (id) => normalizeContestantId(id) === normalizeContestantId(nextTopCandidate)
        )) {
          top.push(nextTopCandidate);
        }
      }

      bottom = bottom.sort((a, b) => score(a) - score(b));
      if (bottom.length > 2 && score(bottom[0]) < 16) {
        bottom.shift();
      }
    }

    const topKeys = new Set(top.map((id) => normalizeContestantId(id)));
    bottom = bottom.filter((id) => !topKeys.has(normalizeContestantId(id)));

    if (count >= 2 && top.length < 2) {
      ids.forEach((id) => {
        if (top.length >= 2) return;
        if (bottom.some((bottomId) => normalizeContestantId(bottomId) === normalizeContestantId(id))) return;
        if (!top.some((topId) => normalizeContestantId(topId) === normalizeContestantId(id))) top.push(id);
      });
    }

    return {
      topIds: uniqueValidParticipantIds(top, participants),
      bottomIds: uniqueValidParticipantIds(bottom, participants),
    };
  }

  function allWinnersRelationshipTarget(sourceId, candidateIds, mode = "worst") {
    const ids = [...(candidateIds || [])].filter(Boolean);
    if (!ids.length) return null;
    const scored = ids.map((id) => ({
      id,
      score: Number(getRelationshipScore(sourceId, id) || 0),
    }));
    const targetScore = mode === "best"
      ? Math.max(...scored.map((item) => item.score))
      : Math.min(...scored.map((item) => item.score));
    const tied = scored.filter((item) => item.score === targetScore).map((item) => item.id);
    return pickRandom(tied) || pickRandom(ids) || null;
  }

  function allWinnersAppendBlockPlacement(placements, targetId) {
    if (!placements || !targetId) return;
    const key = Object.keys(placements).find(
      (id) => normalizeContestantId(id) === normalizeContestantId(targetId)
    ) || targetId;
    const base = String(placements[key] || "SAFE");
    placements[key] = `${base}+BLOCKED`;
  }

  function applyAllWinnersJudging(episode, participants, priorEpisodes, seasonState) {
    const maxi = episode?.maxiChallenge;
    if (!maxi) return;

    const performanceScore = (id) => allStarsLegacyPerformanceScore(maxi, id);
    const ordered = [...(maxi.performances || [])]
      .filter((performance) => participants.some(
        (queen) => normalizeContestantId(queen.id) === normalizeContestantId(performance.id)
      ))
      .sort((a, b) => Number(a.score) - Number(b.score));

    const topGroupSize = participants.length <= 10 ? 4 : 5;
    const preliminaryTopIds = ordered.slice(0, Math.min(topGroupSize, ordered.length)).map((item) => item.id);
    const disableChallengeRiggory = challengeRiggoryDisabled();
    const topAdjusted = preliminaryTopIds
      .map((id) => {
        const runwayScore = allStarsLegacyRunwayModifier(maxi, id);
        const history = competitiveReputationForQueen(id, priorEpisodes || []);
        const adjustedScore = disableChallengeRiggory
          ? performanceScore(id) - runwayScore
          : performanceScore(id) - (runwayScore - history.favoritism);
        return { id, adjustedScore, runwayScore, favoritism: history.favoritism };
      })
      .sort((a, b) => a.adjustedScore - b.adjustedScore);

    const top2Ids = topAdjusted.slice(0, 2).map((item) => item.id);
    const highIds = topAdjusted.slice(2).map((item) => item.id);
    const topKeys = new Set(preliminaryTopIds.map((id) => normalizeContestantId(id)));
    const safeIds = participants
      .map((queen) => queen.id)
      .filter((id) => !topKeys.has(normalizeContestantId(id)));

    const placements = {};
    participants.forEach((queen) => { placements[queen.id] = "SAFE"; });
    top2Ids.forEach((id) => { placements[id] = "TOP2"; });
    highIds.forEach((id) => { placements[id] = "HIGH"; });

    const blockedAtStartIds = [...new Map(
      (seasonState.blockedIds || []).map((id) => [normalizeContestantId(id), id])
    ).values()];
    const blockedKeys = new Set(blockedAtStartIds.map((id) => normalizeContestantId(id)));
    const isTalentShow = maxi.category === "talent_show";
    const talentShowEpisode = participants.length > 10 ? 14 : 11;
    const starValue = isTalentShow && episode.number === talentShowEpisode ? 3 : 1;
    const starAwards = [];
    const starDeltas = {};

    top2Ids.forEach((id) => {
      const blocked = blockedKeys.has(normalizeContestantId(id));
      const amount = blocked ? 0 : starValue;
      if (amount) seasonState.stars[id] = Number(seasonState.stars[id] || 0) + amount;
      starDeltas[id] = (starDeltas[id] || 0) + amount;
      const event = { episode: episode.number, kind: blocked ? "blocked" : "earned", amount, blocked };
      seasonState.starHistory[id] ||= [];
      seasonState.starHistory[id].push(event);
      starAwards.push({ id, amount, blocked });
    });

    seasonState.blockedIds = [];

    let starGiftTwist = false;
    if (!seasonState.giftingTwistUsed) {
      if (episode.number === 5) starGiftTwist = true;
      else if (episode.number < 5 && episode.number > 1 && randomIntInclusive(1, 100) <= 6) starGiftTwist = true;
      if (starGiftTwist) seasonState.giftingTwistUsed = true;
    }

    maxi.topPoolIds = [...preliminaryTopIds];
    maxi.bottomPoolIds = [];
    maxi.judgedIds = [...preliminaryTopIds];
    maxi.safeIds = [...safeIds];
    maxi.placements = placements;

    episode.allWinnersJudging = {
      version: 1,
      preliminaryTopIds,
      top2Ids,
      highIds,
      safeIds,
      blockedAtStartIds,
      starValue,
      starAwards,
      starGiftTwist,
      starDeltas,
      starsAfterJudging: structuredClone(seasonState.stars),
      topAdjusted,
      riggory: disableChallengeRiggory,
    };
  }

  function generateAllWinnersLipSyncAndPower({
    episode,
    participants,
    top2Ids,
    priorEpisodes,
    usedSongIds,
    seasonState,
  }) {
    const lipSync = generateTop2LipSyncForWin({
      episode,
      participants,
      top2Ids,
      priorEpisodes,
      usedSongIds,
      seasonFlags: {},
      neutralOnly: true,
      allowExactTieDoubleWin: true,
    });

    lipSync.allWinners = true;
    lipSync.purpose = "all-winners";
    lipSync.eliminatedIds = [];

    if (lipSync.resultType === "top2-double-win") {
      lipSync.trackResults = Object.fromEntries((lipSync.winnerIds || []).map((id) => [id, "WIN"]));
    } else if (lipSync.occurs) {
      lipSync.trackResults = {};
      (lipSync.winnerIds || []).forEach((id) => { lipSync.trackResults[id] = "WIN"; });
      (lipSync.loserIds || []).forEach((id) => { lipSync.trackResults[id] = "TOP2"; });
    }

    const topKeys = new Set((top2Ids || []).map((id) => normalizeContestantId(id)));
    const eligibleOtherIds = participants
      .map((queen) => queen.id)
      .filter((id) => !topKeys.has(normalizeContestantId(id)));

    const giftEvents = [];
    if (episode.allWinnersJudging?.starGiftTwist) {
      const giftDecision = rupaulStoredDecision(episode.number, "starGiftTargets");
      const giftTargets = giftDecision?.targets || {};
      (top2Ids || []).forEach((topId) => {
        const requested = eligibleOtherIds.find((id) => normalizeContestantId(id) === normalizeContestantId(giftTargets[topId]));
        const recipientId = requested || allWinnersRelationshipTarget(topId, eligibleOtherIds, "best") || pickRandom(eligibleOtherIds);
        if (!recipientId) return;
        seasonState.stars[recipientId] = Number(seasonState.stars[recipientId] || 0) + 1;
        seasonState.starHistory[recipientId] ||= [];
        seasonState.starHistory[recipientId].push({ episode: episode.number, kind: "gift", amount: 1, fromId: topId });
        episode.allWinnersJudging.starDeltas[recipientId] = (episode.allWinnersJudging.starDeltas[recipientId] || 0) + 1;
        giftEvents.push({ giverId: topId, recipientId, amount: 1 });
      });
    }

    const lateNoBlock = participants.length <= 10
      ? [10, 11].includes(episode.number)
      : [13, 14].includes(episode.number);
    const blockEvents = [];
    if (!lateNoBlock) {
      (lipSync.winnerIds || []).forEach((winnerId) => {
        const targetId = allWinnersRelationshipTarget(winnerId, eligibleOtherIds, "worst") || pickRandom(eligibleOtherIds);
        if (!targetId) return;
        blockEvents.push({ winnerId, targetId });
        allWinnersAppendBlockPlacement(episode.maxiChallenge?.placements, targetId);
        if (!seasonState.blockedIds.some(
          (id) => normalizeContestantId(id) === normalizeContestantId(targetId)
        )) seasonState.blockedIds.push(targetId);
      });
    }

    episode.allWinnersPower = {
      version: 1,
      noBlock: lateNoBlock,
      blockEvents,
      giftEvents,
      blockedForNextEpisodeIds: [...seasonState.blockedIds],
      starsAfterEpisode: structuredClone(seasonState.stars),
    };
    episode.allWinnersJudging.giftEvents = giftEvents;
    episode.allWinnersJudging.starsAfterEpisode = structuredClone(seasonState.stars);
    return lipSync;
  }

  function allStars9AppendCutPlacement(placements, targetId) {
    if (!placements || !targetId) return;
    const key = Object.keys(placements).find(
      (id) => normalizeContestantId(id) === normalizeContestantId(targetId)
    ) || targetId;
    const base = String(placements[key] || "SAFE");
    placements[key] = `${base}+CUT`;
  }

  function generateAllStars9DoubleDiamond(participants, seasonState, episodeNumber) {
    const contestantIds = (participants || []).map((contestant) => contestant.id).filter(Boolean);
    const voteRounds = [];
    let eligibleIds = [...contestantIds];
    let winnerId = null;

    for (let round = 1; round <= 6 && eligibleIds.length > 1; round += 1) {
      const votes = [];
      const totals = Object.fromEntries(eligibleIds.map((id) => [id, 0]));
      const manualRound = rupaulStoredDecision(episodeNumber, `doubleDiamondRound${round}Votes`);
      const manualTargets = manualRound?.targets || {};
      contestantIds.forEach((voterId) => {
        const targets = eligibleIds.filter(
          (id) => normalizeContestantId(id) !== normalizeContestantId(voterId)
        );
        if (!targets.length) return;
        const requested = targets.find((id) => normalizeContestantId(id) === normalizeContestantId(manualTargets[voterId]));
        const targetId = requested || allWinnersRelationshipTarget(voterId, targets, "best") || pickRandom(targets);
        if (!targetId) return;
        totals[targetId] = Number(totals[targetId] || 0) + 1;
        votes.push({ voterId, targetId });
      });

      const highest = Math.max(0, ...Object.values(totals).map(Number));
      const tiedIds = eligibleIds.filter((id) => Number(totals[id] || 0) === highest);
      voteRounds.push({ round, eligibleIds: [...eligibleIds], votes, totals, tiedIds: [...tiedIds] });
      if (tiedIds.length === 1) {
        winnerId = tiedIds[0];
        break;
      }
      eligibleIds = tiedIds.length ? tiedIds : eligibleIds;
    }

    if (!winnerId) winnerId = pickRandom(eligibleIds) || pickRandom(contestantIds) || null;
    const badgesBefore = winnerId ? Number(seasonState.stars[winnerId] || 0) : 0;
    const badgesAfter = badgesBefore * 2;
    const badgeDelta = badgesAfter - badgesBefore;
    if (winnerId) {
      seasonState.stars[winnerId] = badgesAfter;
      seasonState.starHistory[winnerId] ||= [];
      seasonState.starHistory[winnerId].push({
        episode: episodeNumber,
        kind: "double-diamond",
        amount: badgeDelta,
        multiplier: 2,
        before: badgesBefore,
        after: badgesAfter,
      });
    }

    return {
      version: 1,
      voteRounds,
      winnerId,
      badgesBefore,
      badgesAfter,
      badgeDelta,
      revealed: false,
    };
  }

  function applyAllStars9Judging(episode, participants, priorEpisodes, seasonState) {
    const maxi = episode?.maxiChallenge;
    if (!maxi) return;

    const performanceScore = (id) => allStarsLegacyPerformanceScore(maxi, id);
    const ordered = [...(maxi.performances || [])]
      .filter((performance) => participants.some(
        (contestant) => normalizeContestantId(contestant.id) === normalizeContestantId(performance.id)
      ))
      .sort((a, b) => Number(a.score) - Number(b.score));

    const topGroupSize = participants.length <= 10 ? 4 : 5;
    const preliminaryTopIds = ordered.slice(0, Math.min(topGroupSize, ordered.length)).map((item) => item.id);
    const disableChallengeRiggory = challengeRiggoryDisabled();
    const topAdjusted = preliminaryTopIds
      .map((id) => {
        const runwayScore = allStarsLegacyRunwayModifier(maxi, id);
        const history = competitiveReputationForQueen(id, priorEpisodes || []);
        const adjustedScore = disableChallengeRiggory
          ? performanceScore(id) - runwayScore
          : performanceScore(id) - (runwayScore - history.favoritism);
        return { id, adjustedScore, runwayScore, favoritism: history.favoritism };
      })
      .sort((a, b) => a.adjustedScore - b.adjustedScore);

    const top2Ids = topAdjusted.slice(0, 2).map((item) => item.id);
    const highIds = topAdjusted.slice(2).map((item) => item.id);
    const topKeys = new Set(preliminaryTopIds.map((id) => normalizeContestantId(id)));
    const safeIds = participants.map((contestant) => contestant.id)
      .filter((id) => !topKeys.has(normalizeContestantId(id)));

    const placements = {};
    participants.forEach((contestant) => { placements[contestant.id] = "SAFE"; });
    top2Ids.forEach((id) => { placements[id] = "TOP2"; });
    highIds.forEach((id) => { placements[id] = "HIGH"; });

    const cutAtStartIds = [...new Map(
      (seasonState.blockedIds || []).map((id) => [normalizeContestantId(id), id])
    ).values()];
    const cutKeys = new Set(cutAtStartIds.map((id) => normalizeContestantId(id)));
    const starValue = maxi.category === "talent_show" && episode.number === episode.allStars9CompetitiveCount ? 3 : 1;
    const starAwards = [];
    const starDeltas = {};

    top2Ids.forEach((id) => {
      const blocked = cutKeys.has(normalizeContestantId(id));
      const amount = blocked ? 0 : starValue;
      if (amount) seasonState.stars[id] = Number(seasonState.stars[id] || 0) + amount;
      starDeltas[id] = (starDeltas[id] || 0) + amount;
      seasonState.starHistory[id] ||= [];
      seasonState.starHistory[id].push({ episode: episode.number, kind: blocked ? "cut" : "earned", amount, blocked });
      starAwards.push({ id, amount, blocked });
    });

    seasonState.blockedIds = [];

    let starGiftTwist = false;
    if (!seasonState.giftingTwistUsed && episode.number < episode.allStars9CompetitiveCount) {
      if (episode.number === 5) starGiftTwist = true;
      else if (episode.number > 1 && episode.number < 5 && randomIntInclusive(1, 100) <= 6) starGiftTwist = true;
      if (starGiftTwist) seasonState.giftingTwistUsed = true;
    }

    maxi.topPoolIds = [...preliminaryTopIds];
    maxi.bottomPoolIds = [];
    maxi.judgedIds = [...preliminaryTopIds];
    maxi.safeIds = [...safeIds];
    maxi.placements = placements;

    episode.allStars9Judging = {
      version: 1,
      preliminaryTopIds,
      top2Ids,
      highIds,
      safeIds,
      blockedAtStartIds: cutAtStartIds,
      starValue,
      starAwards,
      starGiftTwist,
      starDeltas,
      starsAfterJudging: structuredClone(seasonState.stars),
      topAdjusted,
      riggory: disableChallengeRiggory,
    };
  }

