  function dragulaNormalizedFloorCategory(type) {
    const raw = String(type || "runway").toLowerCase();
    const map = {
      lip_sync: "lipsync",
      photo_shoot: "runway",
      music_bands: "girl_group",
      music_video: "rumix",
      musical: "rusical",
    };
    return map[raw] || raw;
  }

  function dragulaFloorShowTypeLabel(type) {
    const raw = String(type || "runway").toLowerCase();
    const labels = {
      runway: "Runway",
      design: "Design",
      performance: "Performance",
      acting: "Acting",
      lip_sync: "Lip Sync",
      photo_shoot: "Photo Shoot",
      improv: "Improv",
      dance: "Dance",
      music_bands: "Music Bands",
      musical: "Musical",
      music_video: "Music Video",
      ads: "Ads",
    };
    return labels[raw] || raw.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
  }

  function dragulaMonsterCopy(value) {
    return String(value || "")
      .replace(/\bcontestants\b/gi, "monsters")
      .replace(/\bcontestant\b/gi, "monster")
      .replace(/\bqueens\b/gi, "monsters")
      .replace(/\bqueen\b/gi, "monster");
  }

  function applyDragulaVisibleTerminology(root) {
    if (!root || typeof document === "undefined" || typeof NodeFilter === "undefined") return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node = walker.nextNode();
    while (node) {
      node.nodeValue = String(node.nodeValue || "")
        .replace(/\bContestants\b/g, "Monsters")
        .replace(/\bcontestants\b/g, "monsters")
        .replace(/\bContestant\b/g, "Monster")
        .replace(/\bcontestant\b/g, "monster");
      node = walker.nextNode();
    }
  }

  function bouletsChosenId(value) {
    if (Array.isArray(value)) return value[0] || null;
    if (value && typeof value === "object") {
      if (Array.isArray(value.winnerIds)) return value.winnerIds[0] || null;
      if (Array.isArray(value.eliminatedIds)) return value.eliminatedIds[0] || null;
      return value.id || value.targetId || value.winnerId || null;
    }
    return value || null;
  }

  function bouletsCatalogChoice(items, choice, fallback = null) {
    if (!choice) return fallback;
    const id = typeof choice === "object" ? (choice.id || choice.name) : choice;
    return structuredClone((items || []).find((item) => item?.id === id || item?.name === id) || fallback);
  }

  function applyBouletsPlacementChoice(floorShow, participants, choice, { resurrection = false } = {}) {
    if (!floorShow || !choice) return floorShow;
    const source = choice.assignments && typeof choice.assignments === "object" ? choice.assignments : choice;
    if (!source || typeof source !== "object") return floorShow;
    const ids = (participants || []).map((monster) => monster.id);
    const placements = {};
    ids.forEach((id) => {
      const key = Object.keys(source).find((candidate) => normalizeContestantId(candidate) === normalizeContestantId(id));
      placements[id] = String(key ? source[key] : (floorShow.placements?.[id] || "SAFE")).trim() || "SAFE";
    });

    const normalizePools = () => {
      const bottomIds = ids.filter((id) => /^BTM\d*$/.test(placements[id]));
      if (bottomIds.length) {
        const bottomLabel = `BTM${Math.max(2, bottomIds.length)}`;
        bottomIds.forEach((id) => { placements[id] = bottomLabel; });
      }
      const winIds = ids.filter((id) => placements[id] === "WIN");
      const highIds = ids.filter((id) => placements[id] === "HIGH" || placements[id] === "HIGH TEAM");
      const lowIds = ids.filter((id) => placements[id] === "LOW");
      const safeIds = ids.filter((id) => placements[id] === "SAFE");
      floorShow.placements = placements;
      floorShow.topPoolIds = [...winIds, ...highIds];
      floorShow.bottomPoolIds = [...bottomIds];
      floorShow.lowIds = [...lowIds];
      floorShow.judgedIds = ids.filter((id) => placements[id] !== "SAFE");
      floorShow.safeIds = [...safeIds];
      floorShow.hesitantWinnerBottomId = null;
      return { bottomIds, winIds, highIds, lowIds, safeIds };
    };

    let pools = normalizePools();
    const groups = Array.isArray(floorShow.groups)
      ? floorShow.groups.filter((group) => Array.isArray(group?.memberIds) && group.memberIds.length)
      : [];

    if (groups.length && floorShow.judgedAsTeams) {
      const topGroups = groups.filter((group) => group.memberIds.some((id) => ["WIN", "HIGH", "HIGH TEAM"].includes(placements[id])));
      const bottomGroups = groups.filter((group) => group.memberIds.some((id) => placements[id] === "LOW" || /^BTM/.test(placements[id])));
      const topGroup = topGroups.find((group) => group.memberIds.some((id) => placements[id] === "WIN")) || topGroups[0] || null;
      const bottomGroup = [...bottomGroups].sort((a, b) => {
        const danger = (group) => group.memberIds.reduce((score, id) => score + (/^BTM/.test(placements[id]) ? 10 : placements[id] === "LOW" ? 1 : 0), 0);
        return danger(b) - danger(a);
      })[0] || null;
      const topKeys = new Set((topGroup?.memberIds || []).map(normalizeContestantId));
      const bottomKeys = new Set((bottomGroup?.memberIds || []).map(normalizeContestantId));

      groups.forEach((group) => {
        group.memberIds.forEach((id) => {
          const key = normalizeContestantId(id);
          if (topKeys.has(key)) {
            if (placements[id] !== "WIN") placements[id] = "HIGH TEAM";
          } else if (bottomKeys.has(key)) {
            if (!/^BTM/.test(placements[id])) placements[id] = placements[id] === "LOW" ? "LOW" : "SAFE";
          } else {
            placements[id] = "SAFE";
          }
        });
      });
      let lowSeen = false;
      bottomGroup?.memberIds.forEach((id) => {
        if (placements[id] === "LOW") {
          if (lowSeen) placements[id] = "SAFE";
          lowSeen = true;
        }
      });
      pools = normalizePools();
      floorShow.topPoolIds = [...(topGroup?.memberIds || [])];
      floorShow.topTeamName = topGroup?.name || floorShow.topTeamName || "";
      floorShow.bottomTeamName = bottomGroup?.name || floorShow.bottomTeamName || "";
      floorShow.safeTeamNames = groups
        .filter((group) => group !== topGroup && group !== bottomGroup)
        .map((group) => group.name)
        .filter(Boolean);
      floorShow.judgedIds = ids.filter((id) => topKeys.has(normalizeContestantId(id)) || bottomKeys.has(normalizeContestantId(id)));
      floorShow.safeIds = ids.filter((id) => !topKeys.has(normalizeContestantId(id)) && !bottomKeys.has(normalizeContestantId(id)));
    } else if (groups.length && floorShow.judgedAsPairs) {
      const tierFor = (id) => {
        const value = String(placements[id] || "SAFE");
        if (["WIN", "HIGH", "HIGH TEAM"].includes(value)) return "top";
        if (value === "LOW" || /^BTM/.test(value)) return "bottom";
        return "safe";
      };
      const topGroups = groups.filter((group) => group.memberIds.some((id) => tierFor(id) === "top"));
      const bottomGroups = groups.filter((group) => group.memberIds.some((id) => tierFor(id) === "bottom"));
      const topKeys = new Set(topGroups.flatMap((group) => group.memberIds).map(normalizeContestantId));
      const bottomKeys = new Set(bottomGroups.flatMap((group) => group.memberIds).map(normalizeContestantId));

      groups.forEach((group) => {
        const hasWinner = group.memberIds.some((id) => placements[id] === "WIN");
        const isTop = topGroups.includes(group);
        const isBottom = bottomGroups.includes(group);
        group.memberIds.forEach((id) => {
          if (isTop) {
            if (hasWinner) {

              placements[id] = placements[id] === "WIN" ? "WIN" : "HIGH";
            } else placements[id] = "HIGH";
          } else if (isBottom) {
            if (!/^BTM/.test(placements[id])) placements[id] = "LOW";
          } else {
            placements[id] = "SAFE";
          }
        });
      });
      pools = normalizePools();
      floorShow.topPairNames = topGroups.map((group) => group.name).filter(Boolean);
      floorShow.bottomPairNames = bottomGroups.map((group) => group.name).filter(Boolean);
      floorShow.safePairNames = groups.filter((group) => !topGroups.includes(group) && !bottomGroups.includes(group)).map((group) => group.name).filter(Boolean);
      floorShow.topPoolIds = ids.filter((id) => topKeys.has(normalizeContestantId(id)));
      floorShow.judgedIds = ids.filter((id) => topKeys.has(normalizeContestantId(id)) || bottomKeys.has(normalizeContestantId(id)));
      floorShow.safeIds = ids.filter((id) => !topKeys.has(normalizeContestantId(id)) && !bottomKeys.has(normalizeContestantId(id)));
    }

    if (resurrection) {
      const winIds = ids.filter((id) => placements[id] === "WIN");
      const highIds = ids.filter((id) => placements[id] === "HIGH" || placements[id] === "HIGH TEAM");
      const lowIds = ids.filter((id) => placements[id] === "LOW");
      const safeIds = ids.filter((id) => placements[id] === "SAFE");
      floorShow.resurrectionCritiques = {
        winnerId: winIds[0] || null,
        positiveIds: [...highIds],
        negativeIds: [...lowIds],
        safeIds: [...safeIds],
      };
      floorShow.bottomPoolIds = [];
    }
    return floorShow;
  }

  function applyBouletsJudgingUnitChoice(floorShow, choice) {
    if (!floorShow || !choice) return floorShow;
    const collaborative = ["pairs", "2_teams", "3_teams"].includes(String(floorShow.format || "solo"));
    if (!collaborative) return floorShow;
    const group = String(choice) === "group";
    floorShow.judgedAsPairs = group && floorShow.format === "pairs" && (floorShow.participantIds || []).length <= 8;
    floorShow.judgedAsTeams = group && ["2_teams", "3_teams"].includes(floorShow.format);
    floorShow.pairJudgingMode = floorShow.format === "pairs" ? (floorShow.judgedAsPairs ? "pairs" : "individual") : "";
    return floorShow;
  }

  function applyBouletsVoteOffVoting(voting, participants, floorShow, keyDecision, choice) {
    const manual = choice?.targets || choice;
    if (!voting || !manual || typeof manual !== "object") return voting;
    const winnerId = voting.winnerId || floorShow?.voteOffWinnerId || null;
    const winnerKey = normalizeContestantId(winnerId);
    const participantIds = (participants || []).map((monster) => monster.id);
    const eligibleIds = participantIds.filter((id) => normalizeContestantId(id) !== winnerKey);
    const eligibleKeys = new Map(eligibleIds.map((id) => [normalizeContestantId(id), id]));
    const totals = new Map(eligibleIds.map((id) => [normalizeContestantId(id), { id, votes: 0, tieBreaker: Math.random() }]));
    const ballots = participantIds.map((voterId) => {
      const entryKey = Object.keys(manual).find((candidate) => normalizeContestantId(candidate) === normalizeContestantId(voterId));
      const requested = Array.isArray(entryKey ? manual[entryKey] : null) ? manual[entryKey] : [];
      const seen = new Set();
      const targetIds = requested.map((id) => eligibleKeys.get(normalizeContestantId(id))).filter((id) => {
        const key = normalizeContestantId(id);
        if (!id || seen.has(key) || key === normalizeContestantId(voterId)) return false;
        seen.add(key);
        return true;
      }).slice(0, Math.min(2, eligibleIds.length));
      targetIds.forEach((id) => {
        const row = totals.get(normalizeContestantId(id));
        if (row) row.votes += 1;
      });
      return { voterId, targetIds };
    });
    const sortedTotals = [...totals.values()].sort((a, b) => b.votes - a.votes || a.tieBreaker - b.tieBreaker);
    const savedKey = normalizeContestantId(keyDecision?.savedId);
    const eligibleForBottom = sortedTotals.filter((item) => !savedKey || normalizeContestantId(item.id) !== savedKey);
    let bottomIds = eligibleForBottom.slice(0, 2).map((item) => item.id);
    if (keyDecision?.nominatedId) {
      const nominatedKey = normalizeContestantId(keyDecision.nominatedId);
      const second = eligibleForBottom.find((item) => normalizeContestantId(item.id) !== nominatedKey)?.id || null;
      bottomIds = [keyDecision.nominatedId, second].filter(Boolean);
    }
    voting.ballots = ballots;
    voting.totals = sortedTotals.map(({ id, votes }) => ({ id, votes }));
    voting.bottomIds = bottomIds;
    return voting;
  }

  function applyBouletsExterminationOutcome(episode, floorShow, extermination, choice) {
    if (!extermination || extermination.abnormalExit || !Array.isArray(choice)) return extermination;
    const bottomIds = [...(extermination.bottomIds || floorShow?.bottomPoolIds || [])];
    const immuneKeys = new Set(directorProtectedContestantIds(episode));
    const allowed = new Map(bottomIds.filter((id) => !immuneKeys.has(normalizeContestantId(id)))
      .map((id) => [normalizeContestantId(id), id]));
    const eliminatedIds = [...new Set(choice.map((id) => allowed.get(normalizeContestantId(id))).filter(Boolean))];
    const eliminatedKeys = new Set(eliminatedIds.map(normalizeContestantId));
    extermination.eliminatedIds = eliminatedIds;
    extermination.survivorIds = bottomIds.filter((id) => !eliminatedKeys.has(normalizeContestantId(id)));
    extermination.decisionMethod = "boulets";
    if (extermination.resultType !== "ghostly-gallows") {
      extermination.resultType = eliminatedIds.length === 0 ? "double-save" : (eliminatedIds.length > 1 ? "double-elimination" : "normal");
    }
    const bottomLabel = dragulaBottomTrackLabel(bottomIds);
    const trackResults = {};
    bottomIds.forEach((id) => {
      const eliminated = eliminatedKeys.has(normalizeContestantId(id));
      if (episode?.dragulaVoteOff) {
        trackResults[id] = dragulaVoteOffCombinedTrackResult(floorShow?.placements?.[id] || "SAFE", { eliminated, bottomCount: bottomIds.length });
      } else if (extermination.resultType === "ghostly-gallows") {
        trackResults[id] = eliminated ? "ELIM" : (floorShow?.placements?.[id] || bottomLabel);
      } else {
        const keyNominated = Boolean(episode?.keyOfLifeDeath?.nominatedId && normalizeContestantId(episode.keyOfLifeDeath.nominatedId) === normalizeContestantId(id));
        trackResults[id] = eliminated ? "EXT" : (keyNominated ? bottomLabel : (floorShow?.placements?.[id] || bottomLabel));
      }
    });
    extermination.trackResults = trackResults;
    extermination.resultRevealed = false;
    return extermination;
  }

  function applyBouletsHellboundWinner(showdown, choice) {
    if (!showdown) return showdown;
    const id = bouletsChosenId(choice);
    const winnerId = (showdown.participantIds || []).find((candidate) => normalizeContestantId(candidate) === normalizeContestantId(id));
    if (!winnerId) return showdown;
    showdown.winnerId = winnerId;
    showdown.loserIds = (showdown.participantIds || []).filter((candidate) => normalizeContestantId(candidate) !== normalizeContestantId(winnerId));
    showdown.resultRevealed = false;
    return showdown;
  }

  function dragulaFloorShowEligible(show, count) {
    const format = String(show?.format || "solo");
    if (format === "pairs") return count >= 4 && count <= 8;
    if (format === "2_teams") return count >= 4;
    if (format === "3_teams") return count >= 6;
    return true;
  }

  function chooseDragulaFloorShow(usedIds, count, { finale = false, firstEpisode = false, priorEpisodes = [] } = {}) {
    const previousCompetitiveEpisode = [...(priorEpisodes || [])].reverse().find((episode) => episode?.dragula && !episode?.dragulaLastSupper && !episode?.isFinale && episode?.floorShow);
    const previousFormat = String(previousCompetitiveEpisode?.floorShow?.format || "solo");
    const previousCollaborative = ["pairs", "2_teams", "3_teams"].includes(previousFormat);
    const matchesEpisodeRules = (show) => {
      if (!dragulaFloorShowEligible(show, count)) return false;
      if (firstEpisode && !["design", "runway"].includes(String(show?.type || "").toLowerCase())) return false;
      const currentFormat = String(show?.format || "solo");
      if (previousCollaborative && ["pairs", "2_teams", "3_teams"].includes(currentFormat)) return false;
      return true;
    };

    let pool = DRAGULA_FLOOR_SHOWS.filter((show) => !usedIds.has(show.id) && matchesEpisodeRules(show));
    if (finale) {
      const solo = pool.filter((show) => show.format === "solo");
      if (solo.length) pool = solo;
    }
    if (!pool.length) {
      pool = DRAGULA_FLOOR_SHOWS.filter(matchesEpisodeRules);
      if (finale) {
        const solo = pool.filter((show) => show.format === "solo");
        if (solo.length) pool = solo;
      }
    }
    const show = pickRandom(pool) || DRAGULA_FLOOR_SHOWS.find(matchesEpisodeRules) || DRAGULA_FLOOR_SHOWS[0];
    if (show?.id) usedIds.add(show.id);
    return structuredClone(show);
  }

  function dragulaKeyOfLifeDeathEnabled() {
    if (isDragulaResurrectionFormat()) return false;
    return Boolean(
      state.seasonSetup?.productionControls?.has?.("key-life-death") ||
      state.seasonSetup?.seasonTwists?.has?.("key-life-death")
    );
  }

  function dragulaCursesEnabled() {
    if (isDragulaResurrectionFormat()) return false;
    return Boolean(
      state.seasonSetup?.productionControls?.has?.("curses") ||
      state.seasonSetup?.seasonTwists?.has?.("curses")
    );
  }

  function isHellboundShowdownFormat() {
    return isDragulaMode() && String(state.seasonSetup?.comebackFormat || "none") === "hellbound-showdown";
  }

  function chooseDragulaKeyFrightFeat(usedIds) {
    const feat = DRAGULA_FRIGHT_FEATS.find((item) => item?.id === "ff_random_key_of_life_and_death") || {
      id: "ff_random_key_of_life_and_death",
      name: "Key of Life & Death",
      description: "Pick a key at random, one of which is the Key of Life and Death.",
    };
    if (feat?.id) usedIds.add(feat.id);
    return structuredClone(feat);
  }

  function chooseDragulaFrightFeat(usedIds) {
    const regularPool = DRAGULA_FRIGHT_FEATS.filter((feat) => feat?.id !== "ff_random_key_of_life_and_death");
    let pool = regularPool.filter((feat) => !usedIds.has(feat.id));
    if (!pool.length) pool = regularPool;
    const feat = pickRandom(pool) || regularPool[0] || null;
    if (feat?.id) usedIds.add(feat.id);
    return feat ? structuredClone(feat) : null;
  }

  function chooseDragulaExtermination(usedIds) {
    let pool = DRAGULA_EXTERMINATIONS.filter((challenge) => !usedIds.has(challenge.id));
    if (!pool.length) pool = DRAGULA_EXTERMINATIONS;
    const challenge = pickRandom(pool) || DRAGULA_EXTERMINATIONS[0] || null;
    if (challenge?.id) usedIds.add(challenge.id);
    return challenge ? structuredClone(challenge) : null;
  }

  function buildDragulaGroups(format, participantIds, assignedById = null) {
    const ids = shuffled([...(participantIds || [])]);
    if (!ids.length || format === "solo") return [];
    const groups = [];
    if (format === "pairs") {
      while (ids.length) {
        const memberIds = ids.splice(0, 2);
        if (memberIds.length === 1 && groups.length) groups[groups.length - 1].memberIds.push(memberIds[0]);
        else groups.push({ name: `Pair ${groups.length + 1}`, memberIds });
      }
    } else {
      const teamCount = format === "3_teams" ? 3 : 2;
      for (let index = 0; index < teamCount; index += 1) groups.push({ name: `Team ${index + 1}`, memberIds: [] });
      ids.forEach((id, index) => groups[index % teamCount].memberIds.push(id));
    }
    groups.forEach((group) => { group.assignedById = assignedById; });
    return groups.filter((group) => group.memberIds.length);
  }

  function buildDragulaTeamDraft(format, participantIds, assignmentWinnerId) {
    if (!isDraftTeamFormat(format) || !assignmentWinnerId) return null;
    const teamCount = teamCountForFormat(format, participantIds.length);
    if (!teamCount) return null;

    const winnerKey = normalizeContestantId(assignmentWinnerId);
    const canonicalWinner = participantIds.find((id) => normalizeContestantId(id) === winnerKey);
    let captainIds = canonicalWinner ? [canonicalWinner] : [];
    const fallback = shuffled(participantIds.filter((id) => !captainIds.some((captainId) => normalizeContestantId(captainId) === normalizeContestantId(id))));
    captainIds = [...captainIds, ...fallback.slice(0, Math.max(0, teamCount - captainIds.length))];

    const targetSizes = Array.from({ length: teamCount }, (_, index) =>
      Math.floor(participantIds.length / teamCount) + (index < participantIds.length % teamCount ? 1 : 0)
    );
    const groups = captainIds.map((captainId, index) => ({
      name: `TEAM ${index + 1}`,
      captainId,
      memberIds: [captainId],
      assignedById: assignmentWinnerId,
    }));

    let availableIds = participantIds.filter((id) => !captainIds.some((captainId) => normalizeContestantId(captainId) === normalizeContestantId(id)));
    const picks = [];
    let teamIndex = 0;
    let safety = 0;
    while (availableIds.length && safety < 500) {
      safety += 1;
      const group = groups[teamIndex];
      if (group && group.memberIds.length < targetSizes[teamIndex]) {
        const choice = chooseBestRelationshipPick(group.captainId, availableIds) || { id: pickRandom(availableIds), score: 0 };
        if (choice?.id) {
          group.memberIds.push(choice.id);
          picks.push({
            captainId: group.captainId,
            pickedId: choice.id,
            teamIndex,
            teamName: group.name,
            relationshipScore: Number(choice.score) || 0,
          });
          availableIds = availableIds.filter((id) => normalizeContestantId(id) !== normalizeContestantId(choice.id));
        }
      }
      teamIndex = (teamIndex + 1) % teamCount;
    }

    return { groups, captainIds, picks };
  }

  function buildDragulaFrightFeat(feat, participants, floorShow) {
    if (!feat) {
      return {
        occurs: false,
        reason: "random-skip",
        winnerIds: [],
        winnerRevealed: false,
        rewardType: "",
        advantageLevel: 0,
        floorShowFormat: floorShow?.format || "solo",
      };
    }
    const winner = pickRandom(participants);
    const collaborative = ["pairs", "2_teams", "3_teams"].includes(String(floorShow?.format || "solo"));
    const assignsGroups = collaborative && Math.random() < 0.65;
    const cursePrize = dragulaCursesEnabled() && Math.random() < 0.20;
    const rewardType = cursePrize ? "curse" : (assignsGroups ? "assign-groups" : "advantage");
    return {
      occurs: true,
      id: feat?.id || "fright-feat",
      name: feat?.name || "Fright Feat",
      description: dragulaMonsterCopy(feat?.description || "Face a Fright Feat."),
      winnerIds: winner ? [winner.id] : [],
      winnerRevealed: false,
      rewardType,
      advantageLevel: rewardType === "advantage" ? 2 : 0,
      floorShowFormat: floorShow?.format || "solo",
    };
  }

  function dragulaCurrentBestCompetitorId(participants, priorEpisodes, excludedIds = []) {
    const excluded = new Set((excludedIds || []).map((id) => normalizeContestantId(id)));
    const rows = (participants || [])
      .filter((monster) => !excluded.has(normalizeContestantId(monster.id)))
      .map((monster) => {
        const ppe = calculateQueenPPE(monster.id, priorEpisodes || []);
        return { id: monster.id, ppe: Number(ppe?.value || 0), tie: Math.random() };
      });
    if (!rows.length) return null;
    rows.sort((a, b) => b.ppe - a.ppe || a.tie - b.tie);
    return rows[0]?.id || null;
  }

  function buildDragulaCurse(participants, frightFeat, priorEpisodes, episodeNumber, finalistTarget = 3) {
    const activeCount = (participants || []).length;
    if (
      !dragulaCursesEnabled() ||
      frightFeat?.rewardType !== "curse" ||
      Number(episodeNumber) <= 1 ||
      activeCount < Math.max(2, Number(finalistTarget) || 3) + 2 ||
      !frightFeat?.occurs ||
      !(frightFeat.winnerIds || []).length
    ) return null;

    const curserId = frightFeat.winnerIds[0];
    const previousCurseTargetId = priorEpisodes?.length
      ? priorEpisodes[priorEpisodes.length - 1]?.curse?.targetId || null
      : null;
    const previousTargetKey = normalizeContestantId(previousCurseTargetId);

    let candidates = (participants || []).filter((monster) => {
      const key = normalizeContestantId(monster.id);
      return key !== normalizeContestantId(curserId) && (!previousTargetKey || key !== previousTargetKey);
    });
    if (!candidates.length) {
      candidates = (participants || []).filter((monster) => normalizeContestantId(monster.id) !== normalizeContestantId(curserId));
    }
    if (!candidates.length) return null;

    const roll = Math.random();
    let targetId = null;
    let strategy = "random";
    if (roll < 0.45) {
      targetId = dragulaWorstSisterId(curserId, candidates, []);
      strategy = "worstsister";
    } else if (roll < 0.90) {
      targetId = dragulaCurrentBestCompetitorId(candidates, priorEpisodes || [], [curserId]);
      strategy = "front-runner";
    }
    if (!targetId) targetId = pickRandom(candidates)?.id || null;
    if (!targetId) return null;

    return {
      occurs: true,
      curserId,
      targetId,
      strategy,
      penalty: randomIntInclusive(3, 8),
    };
  }

  function buildDragulaFloorShowRuntime(show, participants, frightFeat, priorEpisodes = [], { finale = false, forceBottom3 = false, allowHesitantWinner = true, curse = null, forceIndividualJudging = false, titansMode = false, titansPenultimate = false, allowDoubleWin = true } = {}) {
    const category = dragulaNormalizedFloorCategory(show?.type);
    const participantIds = participants.map((queen) => queen.id);
    const assignmentWinnerId = frightFeat?.occurs && frightFeat?.rewardType === "assign-groups" ? frightFeat?.winnerIds?.[0] : null;
    const teamDraft = buildDragulaTeamDraft(show?.format || "solo", participantIds, assignmentWinnerId);
    const groups = teamDraft?.groups || buildDragulaGroups(show?.format || "solo", participantIds, assignmentWinnerId);
    const groupById = new Map();
    groups.forEach((group) => group.memberIds.forEach((id) => groupById.set(normalizeContestantId(id), group)));
    const advantageWinnerId = frightFeat?.occurs && frightFeat?.rewardType === "advantage" ? frightFeat?.winnerIds?.[0] : null;

    const performances = participants.map((queen) => {
      const weightedSkill = Object.entries(show?.requiredSkills || {}).reduce(
        (sum, [skill, weight]) => sum + (Number(queen.skills?.[skill]) || 0) * Number(weight || 0),
        0
      );
      const baseRoll = performanceRoll(15, 35);
      const advantage = normalizeContestantId(queen.id) === normalizeContestantId(advantageWinnerId) ? 2 : 0;
      const history = competitiveReputationForQueen(queen.id, priorEpisodes || []);
      const productionBias = challengeRiggoryDisabled() ? 0 : Number(history?.favoritism || 0);
      const cursePenalty = curse?.occurs && normalizeContestantId(curse.targetId) === normalizeContestantId(queen.id)
        ? Number(curse.penalty || 0)
        : 0;
      const individualScore = baseRoll - weightedSkill - advantage + productionBias + cursePenalty;
      return {
        id: queen.id,
        weightedSkill,
        baseRoll,
        advantage,
        productionBias,
        cursePenalty,
        individualScore,
        score: individualScore,
        adjustedScore: individualScore,
      };
    });

    const teamScores = [];
    if (groups.length) {
      groups.forEach((group) => {
        const values = group.memberIds
          .map((id) => performances.find((item) => normalizeContestantId(item.id) === normalizeContestantId(id))?.individualScore)
          .filter(Number.isFinite);
        group.average = values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : 999;
        teamScores.push({ name: group.name, memberIds: [...group.memberIds], average: group.average });
      });
      performances.forEach((performance) => {
        const group = groupById.get(normalizeContestantId(performance.id));
        if (group) performance.score = performance.individualScore * 0.72 + Number(group.average || 0) * 0.28;
        performance.adjustedScore = performance.score;
      });
    }

    performances.forEach((performance) => {
      performance.bracket = performanceBracket(Number(performance.score));
      performance.commentBracket = performance.bracket;
    });
    assignPerformanceCommentBrackets(performances);

    const runwayResults = participants.map((queen) => {
      const rawScore = performanceRoll(12, 35) - (Number(queen.skills?.runway) || 0);
      const result = runwayResultForScore(rawScore);
      return { id: queen.id, rawScore, result: result.label, modifier: result.modifier, adjustedScore: rawScore };
    });
    assignRunwayCommentBrackets(runwayResults);

    const ordered = [...performances].sort((a, b) => a.score - b.score);
    const placements = Object.fromEntries(participantIds.map((id) => [id, "SAFE"]));
    const format = String(show?.format || "solo");
    const topFivePlacementEpisode = !finale && participants.length === 5;
    const recentTeamJudged = (priorEpisodes || []).slice(-2).some((episode) => Boolean(episode?.floorShow?.judgedAsTeams || episode?.maxiChallenge?.judgedAsTeams));
    const judgedAsPairs = Boolean(participants.length <= 8 && !forceIndividualJudging && !finale && !forceBottom3 && !topFivePlacementEpisode && format === "pairs" && teamScores.length >= 2 && randomIntInclusive(0, 100) <= 84);
    const judgedAsTeams = Boolean(!forceIndividualJudging && !finale && !forceBottom3 && !topFivePlacementEpisode && !recentTeamJudged && isDraftTeamFormat(format) && teamScores.length >= 2 && randomIntInclusive(0, 100) <= 84);
    const pairJudgingMode = format === "pairs" ? (judgedAsPairs ? "pairs" : "individual") : "";
    let topPoolIds = [];
    let bottomPoolIds = [];
    let judgedIds = [];
    let safeIds = [];
    let topTeamName = "";
    let bottomTeamName = "";
    let safeTeamNames = [];
    let topPairNames = [];
    let safePairNames = [];
    let bottomPairNames = [];
    let hesitantWinnerBottomId = null;

    if (finale) {
      if (ordered[0]) placements[ordered[0].id] = "WIN";
      topPoolIds = ordered[0] ? [ordered[0].id] : [];
      judgedIds = [...participantIds];
      safeIds = participantIds.filter((id) => !topPoolIds.some((topId) => normalizeContestantId(topId) === normalizeContestantId(id)));
    } else if (judgedAsPairs && teamScores.length >= 2) {
      const pairPools = pairJudgingPools({ teamScores });
      topPoolIds = pairPools.topPairs.flatMap((pair) => pair.memberIds);
      bottomPoolIds = pairPools.bottomPairs.flatMap((pair) => pair.memberIds);
      topPairNames = pairPools.topPairs.map(pairDisplayName);
      safePairNames = pairPools.safePairs.map(pairDisplayName);
      bottomPairNames = pairPools.bottomPairs.map(pairDisplayName);

      const winningPair = pairPools.topPairs[0];
      const highPairs = pairPools.topPairs.slice(1);

      const winningPairIds = [...(winningPair?.memberIds || [])].sort((a, b) => {
        const aScore = Number(performances.find((item) => normalizeContestantId(item.id) === normalizeContestantId(a))?.score ?? 999);
        const bScore = Number(performances.find((item) => normalizeContestantId(item.id) === normalizeContestantId(b))?.score ?? 999);
        return aScore - bScore;
      });
      const jointPairWin = allowDoubleWin && winningPairIds.length > 1 && Math.random() < 0.04;
      winningPairIds.forEach((id, index) => { placements[id] = (index === 0 || jointPairWin) ? "WIN" : "HIGH"; });
      highPairs.forEach((pair) => pair.memberIds.forEach((id) => { placements[id] = "HIGH"; }));

      const performanceById = new Map(performances.map((item) => [normalizeContestantId(item.id), item]));
      const sortedBottom = [...bottomPoolIds].sort(
        (a, b) => (performanceById.get(normalizeContestantId(a))?.score ?? 999) - (performanceById.get(normalizeContestantId(b))?.score ?? 999)
      );
      if (sortedBottom.length >= 4) {
        sortedBottom.slice(0, -2).forEach((id) => { placements[id] = "LOW"; });
        sortedBottom.slice(-2).forEach((id) => { placements[id] = "BTM2"; });
      } else if (sortedBottom.length === 2) {
        sortedBottom.forEach((id) => { placements[id] = "BTM2"; });
      } else if (sortedBottom.length === 1) {
        placements[sortedBottom[0]] = "LOW";
      }
      bottomPoolIds = sortedBottom.filter((id) => /^BTM/.test(String(placements[id] || "")));
      judgedIds = [...topPoolIds, ...pairPools.bottomPairs.flatMap((pair) => pair.memberIds)];
      const judgedKeys = new Set(judgedIds.map((id) => normalizeContestantId(id)));
      safeIds = participantIds.filter((id) => !judgedKeys.has(normalizeContestantId(id)));
    } else if (judgedAsTeams && teamScores.length >= 2) {
      const orderedTeams = [...teamScores].sort((a, b) => a.average - b.average);
      const topTeam = orderedTeams[0];
      const bottomTeam = orderedTeams[orderedTeams.length - 1];
      topTeamName = topTeam?.name || "";
      bottomTeamName = bottomTeam?.name || "";
      safeTeamNames = orderedTeams.slice(1, -1).map((team) => team.name);
      topPoolIds = [...(topTeam?.memberIds || [])];

      const performanceById = new Map(performances.map((item) => [normalizeContestantId(item.id), item]));
      const bottomMembersWorstFirst = [...(bottomTeam?.memberIds || [])].sort(
        (a, b) => (performanceById.get(normalizeContestantId(b))?.score ?? -999) - (performanceById.get(normalizeContestantId(a))?.score ?? -999)
      );

      const allTeamBottom = bottomMembersWorstFirst.length <= 4;
      bottomPoolIds = allTeamBottom ? [...bottomMembersWorstFirst] : bottomMembersWorstFirst.slice(0, 3);

      const sortedTop = [...topPoolIds].sort(
        (a, b) => (performanceById.get(normalizeContestantId(a))?.score ?? 999) - (performanceById.get(normalizeContestantId(b))?.score ?? 999)
      );
      if (sortedTop.length) {
        placements[sortedTop[0]] = "WIN";
        sortedTop.slice(1).forEach((id) => { placements[id] = "HIGH TEAM"; });
      }

      if (allTeamBottom && bottomPoolIds.length >= 2) {
        const label = `BTM${bottomPoolIds.length}`;
        bottomPoolIds.forEach((id) => { placements[id] = label; });
      } else {
        const sortedBottomBestFirst = [...bottomPoolIds].sort(
          (a, b) => (performanceById.get(normalizeContestantId(a))?.score ?? 999) - (performanceById.get(normalizeContestantId(b))?.score ?? 999)
        );
        if (sortedBottomBestFirst.length >= 3) {
          sortedBottomBestFirst[0] && (placements[sortedBottomBestFirst[0]] = "LOW");
          sortedBottomBestFirst.slice(-2).forEach((id) => { placements[id] = "BTM2"; });
          bottomPoolIds = sortedBottomBestFirst.slice(-2);
        } else {
          sortedBottomBestFirst.forEach((id) => { placements[id] = `BTM${Math.max(2, sortedBottomBestFirst.length)}`; });
          bottomPoolIds = sortedBottomBestFirst;
        }
      }

      judgedIds = [...topPoolIds, ...bottomPoolIds];
      const judgedKeys = new Set(judgedIds.map((id) => normalizeContestantId(id)));
      safeIds = participantIds.filter((id) => !judgedKeys.has(normalizeContestantId(id)));
    } else {
      const count = ordered.length;

      if (count === 5 && titansPenultimate) {
        const winnerEntry = ordered[0] || null;
        const bottomEntries = ordered.slice(1);
        if (winnerEntry) placements[winnerEntry.id] = "WIN";
        bottomEntries.forEach((item) => { placements[item.id] = "BTM4"; });
        topPoolIds = winnerEntry ? [winnerEntry.id] : [];
        bottomPoolIds = bottomEntries.map((item) => item.id);
        judgedIds = [...topPoolIds, ...bottomPoolIds];
        safeIds = [];
      } else if (count === 5) {

        const patternRoll = Math.random();
        const pattern = forceBottom3
          ? "1w1h3b"
          : (allowDoubleWin && patternRoll < 0.04 ? "2w1h2b"
            : patternRoll < 0.09 ? "1w1h3b"
            : (Math.random() < 0.70 ? "1w1h1l2b" : "1w2h2b"));
        let winnerEntries = [];
        let highEntries = [];
        let low = null;
        let bottomEntries = [];

        if (pattern === "1w2h2b") {
          winnerEntries = ordered.slice(0, 1);
          highEntries = ordered.slice(1, 3);
          bottomEntries = ordered.slice(3, 5);
        } else if (pattern === "1w1h3b") {
          winnerEntries = ordered.slice(0, 1);
          highEntries = ordered.slice(1, 2);
          bottomEntries = ordered.slice(2, 5);
        } else if (pattern === "2w1h2b") {
          winnerEntries = ordered.slice(0, 2);
          highEntries = ordered.slice(2, 3);
          bottomEntries = ordered.slice(3, 5);
        } else {
          winnerEntries = ordered.slice(0, 1);
          highEntries = ordered.slice(1, 2);
          low = ordered[2] || null;
          bottomEntries = ordered.slice(3, 5);
        }

        winnerEntries.forEach((item) => { placements[item.id] = "WIN"; });
        highEntries.forEach((item) => { placements[item.id] = "HIGH"; });
        if (low) placements[low.id] = "LOW";
        const bottomLabel = bottomEntries.length >= 3 ? `BTM${bottomEntries.length}` : "BTM2";
        bottomEntries.forEach((item) => { placements[item.id] = bottomLabel; });

        topPoolIds = [...winnerEntries.map((item) => item.id), ...highEntries.map((item) => item.id)];
        bottomPoolIds = bottomEntries.map((item) => item.id);
        judgedIds = [...topPoolIds, ...(low ? [low.id] : []), ...bottomPoolIds];
        safeIds = [];
      } else {

        const bottom3Chance = titansMode ? 0.07 : 0.045;
        const randomBottom3 = forceBottom3 || Math.random() < bottom3Chance;
        const skipHighLow = !forceBottom3 && count >= 6 && Math.random() < 0.025;
        const useDoubleWin = allowDoubleWin && !randomBottom3 && Math.random() < 0.04;
        let selected;
        if (skipHighLow) {
          selected = { wins: 1, highs: 0, lows: 0, bottoms: randomBottom3 ? 3 : 2 };
        } else if (useDoubleWin) {
          selected = { wins: 2, highs: 1, lows: 1, bottoms: 2 };
        } else if (randomBottom3) {
          selected = Math.random() < 0.665
            ? { wins: 1, highs: 1, lows: 1, bottoms: 3 }
            : { wins: 1, highs: 2, lows: 0, bottoms: 3 };
        } else {
          selected = Math.random() < 0.85
            ? { wins: 1, highs: 2, lows: 1, bottoms: 2 }
            : { wins: 1, highs: 3, lows: 0, bottoms: 2 };
        }
        const winnerEntries = ordered.slice(0, selected.wins);
        const highEntries = ordered.slice(selected.wins, selected.wins + selected.highs);
        const bottomEntries = ordered.slice(-selected.bottoms);
        const usedKeys = new Set([
          ...winnerEntries, ...highEntries, ...bottomEntries
        ].map((item) => normalizeContestantId(item.id)));
        const middle = ordered.filter((item) => !usedKeys.has(normalizeContestantId(item.id)));
        const lowEntry = selected.lows ? middle[middle.length - 1] || null : null;

        winnerEntries.forEach((item) => { placements[item.id] = "WIN"; });
        highEntries.forEach((item) => { placements[item.id] = "HIGH"; });
        if (lowEntry) placements[lowEntry.id] = "LOW";
        const bottomLabel = `BTM${Math.max(2, bottomEntries.length)}`;
        bottomEntries.forEach((item) => { placements[item.id] = bottomLabel; });

        topPoolIds = [...winnerEntries, ...highEntries].map((item) => item.id);
        bottomPoolIds = bottomEntries.map((item) => item.id);
        judgedIds = [...topPoolIds, ...(lowEntry ? [lowEntry.id] : []), ...bottomPoolIds];
        const judgedKeys = new Set(judgedIds.map(normalizeContestantId));
        safeIds = participantIds.filter((id) => !judgedKeys.has(normalizeContestantId(id)));
        const winner = winnerEntries[0] || null;

        if (allowHesitantWinner && winner && bottomPoolIds.length === 2 && Number(winner.score) >= 10) {
          const chance = Number(winner.score) >= 15 ? 6 : 4;
          if (randomIntInclusive(1, 100) <= chance) {
            hesitantWinnerBottomId = winner.id;
            bottomPoolIds = [winner.id, ...bottomPoolIds];
            bottomPoolIds.forEach((id) => {
              if (normalizeContestantId(id) === normalizeContestantId(winner.id)) placements[id] = "WIN BTM3";
              else placements[id] = "BTM3";
            });
            Object.entries(placements).forEach(([id, placement]) => {
              if (placement === "LOW") placements[id] = "SAFE";
            });
            judgedIds = [...new Map([...topPoolIds, ...bottomPoolIds].map((id) => [normalizeContestantId(id), id])).values()];
            const hesitantJudgedKeys = new Set(judgedIds.map((id) => normalizeContestantId(id)));
            safeIds = participantIds.filter((id) => !hesitantJudgedKeys.has(normalizeContestantId(id)));
          }
        }
      }
    }

    return {
      id: show?.id,
      sourceType: show?.type || "runway",
      category,
      categoryLabel: "FLOOR SHOW",
      challengeTypeLabel: dragulaFloorShowTypeLabel(show?.type),
      format,
      formatLabel: format.replaceAll("_", " ").toUpperCase(),
      name: show?.name || "Floor Show",
      displayName: show?.name || "Floor Show",
      description: dragulaMonsterCopy(show?.description || ""),
      skills: structuredClone(show?.requiredSkills || {}),
      requiredSkills: structuredClone(show?.requiredSkills || {}),
      participantIds,
      groups,
      captainIds: teamDraft?.captainIds || [],
      teamDraftPicks: teamDraft?.picks || [],
      teamsRevealed: !teamDraft,
      performances,
      teamScores,
      runwayResults,
      placements,
      topPoolIds,
      bottomPoolIds,
      judgedIds,
      safeIds,
      separateRunway: false,
      collaborative: groups.length > 0,
      judgedAsPairs,
      judgedAsTeams,
      pairJudgingMode,
      wholeTeamWins: false,
      topTeamName,
      bottomTeamName,
      safeTeamNames,
      topPairNames,
      safePairNames,
      bottomPairNames,
      hesitantWinnerBottomId,
      resultScene: structuredClone(show?.resultScene || {}),
      workroomEvents: null,
    };
  }

  function dragulaWorstSisterId(holderId, participants, excludedIds = []) {
    const holderKey = normalizeContestantId(holderId);
    const excluded = new Set((excludedIds || []).map((id) => normalizeContestantId(id)));
    let candidates = (participants || []).filter((monster) => {
      const key = normalizeContestantId(monster.id);
      return key && key !== holderKey && !excluded.has(key);
    });
    if (!candidates.length) {
      candidates = (participants || []).filter((monster) => normalizeContestantId(monster.id) !== holderKey);
    }
    if (!candidates.length) return null;
    const rows = candidates.map((monster) => ({
      id: monster.id,
      relationship: Number(getRelationshipScore(holderId, monster.id) ?? 0),
      tie: Math.random(),
    }));
    rows.sort((a, b) => a.relationship - b.relationship || a.tie - b.tie);
    return rows[0]?.id || null;
  }

  function normalizeDragulaBottomLabels(floorShow) {
    if (!floorShow) return;
    const bottomIds = [...new Map((floorShow.bottomPoolIds || []).map((id) => [normalizeContestantId(id), id])).values()];
    floorShow.bottomPoolIds = bottomIds;
    const count = bottomIds.length;
    if (count >= 2) {
      const label = `BTM${count}`;
      bottomIds.forEach((id) => {
        const current = String(floorShow.placements?.[id] || "").trim();
        if (/^WIN\s*BTM\d+$/.test(current) || /^WIN\+BTM\d+$/.test(current)) floorShow.placements[id] = `WIN ${label}`;
        else if (/^BTM\d+$/.test(current)) floorShow.placements[id] = label;
      });
    }

  }

  function syncDragulaPoolsAfterKeyDecision(floorShow, participants, keyDecision) {
    if (!floorShow) return;
    normalizeDragulaBottomLabels(floorShow);
    const bottomKeys = new Set((floorShow.bottomPoolIds || []).map((id) => normalizeContestantId(id)));
    const judged = new Map((floorShow.judgedIds || []).map((id) => [normalizeContestantId(id), id]));
    (floorShow.bottomPoolIds || []).forEach((id) => judged.set(normalizeContestantId(id), id));
    if (keyDecision?.nominatedId) judged.set(normalizeContestantId(keyDecision.nominatedId), keyDecision.nominatedId);
    if (keyDecision?.savedId && String(floorShow.placements?.[keyDecision.savedId] || "") === "SAFE") {
      judged.delete(normalizeContestantId(keyDecision.savedId));
    }
    floorShow.judgedIds = [...judged.values()];
    const topKeys = new Set((floorShow.topPoolIds || []).map((id) => normalizeContestantId(id)));
    floorShow.safeIds = (participants || [])
      .map((monster) => monster.id)
      .filter((id) => {
        const key = normalizeContestantId(id);
        const placement = String(floorShow.placements?.[id] || "SAFE");
        return !bottomKeys.has(key) && !topKeys.has(key) && placement === "SAFE" && key !== normalizeContestantId(keyDecision?.nominatedId);
      });

    if (floorShow.voteOffPremiere) {
      const ids = (participants || []).map((monster) => monster.id);
      const winnerId = ids.find((id) => /^WIN(?:$|[+\s])/.test(String(floorShow.placements?.[id] || "").trim())) || null;
      floorShow.voteOffWinnerId = winnerId;
      floorShow.voteOffCritiques = {
        winnerId,
        positiveIds: ids.filter((id) => String(floorShow.placements?.[id] || "") === "HIGH"),
        safeIds: ids.filter((id) => String(floorShow.placements?.[id] || "") === "SAFE"),
        negativeIds: ids.filter((id) => String(floorShow.placements?.[id] || "") === "LOW"),
      };
    }
  }

  function validateDragulaFloorPlacements(floorShow, participants, { allowLargeBottom = false, protectedBottomId = null, immuneIds = [] } = {}) {
    if (!floorShow || !(participants || []).length) return floorShow;
    const ids = participants.map((monster) => monster.id);
    const placements = floorShow.placements || (floorShow.placements = {});
    const scores = new Map((floorShow.performances || []).map((item) =>
      [normalizeContestantId(item.id), Number.isFinite(Number(item.score)) ? Number(item.score) : 999]));
    const byScore = (a, b) => (scores.get(normalizeContestantId(a)) ?? 999) - (scores.get(normalizeContestantId(b)) ?? 999);
    const isWinner = (value) => /^WIN(?:$|[+\s])/.test(String(value || "").trim());
    const isBottom = (value) => /^(?:WIN\s*\+?\s*)?BTM\d*$/.test(String(value || "").trim());
    const protectedKey = normalizeContestantId(protectedBottomId);
    const immuneKeys = new Set((immuneIds || []).map(normalizeContestantId));
    ids.forEach((id) => {
      if (immuneKeys.has(normalizeContestantId(id)) && isBottom(placements[id])) {
        placements[id] = isWinner(placements[id]) ? "WIN" : "SAFE";
      }
    });

    const voteOff = Boolean(floorShow.voteOffPremiere);
    let bottoms = voteOff ? [] : ids.filter((id) => isBottom(placements[id]));
    if (!voteOff && protectedKey && !bottoms.some((id) => normalizeContestantId(id) === protectedKey)) {
      const protectedId = ids.find((id) => normalizeContestantId(id) === protectedKey);
      if (protectedId) bottoms.push(protectedId);
    }

    const maxBottom = (allowLargeBottom || floorShow.judgedAsTeams) ? 4 : 3;
    if (bottoms.length > maxBottom) {
      const keep = [...bottoms].sort((a, b) => {
        if (normalizeContestantId(a) === protectedKey) return -1;
        if (normalizeContestantId(b) === protectedKey) return 1;
        return byScore(b, a);
      }).slice(0, maxBottom);
      const keepKeys = new Set(keep.map(normalizeContestantId));
      bottoms.forEach((id) => {
        if (!keepKeys.has(normalizeContestantId(id))) placements[id] = isWinner(placements[id]) ? "WIN" : "LOW";
      });
      bottoms = keep;
    }

    if (!voteOff && bottoms.length < 2 && ids.length >= 3) {
      const excluded = new Set(bottoms.map(normalizeContestantId));
      const options = ids.filter((id) => !excluded.has(normalizeContestantId(id)) && !isWinner(placements[id]) &&
        !immuneKeys.has(normalizeContestantId(id)));
      options.sort((a, b) => byScore(b, a));
      while (bottoms.length < 2 && options.length) bottoms.push(options.shift());
    }

    let winners = ids.filter((id) => isWinner(placements[id]));
    if (!winners.length) {
      const bottomKeys = new Set(bottoms.map(normalizeContestantId));
      let candidates = ids.filter((id) => !bottomKeys.has(normalizeContestantId(id)) && normalizeContestantId(id) !== protectedKey);
      if (!candidates.length) candidates = ids.filter((id) => normalizeContestantId(id) !== protectedKey);
      if (!candidates.length) candidates = [...ids];
      const winnerId = candidates.sort(byScore)[0];
      if (winnerId) {
        placements[winnerId] = "WIN";
        bottoms = bottoms.filter((id) => normalizeContestantId(id) !== normalizeContestantId(winnerId));
        winners = [winnerId];
      }
    }
    if (!voteOff && bottoms.length >= 2) {
      const label = `BTM${bottoms.length}`;
      bottoms.forEach((id) => { placements[id] = isWinner(placements[id]) ? `WIN ${label}` : label; });
    }

    if (!voteOff) {
      const bottomKeys = new Set(bottoms.map(normalizeContestantId));
      ids.forEach((id) => {
        if (!bottomKeys.has(normalizeContestantId(id)) && isBottom(placements[id])) {
          placements[id] = isWinner(placements[id]) ? "WIN" : "LOW";
        }
      });
    }
    if (floorShow.judgedAsTeams) {
      const lows = ids.filter((id) => String(placements[id] || "").trim() === "LOW");
      lows.slice(1).forEach((id) => { placements[id] = "SAFE"; });
    }
    floorShow.bottomPoolIds = bottoms;
    const topIds = ids.filter((id) => isWinner(placements[id]) || ["HIGH", "HIGH TEAM"].includes(String(placements[id] || "").trim()));
    floorShow.topPoolIds = topIds;
    floorShow.lowIds = ids.filter((id) => String(placements[id] || "").trim() === "LOW");
    floorShow.judgedIds = ids.filter((id) => String(placements[id] || "SAFE").trim() !== "SAFE");
    floorShow.safeIds = ids.filter((id) => String(placements[id] || "SAFE").trim() === "SAFE");
    const bottomKeys = new Set(bottoms.map(normalizeContestantId));
    if (floorShow.hesitantWinnerBottomId && !bottomKeys.has(normalizeContestantId(floorShow.hesitantWinnerBottomId))) {
      floorShow.hesitantWinnerBottomId = null;
    }
    if (voteOff) {
      const currentWinnerId = ids.find((id) => isWinner(placements[id])) || null;
      floorShow.voteOffWinnerId = currentWinnerId;
      floorShow.voteOffCritiques = {
        winnerId: currentWinnerId,
        positiveIds: ids.filter((id) => String(placements[id] || "") === "HIGH"),
        safeIds: [...floorShow.safeIds],
        negativeIds: [...floorShow.lowIds],
      };
    }
    return floorShow;
  }

  function applyDragulaFrightFeatImmunity(floorShow, participants, frightFeat) {
    const winnerId = frightFeat?.frightFeatImmunity ? frightFeat?.winnerIds?.[0] : null;
    if (!winnerId || !floorShow) return null;

    const placements = floorShow.placements || {};
    const preImmunityPlacements = structuredClone(placements);
    const preImmunityBottomIds = [...(floorShow.bottomPoolIds || [])];
    const originalPlacement = String(placements[winnerId] || "SAFE").trim();
    const bottomToken = originalPlacement.match(/BTM\d+/)?.[0] || "";
    const dangerPlacement = originalPlacement === "LOW" || Boolean(bottomToken);
    const performanceById = new Map((floorShow.performances || []).map((item) => [normalizeContestantId(item.id), Number(item.score)]));
    let bumpedId = null;

    if (dangerPlacement) {
      const bottomKeys = new Set((floorShow.bottomPoolIds || []).map((id) => normalizeContestantId(id)));
      const candidates = (participants || []).map((monster) => monster.id).filter((id) => {
        const key = normalizeContestantId(id);
        return key !== normalizeContestantId(winnerId) && !bottomKeys.has(key);
      });

      const priority = (id) => {
        const placement = String(placements[id] || "SAFE").trim();
        if (bottomToken) {
          if (placement === "LOW") return 0;
          if (placement === "SAFE") return 1;
          if (placement === "HIGH" || placement === "HIGH TEAM") return 2;
          if (placement.startsWith("WIN")) return 3;
          return 1;
        }
        if (placement === "SAFE") return 0;
        if (placement === "HIGH" || placement === "HIGH TEAM") return 1;
        if (placement.startsWith("WIN")) return 2;
        return 1;
      };

      candidates.sort((a, b) => {
        const diff = priority(a) - priority(b);
        if (diff) return diff;
        return (performanceById.get(normalizeContestantId(b)) ?? -999) - (performanceById.get(normalizeContestantId(a)) ?? -999);
      });
      bumpedId = candidates[0] || null;

      placements[winnerId] = originalPlacement.startsWith("WIN") ? "WIN" : "SAFE";

      if (bottomToken) {
        floorShow.bottomPoolIds = (floorShow.bottomPoolIds || []).filter(
          (id) => normalizeContestantId(id) !== normalizeContestantId(winnerId)
        );
        if (bumpedId) {
          floorShow.bottomPoolIds.push(bumpedId);
          floorShow.topPoolIds = (floorShow.topPoolIds || []).filter(
            (id) => normalizeContestantId(id) !== normalizeContestantId(bumpedId)
          );
          placements[bumpedId] = bottomToken;
        }
      } else if (bumpedId) {
        floorShow.topPoolIds = (floorShow.topPoolIds || []).filter(
          (id) => normalizeContestantId(id) !== normalizeContestantId(bumpedId)
        );
        placements[bumpedId] = "LOW";
      }

      if (normalizeContestantId(floorShow.hesitantWinnerBottomId) === normalizeContestantId(winnerId)) {
        floorShow.hesitantWinnerBottomId = null;
      }

      normalizeDragulaBottomLabels(floorShow);
      const participantIds = (participants || []).map((monster) => monster.id);
      const placementFor = (id) => String(placements[id] || "SAFE").trim();
      floorShow.topPoolIds = participantIds.filter((id) => /^(WIN|HIGH)/.test(placementFor(id)));
      floorShow.bottomPoolIds = participantIds.filter((id) => /BTM\d+/.test(placementFor(id)));
      floorShow.judgedIds = participantIds.filter((id) => placementFor(id) !== "SAFE");
      floorShow.safeIds = participantIds.filter((id) => placementFor(id) === "SAFE");
    }

    return {
      occurs: true,
      winnerId,
      savedId: winnerId,
      bumpedId,
      originalPlacement,
      placementChanged: dangerPlacement,
      preImmunityPlacements,
      preImmunityBottomIds,
      preImmunityBottomCount: preImmunityBottomIds.length,
    };
  }

  function applyDragulaKeyOfLifeDeath(floorShow, participants, frightFeat, nominatedIdOverride = null, choiceOverride = null) {
    const holderId = frightFeat?.keyOfLifeDeath ? frightFeat?.winnerIds?.[0] : null;
    if (!holderId || !floorShow) return null;
    const placements = floorShow.placements || {};
    const preKeyPlacements = structuredClone(placements);
    const holderPlacement = String(placements[holderId] || "SAFE").trim();
    const bottomToken = holderPlacement.match(/BTM\d+/)?.[0] || "";
    const atRisk = holderPlacement === "LOW" || Boolean(bottomToken);
    const preKeyBottomIds = [...(floorShow.bottomPoolIds || [])];
    const requestedChoice = ["save-self", "nominate"].includes(String(choiceOverride || ""))
      ? String(choiceOverride)
      : "";
    const saveSelf = requestedChoice ? requestedChoice === "save-self" : atRisk;
    const performanceById = new Map((floorShow.performances || []).map((item) => [normalizeContestantId(item.id), Number(item.score)]));

    if (saveSelf) {
      let bumpedId = null;
      if (atRisk) {
        const currentBottomKeys = new Set((floorShow.bottomPoolIds || []).map((id) => normalizeContestantId(id)));
        let candidates = (participants || []).map((monster) => monster.id).filter((id) => {
          const key = normalizeContestantId(id);
          return key !== normalizeContestantId(holderId) && !currentBottomKeys.has(key);
        });
        const placementPriority = (id) => {
          const placement = String(placements[id] || "SAFE").trim();
          if (bottomToken) {
            if (placement === "LOW") return 0;
            if (placement === "SAFE") return 1;
            if (placement === "HIGH" || placement === "HIGH TEAM") return 2;
            if (placement.startsWith("WIN")) return 3;
            return 1;
          }
          if (placement === "SAFE") return 0;
          if (placement === "HIGH" || placement === "HIGH TEAM") return 1;
          if (placement.startsWith("WIN")) return 2;
          return 1;
        };
        candidates.sort((a, b) => {
          const priority = placementPriority(a) - placementPriority(b);
          if (priority) return priority;
          return (performanceById.get(normalizeContestantId(b)) ?? -999) - (performanceById.get(normalizeContestantId(a)) ?? -999);
        });
        bumpedId = candidates[0] || null;

        placements[holderId] = holderPlacement.startsWith("WIN") ? "WIN" : "SAFE";
        if (bumpedId) {
          placements[bumpedId] = bottomToken || "LOW";
          if (bottomToken) {
            floorShow.topPoolIds = (floorShow.topPoolIds || []).filter((id) => normalizeContestantId(id) !== normalizeContestantId(bumpedId));
            floorShow.bottomPoolIds = (floorShow.bottomPoolIds || []).map((id) =>
              normalizeContestantId(id) === normalizeContestantId(holderId) ? bumpedId : id
            );
          }
        } else if (bottomToken) {
          floorShow.bottomPoolIds = (floorShow.bottomPoolIds || []).filter((id) => normalizeContestantId(id) !== normalizeContestantId(holderId));
        }

        if (normalizeContestantId(floorShow.hesitantWinnerBottomId) === normalizeContestantId(holderId)) {
          floorShow.hesitantWinnerBottomId = null;
        }
      }

      const decision = {
        occurs: true,
        holderId,
        choice: "save-self",
        savedId: holderId,
        bumpedId,
        originalPlacement: holderPlacement,
        nominatedId: null,
        preKeyBottomIds,
        preKeyBottomCount: preKeyBottomIds.length,
        preKeyPlacements,
      };
      syncDragulaPoolsAfterKeyDecision(floorShow, participants, decision);
      return decision;
    }

    const existingBottom = floorShow.bottomPoolIds || [];
    const immuneKeys = new Set(frightFeat?.frightFeatImmunity ? (frightFeat.winnerIds || []).map(normalizeContestantId) : []);
    const overrideCandidate = (participants || []).map((monster) => monster.id).find((id) =>
      !immuneKeys.has(normalizeContestantId(id)) &&
      normalizeContestantId(id) === normalizeContestantId(nominatedIdOverride) &&
      normalizeContestantId(id) !== normalizeContestantId(holderId) &&
      !existingBottom.some((bottomId) => normalizeContestantId(bottomId) === normalizeContestantId(id))
    );
    const nominatedId = overrideCandidate || dragulaWorstSisterId(holderId, participants, [...existingBottom, ...immuneKeys]);
    if (nominatedId) {
      if (!(floorShow.bottomPoolIds || []).some((id) => normalizeContestantId(id) === normalizeContestantId(nominatedId))) {
        floorShow.bottomPoolIds = [...(floorShow.bottomPoolIds || []), nominatedId];
      }
      floorShow.topPoolIds = (floorShow.topPoolIds || []).filter(
        (id) => normalizeContestantId(id) !== normalizeContestantId(nominatedId)
      );
      floorShow.safeIds = (floorShow.safeIds || []).filter(
        (id) => normalizeContestantId(id) !== normalizeContestantId(nominatedId)
      );
      placements[nominatedId] = `BTM${Math.max(2, (floorShow.bottomPoolIds || []).length)}`;
      normalizeDragulaBottomLabels(floorShow);
    }
    const decision = {
      occurs: true,
      holderId,
      choice: "nominate",
      savedId: null,
      bumpedId: null,
      originalPlacement: holderPlacement,
      nominatedId,
      relationshipScore: nominatedId ? Number(getRelationshipScore(holderId, nominatedId) ?? 0) : null,
      preKeyBottomIds,
      preKeyBottomCount: preKeyBottomIds.length,
      preKeyPlacements,
    };
    syncDragulaPoolsAfterKeyDecision(floorShow, participants, decision);
    return decision;
  }

  function configureDragulaVoteOffFloorShow(floorShow, participants) {
    if (!floorShow) return floorShow;
    const ids = (participants || []).map((monster) => monster.id);
    const placements = floorShow.placements || {};
    const performanceById = new Map((floorShow.performances || []).map((item) => [normalizeContestantId(item.id), Number(item.score)]));
    let winnerId = Object.entries(placements).find(([, value]) => String(value || "").trim() === "WIN")?.[0] || null;
    if (!winnerId && ids.length) {
      winnerId = [...ids].sort((a, b) => (performanceById.get(normalizeContestantId(a)) ?? 999) - (performanceById.get(normalizeContestantId(b)) ?? 999))[0];
    }

    const critiquePlacements = {};
    ids.forEach((id) => {
      const raw = String(placements[id] || "SAFE").trim();
      if (normalizeContestantId(id) === normalizeContestantId(winnerId)) critiquePlacements[id] = "WIN";
      else if (raw === "HIGH" || raw === "HIGH TEAM") critiquePlacements[id] = "HIGH";
      else if (raw === "LOW" || /^BTM\d*$/.test(raw) || /^WIN\s*BTM\d*$/.test(raw) || /^WIN\+BTM\d*$/.test(raw)) critiquePlacements[id] = "LOW";
      else critiquePlacements[id] = "SAFE";
    });

    const nonWinnerIds = ids.filter((id) => normalizeContestantId(id) !== normalizeContestantId(winnerId));
    if (!nonWinnerIds.some((id) => critiquePlacements[id] === "HIGH") && nonWinnerIds.length) {
      const best = [...nonWinnerIds].sort((a, b) => (performanceById.get(normalizeContestantId(a)) ?? 999) - (performanceById.get(normalizeContestantId(b)) ?? 999))[0];
      if (best) critiquePlacements[best] = "HIGH";
    }
    if (!nonWinnerIds.some((id) => critiquePlacements[id] === "LOW") && nonWinnerIds.length) {
      const worst = [...nonWinnerIds].sort((a, b) => (performanceById.get(normalizeContestantId(b)) ?? -999) - (performanceById.get(normalizeContestantId(a)) ?? -999))[0];
      if (worst) critiquePlacements[worst] = "LOW";
    }

    const positiveIds = ids.filter((id) => critiquePlacements[id] === "HIGH");
    const safeIds = ids.filter((id) => critiquePlacements[id] === "SAFE");
    const negativeIds = ids.filter((id) => critiquePlacements[id] === "LOW");
    floorShow.voteOffPremiere = true;
    floorShow.voteOffWinnerId = winnerId;
    floorShow.voteOffCritiques = { winnerId, positiveIds, safeIds, negativeIds };
    floorShow.placements = critiquePlacements;
    floorShow.judgedIds = [...ids];
    floorShow.safeIds = [];
    floorShow.bottomPoolIds = [];
    floorShow.hesitantWinnerBottomId = null;
    return floorShow;
  }

  function buildDragulaVoteOffVoting(participants, floorShow, keyDecision = null) {
    const winnerId = (participants || []).map((monster) => monster.id)
      .find((id) => /^WIN(?:$|[+\s])/.test(String(floorShow?.placements?.[id] || "").trim()))
      || floorShow?.voteOffWinnerId || null;
    const winnerKey = normalizeContestantId(winnerId);
    const participantIds = (participants || []).map((monster) => monster.id);
    const savedKey = normalizeContestantId(keyDecision?.savedId);
    const eligibleIds = participantIds.filter((id) => normalizeContestantId(id) !== winnerKey);
    const totals = new Map(eligibleIds.map((id) => [normalizeContestantId(id), { id, votes: 0, tieBreaker: Math.random() }]));
    const ballots = [];

    participantIds.forEach((voterId) => {
      let choices = eligibleIds.filter((id) => normalizeContestantId(id) !== normalizeContestantId(voterId));
      if (choices.length < 2) choices = [...eligibleIds];
      const picked = shuffled(choices).slice(0, Math.min(2, choices.length));
      picked.forEach((id) => {
        const item = totals.get(normalizeContestantId(id));
        if (item) item.votes += 1;
      });
      ballots.push({ voterId, targetIds: picked });
    });

    const sortedTotals = [...totals.values()].sort((a, b) => b.votes - a.votes || a.tieBreaker - b.tieBreaker);
    const eligibleForBottom = sortedTotals.filter((item) => !savedKey || normalizeContestantId(item.id) !== savedKey);
    let bottomIds = eligibleForBottom.slice(0, 2).map((item) => item.id);
    if (keyDecision?.nominatedId) {
      const nominatedKey = normalizeContestantId(keyDecision.nominatedId);
      const second = eligibleForBottom.find((item) => normalizeContestantId(item.id) !== nominatedKey)?.id || null;
      bottomIds = [keyDecision.nominatedId, second].filter(Boolean);
    }
    return {
      occurs: true,
      winnerId,
      ballots,
      totals: sortedTotals.map(({ id, votes }) => ({ id, votes })),
      bottomIds,
      revealed: true,
    };
  }

  function dragulaVoteOffCombinedTrackResult(basePlacement, { eliminated = false, bottomCount = 2 } = {}) {
    const base = ["HIGH", "SAFE", "LOW"].includes(String(basePlacement || "").trim())
      ? String(basePlacement).trim()
      : "SAFE";
    return `${base}+${eliminated ? "EXT" : `BTM${Math.max(2, bottomCount)}`}`;
  }

  function dragulaExterminationBracket(score) {
    if (score >= 67) return "strong";
    if (score >= 34) return "mixed";
    return "weak";
  }

  function dragulaExterminationComment(challenge, queen, score) {
    const bracket = dragulaExterminationBracket(score);
    const pool = Array.isArray(challenge?.comments?.[bracket]) ? challenge.comments[bracket] : [];
    const fallback = bracket === "strong"
      ? "{Contestant} dominates the extermination and never loses control."
      : bracket === "mixed"
        ? "{Contestant} pushes through the extermination, but visibly struggles."
        : "{Contestant} struggles badly and looks dangerously close to breaking.";
    return String(pickRandom(pool) || fallback)
      .replaceAll("{Contestant}", queen?.nickname || queen?.fullName || queen?.id || "The monster");
  }

  function dragulaBottomTrackLabel(bottomIds) {
    const count = Math.max(2, (bottomIds || []).length);
    return `BTM${count}`;
  }

  function dragulaUsedIndividualDoubleWin(episodes) {
    return (episodes || []).some(ep => {
      const floor = ep?.floorShow;
      if (!floor || floor.judgedAsTeams || floor.wholeTeamWins) return false;
      return Object.values(floor.placements || {}).filter(value => /^WIN(?:\b|[ +])/i.test(String(value))).length >= 2;
    });
  }

  function dragulaDoubleOutcomeSuitability(bottomIds, participants, priorEpisodes, floorShow, exterminationPerformances) {
    const bound = (x) => Math.max(0, Math.min(1, Number(x) || 0));
    const provisional = {
      dragula: true, isFinale: false,
      castIds: participants.map(q => q.id), competitionCastIds: participants.map(q => q.id),
      dragulaTrackResults: { ...(floorShow?.placements || {}) }, floorShow, maxiChallenge: floorShow,
    };
    const records = (participants || []).map(monster => {
      const id = monster.id, key = normalizeContestantId(id);
      const earlier = calculateQueenPPE(id, priorEpisodes || []);
      const current = calculateQueenPPE(id, [...(priorEpisodes || []), provisional]);
      const value = earlier.episodesOn
        ? 0.75 * Number(earlier.value) + 0.25 * Number(current.value)
        : Number(current.value);
      let wins=0, highs=0, lows=0, bottoms=0;
      (priorEpisodes || []).forEach(ep => {
        const raw = String(ep?.dragulaTrackResults?.[id] || ep?.floorShow?.placements?.[id] || '').trim();
        if (/^WIN(?:\b|[ +])/.test(raw)) wins++;
        else if (/^HIGH/.test(raw)) highs++;
        if (/^LOW/.test(raw)) lows++;
        if (/^BTM|\+BTM/.test(raw)) bottoms++;
      });
      const played = Math.max(1, Number(earlier.episodesOn));
      const placementTrend = bound(0.5 + (1.55*wins + 0.65*highs - 0.7*lows - 1.05*bottoms) / (played * 2.7));
      return { id, key, ppe: Number.isFinite(value) ? value : 3, placementTrend, played: earlier.episodesOn };
    });
    const sorted = [...records].sort((a,b) => a.ppe - b.ppe);
    records.forEach(r => {

      const below = sorted.filter(item => item.ppe < r.ppe - 0.00001).length;
      const equal = sorted.filter(item => Math.abs(item.ppe-r.ppe) <= 0.00001).length;
      const relative = bound(sorted.length > 1
        ? (below + (equal-1)/2) / (sorted.length-1) : 0.5);

      const confidence = Math.min(1, (r.played + 1) / 4);
      r.strength = bound(0.55*bound((r.ppe-1)/4) + 0.25*relative +
        0.20*(0.5 + confidence*(r.placementTrend - 0.5)));
    });
    const byKey = new Map(records.map(r => [r.key,r]));
    const selected = (bottomIds || []).map(id => byKey.get(normalizeContestantId(id))).filter(Boolean);
    const performances = new Map((exterminationPerformances || []).map(p => [normalizeContestantId(p.id), bound(Number(p.score)/100)]));
    const exterm = (bottomIds || []).map(id => performances.get(normalizeContestantId(id)) ?? 0.5);
    if (selected.length < 2) return { save:0, double:0, records:selected, reason:'not-enough-bottom-contestants' };
    const strengths = selected.map(r => r.strength);
    const min = Math.min(...strengths), max=Math.max(...strengths);
    const mean = strengths.reduce((a,b)=>a+b,0) / strengths.length;
    const extermMean = exterm.reduce((a,b)=>a+b,0) / Math.max(1,exterm.length);
    const extermGap = Math.max(...exterm)-Math.min(...exterm);
    const save = bound(0.56*min + 0.21*mean + 0.17*extermMean + 0.06*(1-extermGap));
    const double = bound(0.56*(1-max) + 0.21*(1-mean) + 0.17*(1-extermMean) + 0.06*(1-extermGap));
    return {
      save, double, records:selected.map(r=>({id:r.id,ppe:Number(r.ppe.toFixed(2)),strength:Number(r.strength.toFixed(3))})),
      extermAverage:Number(extermMean.toFixed(3)),
    };
  }

  function buildDragulaExtermination(episode, floorShow, participants, challenge, { forceDoubleSave = false, forceDoubleElimination = false, seasonFlags = null, bottomIdsOverride = null, allowSpecialExits = true, priorEpisodes = [], secondHalf = false, titansMode = false, saveUrgent = false, doubleUrgent = false } = {}) {
    const bottomIds = Array.isArray(bottomIdsOverride) ? [...bottomIdsOverride] : [...(floorShow?.bottomPoolIds || [])];
    const bottomQueens = bottomIds.map((id) => participants.find((monster) => normalizeContestantId(monster.id) === normalizeContestantId(id))).filter(Boolean);
    const bottomTrackLabel = dragulaBottomTrackLabel(bottomIds);
    const challengeData = {
      occurs: bottomIds.length > 0,
      id: challenge?.id || "dragula-extermination",
      name: challenge?.name || "Extermination",
      description: dragulaMonsterCopy(challenge?.description || "The bottom monsters must face an extermination challenge."),
      bottomIds,
    };
    const voteOffPremiere = Boolean(episode?.dragulaVoteOff);
    const voteOffBasePlacement = (id) => floorShow?.placements?.[id] || "SAFE";
    const voteOffBottomResult = (id, eliminated = false) => dragulaVoteOffCombinedTrackResult(
      voteOffBasePlacement(id),
      { eliminated, bottomCount: bottomIds.length }
    );

    if (
      allowSpecialExits &&
      bottomQueens.length === 2 &&
      (titansMode ? (Number(seasonFlags?.specialExitCount || 0) < 2) : (!seasonFlags?.disqOrDept && !seasonFlags?.specialExitUsed)) &&
      abnormalExitRoll(titansMode ? 945 : 999)
    ) {
      const quitter = pickRandom(bottomQueens);
      const survivor = bottomQueens.find((monster) => normalizeContestantId(monster.id) !== normalizeContestantId(quitter.id));
      const name = quitter.nickname || quitter.fullName || quitter.id;
      const abnormalExit = markSpecialExit(seasonFlags, quitter, {
        version: 1,
        stage: "extermination",
        kind: "refuse-extermination",
        result: "QUIT",
        annotation: "Quit",
        originalPlacement: floorShow?.placements?.[quitter.id] || "BTM2",
        wasBottom: true,
        messageLines: [`${name}, shockingly has left the stage. They decided that they won't participate in the extermination.`],
      });
      return {
        ...challengeData,
        performances: [],
        decisionMethod: "special-exit",
        resultType: "quit-refusal",
        survivorIds: survivor ? [survivor.id] : [],
        eliminatedIds: [quitter.id],
        abnormalExit,
        trackResults: {
          [quitter.id]: "QUIT",
          ...(survivor ? { [survivor.id]: voteOffPremiere ? voteOffBottomResult(survivor.id, false) : (floorShow?.placements?.[survivor.id] || "BTM2") } : {}),
        },
        resultScene: null,
        resultRevealed: false,
      };
    }

    const performances = bottomQueens.map((monster) => {
      const isHesitantWinner = normalizeContestantId(monster.id) === normalizeContestantId(floorShow?.hesitantWinnerBottomId);
      const score = isHesitantWinner ? randomIntInclusive(78, 100) : randomIntInclusive(1, 100);
      const bracket = dragulaExterminationBracket(score);
      return {
        id: monster.id,
        score,
        bracket,
        summary: dragulaExterminationComment(challenge, monster, score),
      };
    });

    const makeSpecialResult = (abnormalExit, trackResults, survivorIds, eliminatedIds, resultType) => ({
      ...challengeData,
      performances,
      decisionMethod: "special-exit",
      resultType,
      survivorIds,
      eliminatedIds,
      abnormalExit,
      trackResults,
      resultScene: null,
      resultRevealed: false,
    });

    if (
      allowSpecialExits &&
      bottomQueens.length === 2 &&
      (titansMode ? (Number(seasonFlags?.specialExitCount || 0) < 2) : (!seasonFlags?.disqOrDept && !seasonFlags?.specialExitUsed)) &&
      abnormalExitRoll(titansMode ? 945 : 999)
    ) {
      const quitter = pickRandom(bottomQueens);
      const survivor = bottomQueens.find((monster) => normalizeContestantId(monster.id) !== normalizeContestantId(quitter.id));
      const name = quitter.nickname || quitter.fullName || quitter.id;
      const abnormalExit = markSpecialExit(seasonFlags, quitter, {
        version: 1,
        stage: "results",
        kind: "bottom-quit",
        result: "BTM2 + QUIT",
        annotation: "Quit",
        originalPlacement: floorShow?.placements?.[quitter.id] || "BTM2",
        wasBottom: true,
        messageLines: [`${name} feels extremely grateful for being here, however they need to go home and take care of themselves.`],
      });
      return makeSpecialResult(
        abnormalExit,
        { [quitter.id]: "BTM2 + QUIT", ...(survivor ? { [survivor.id]: voteOffPremiere ? voteOffBottomResult(survivor.id, false) : (floorShow?.placements?.[survivor.id] || "BTM2") } : {}) },
        survivor ? [survivor.id] : [],
        [quitter.id],
        "bottom-quit"
      );
    }

    if (
      allowSpecialExits &&
      (titansMode ? (Number(seasonFlags?.specialExitCount || 0) < 2) : (!seasonFlags?.disqOrDept && !seasonFlags?.specialExitUsed)) &&
      participants.length &&
      abnormalExitRoll(titansMode ? 945 : 999)
    ) {
      const injured = pickRandom(participants);
      const injuredKey = normalizeContestantId(injured.id);
      const wasBottom = bottomIds.some((id) => normalizeContestantId(id) === injuredKey);
      const originalPlacement = placementForContestant(episode, injured.id);
      const name = injured.nickname || injured.fullName || injured.id;
      const abnormalExit = markSpecialExit(seasonFlags, injured, {
        version: 1,
        stage: "results",
        kind: "medical-result",
        result: "DEPT",
        annotation: "Departed",
        originalPlacement,
        wasBottom,
        messageLines: [
          `${name}, would you please step forward.`,
          "We've been in touch with the doctor. You need time to heal. We cannot allow you to continue in the competition.",
          "We must ask you to leave the competition.",
        ],
      });
      const trackResults = {};
      if (wasBottom) {
        bottomIds.forEach((id) => {
          trackResults[id] = normalizeContestantId(id) === injuredKey
            ? "DEPT"
            : (voteOffPremiere ? voteOffBottomResult(id, false) : (floorShow?.placements?.[id] || bottomTrackLabel));
        });
      } else {
        bottomIds.forEach((id) => { trackResults[id] = voteOffPremiere ? voteOffBottomResult(id, false) : ` ${floorShow?.placements?.[id] || bottomTrackLabel}`; });
        trackResults[injured.id] = `${originalPlacement} + DEPT`;
      }
      return makeSpecialResult(
        abnormalExit,
        trackResults,
        bottomIds.filter((id) => normalizeContestantId(id) !== injuredKey),
        [injured.id],
        "medical-departure"
      );
    }

    if (
      allowSpecialExits &&
      (titansMode ? (Number(seasonFlags?.specialExitCount || 0) < 2) : (!seasonFlags?.disqOrDept && !seasonFlags?.specialExitUsed)) &&
      participants.length &&
      abnormalExitRoll(titansMode ? 945 : 999)
    ) {
      const disqualified = pickRandom(participants);
      const disqKey = normalizeContestantId(disqualified.id);
      const wasBottom = bottomIds.some((id) => normalizeContestantId(id) === disqKey);
      const originalPlacement = placementForContestant(episode, disqualified.id);
      const name = disqualified.nickname || disqualified.fullName || disqualified.id;
      const abnormalExit = markSpecialExit(seasonFlags, disqualified, {
        version: 1,
        stage: "results",
        kind: "disqualification",
        result: "DISQ",
        annotation: "Disqualified",
        originalPlacement,
        wasBottom,
        messageLines: [`${name}, it has come to our attention that you have broken the rules of this competition. You are disqualified and must leave immediately.`],
      });
      const trackResults = {};
      if (wasBottom) {
        bottomIds.forEach((id) => {
          trackResults[id] = normalizeContestantId(id) === disqKey
            ? "DISQ"
            : (voteOffPremiere ? voteOffBottomResult(id, false) : (floorShow?.placements?.[id] || bottomTrackLabel));
        });
      } else {
        bottomIds.forEach((id) => { trackResults[id] = voteOffPremiere ? voteOffBottomResult(id, false) : ` ${floorShow?.placements?.[id] || bottomTrackLabel}`; });
        trackResults[disqualified.id] = "DISQ";
      }
      return makeSpecialResult(
        abnormalExit,
        trackResults,
        bottomIds.filter((id) => normalizeContestantId(id) !== disqKey),
        [disqualified.id],
        "disqualification"
      );
    }

    const exterminationById = new Map(performances.map((item) => [
      normalizeContestantId(item.id),
      Number(item.score),
    ]));
    const floorPerformanceById = new Map((floorShow?.performances || []).map((item) => [
      normalizeContestantId(item.id),
      Number(item.score),
    ]));
    const recordedFloorScores = bottomIds
      .map((id) => floorPerformanceById.get(normalizeContestantId(id)))
      .filter(Number.isFinite);
    const bestFloorScore = recordedFloorScores.length ? Math.min(...recordedFloorScores) : 0;
    const worstFloorScore = recordedFloorScores.length ? Math.max(...recordedFloorScores) : 0;
    const floorScoreRange = worstFloorScore - bestFloorScore;
    const clamp01 = (value) => Math.max(0, Math.min(1, value));
    const currentPPEEpisode = {
      dragula: true,
      isFinale: false,
      castIds: (participants || []).map((monster) => monster.id),
      competitionCastIds: (participants || []).map((monster) => monster.id),
      dragulaTrackResults: { ...(floorShow?.placements || {}) },
      floorShow,
      maxiChallenge: floorShow,
    };
    const ppeRows = bottomIds.map((id) => {
      const earlier = calculateQueenPPE(id, priorEpisodes || []);
      const throughFloorShow = calculateQueenPPE(id, [...(priorEpisodes || []), currentPPEEpisode]);

      const earlierPPE = earlier.episodesOn > 0 ? Number(earlier.value) : 3;
      const currentPPE = throughFloorShow.episodesOn > 0 ? Number(throughFloorShow.value) : 3;
      const effectivePPE = earlier.episodesOn > 0
        ? earlierPPE * 0.75 + currentPPE * 0.25
        : currentPPE;
      return { id, history: earlier.episodesOn, ppe: Number.isFinite(effectivePPE) ? effectivePPE : 3 };
    });
    const ppeById = new Map(ppeRows.map((item) => [normalizeContestantId(item.id), item.ppe]));
    const longestHistory = Math.max(0, ...ppeRows.map((item) => item.history));
    const noRiggory = dragulaExterminationRiggoryDisabled();

    const highestPPE = Math.max(0, ...ppeRows.map(row => row.ppe));
    const lowestPPE = Math.min(5, ...ppeRows.map(row => row.ppe));
    const biggestExterminationGap = Math.max(0, ...performances.map(p => p.score)) - Math.min(100, ...performances.map(p => p.score));

    const genuineExterminationUpset = ppeRows.length>=2 && highestPPE-lowestPPE>=0.65 &&
      biggestExterminationGap>=45 && ppeRows.some(row => row.ppe>=highestPPE-0.01 &&
        (exterminationById.get(normalizeContestantId(row.id)) ?? 100)<=26);
    const shockingUpset = !noRiggory && longestHistory>=2 && genuineExterminationUpset && Math.random()<0.015;
    const decisionMethod = noRiggory || shockingUpset ? "extermination" : "balanced";
    const extermWeight = longestHistory === 0 ? 0.82 : (longestHistory < 2 ? 0.43 : 0.24);
    const ppeWeight = longestHistory === 0 ? 0.10 : (longestHistory < 2 ? 0.48 : 0.69);
    const floorWeight = longestHistory === 0 ? 0.08 : (longestHistory < 2 ? 0.09 : 0.07);
    const dangerById = new Map(bottomIds.map((id) => {
      const key = normalizeContestantId(id);
      const exterminationScore = exterminationById.get(key);
      const floorScore = floorPerformanceById.get(key);
      const exterminationDanger = Number.isFinite(exterminationScore)
        ? 1 - clamp01(exterminationScore / 100)
        : 0.5;
      const ppe = ppeById.get(key) ?? 3;
      const priorHistory = ppeRows.find(row=>normalizeContestantId(row.id)===key)?.history || 0;

      const frontRunnerCredit = priorHistory>=2 && ppe>=3.25 && ppe-lowestPPE>=0.75
        ? Math.min(0.075, 0.025 + (ppe-lowestPPE-0.75)*0.025)
        : 0;
      const ppeDanger = 1 - clamp01(ppe / 5);
      const floorDanger = Number.isFinite(floorScore) && floorScoreRange > 0
        ? clamp01((floorScore - bestFloorScore) / floorScoreRange)
        : 0.5;
      return [key, decisionMethod === "extermination"
        ? exterminationDanger
        : extermWeight * exterminationDanger + ppeWeight * ppeDanger + floorWeight * floorDanger - frontRunnerCredit];
    }));
    const dangerOrder = [...bottomIds].sort((a, b) =>
      (dangerById.get(normalizeContestantId(b)) ?? 0.5) - (dangerById.get(normalizeContestantId(a)) ?? 0.5)
      || (exterminationById.get(normalizeContestantId(a)) ?? 100) - (exterminationById.get(normalizeContestantId(b)) ?? 100)
    );

    const doubleSuitability = dragulaDoubleOutcomeSuitability(bottomIds, participants, priorEpisodes, floorShow, performances);

    if (bottomIds.length > 2) {
      const victims = dragulaDoubleOutcomeSuitability(dangerOrder.slice(0, 2), participants, priorEpisodes, floorShow, performances);
      doubleSuitability.double = victims.double;
      doubleSuitability.doubleTargets = victims.records;
    }

    const strongestBottom = Math.max(0, ...((doubleSuitability.doubleTargets || doubleSuitability.records) || []).map(r => r.strength));
    const weakestBottom = Math.min(1, ...(doubleSuitability.records || []).map(r => r.strength));
    const takeSave = forceDoubleSave && (saveUrgent ||
      (doubleSuitability.save >= 0.51 && weakestBottom >= 0.39));
    const takeDouble = forceDoubleElimination && dangerOrder.length >= 2 &&
      (doubleUrgent || (doubleSuitability.double >= 0.46 && strongestBottom <= 0.65));
    let eliminatedIds = [];
    let resultType = "normal";
    if (takeSave) {
      resultType = "double-save";
    } else if (takeDouble) {
      resultType = "double-elimination";
      eliminatedIds = dangerOrder.slice(0, 2);
    } else if (dangerOrder.length) {
      eliminatedIds = [dangerOrder[0]];
    }

    const eliminatedKeys = new Set(eliminatedIds.map((id) => normalizeContestantId(id)));
    const survivorIds = bottomIds.filter((id) => !eliminatedKeys.has(normalizeContestantId(id)));
    const scene = structuredClone(floorShow?.resultScene || {});
    const trackResults = {};
    bottomIds.forEach((id) => {
      const eliminated = eliminatedKeys.has(normalizeContestantId(id));
      const keyNominated = Boolean(
        episode?.keyOfLifeDeath?.nominatedId &&
        normalizeContestantId(episode.keyOfLifeDeath.nominatedId) === normalizeContestantId(id)
      );
      trackResults[id] = voteOffPremiere
        ? voteOffBottomResult(id, eliminated)
        : (eliminated ? "EXT" : (keyNominated ? bottomTrackLabel : (floorShow?.placements?.[id] || bottomTrackLabel)));
    });
    return {
      ...challengeData,
      performances,
      decisionMethod,
      resultType,
      doubleSuitability,
      doubleDecision: {
        saveCandidate: Boolean(forceDoubleSave), doubleCandidate: Boolean(forceDoubleElimination),
        deadline: Boolean((forceDoubleSave && saveUrgent) || (forceDoubleElimination && doubleUrgent)),
      },
      survivorIds,
      eliminatedIds,
      trackResults,
      resultScene: {
        title: scene.title || "Exterminated",
        story: dragulaMonsterCopy(
          String(scene.story || "After the extermination, {Contestant} disappears into the darkness.")
            .replaceAll("{Contestant}", "{name}")
        ),
      },
      resultRevealed: false,
    };
  }

  function dragulaCurrentPPEWithFloorShow(monsterId, priorEpisodes, floorShow, participants) {
    const provisional = {
      dragula: true,
      isFinale: false,
      castIds: (participants || []).map((monster) => monster.id),
      competitionCastIds: (participants || []).map((monster) => monster.id),
      floorShow,
      maxiChallenge: floorShow,
      dragulaTrackResults: { ...(floorShow?.placements || {}) },
    };
    return Number(calculateQueenPPE(monsterId, [...(priorEpisodes || []), provisional]).value) || 0;
  }

  function buildGhostlyGallows(episode, floorShow, participants, priorEpisodes = [], { eliminateCount = 1 } = {}) {
    const bottomIds = [...(floorShow?.bottomPoolIds || [])];
    const ppeRows = bottomIds.map((id) => ({
      id,
      ppe: dragulaCurrentPPEWithFloorShow(id, priorEpisodes, floorShow, participants),
      tie: Math.random(),
    })).sort((a, b) => a.ppe - b.ppe || a.tie - b.tie);
    const eliminatedIds = ppeRows.slice(0, Math.max(1, Math.min(eliminateCount, ppeRows.length))).map((row) => row.id);
    const eliminatedKeys = new Set(eliminatedIds.map(normalizeContestantId));
    const survivorIds = bottomIds.filter((id) => !eliminatedKeys.has(normalizeContestantId(id)));
    const trackResults = {};
    bottomIds.forEach((id) => { trackResults[id] = floorShow?.placements?.[id] || dragulaBottomTrackLabel(bottomIds); });
    eliminatedIds.forEach((id) => { trackResults[id] = "ELIM"; });
    return {
      occurs: true,
      id: "ghostly-gallows",
      name: "None (Ghostly Gallows)",
      description: "Welcome to the Ghostly Gallows. Your fate lies in here.",
      bottomIds,
      survivorIds,
      eliminatedIds,
      trackResults,
      decisionMethod: "ppe",
      resultType: "ghostly-gallows",
      resultRevealed: false,
    };
  }

  function configureSonicTransducerFloorShow(floorShow, participants, winnerIdOverride = null) {
    if (!floorShow) return null;
    const ordered = [...(floorShow.performances || [])].sort((a, b) => Number(a.score) - Number(b.score));
    const existingWinnerId = Object.entries(floorShow.placements || {}).find(([, value]) => String(value || "").trim() === "WIN")?.[0] || null;
    const forcedWinnerId = (participants || []).map((monster) => monster.id).find((id) => normalizeContestantId(id) === normalizeContestantId(winnerIdOverride));
    const winnerId = forcedWinnerId || existingWinnerId || ordered[0]?.id || participants?.[0]?.id || null;
    const placements = Object.fromEntries((participants || []).map((monster) => [monster.id, "SAFE"]));
    if (winnerId) placements[winnerId] = "WIN";
    floorShow.placements = placements;
    floorShow.topPoolIds = winnerId ? [winnerId] : [];
    floorShow.bottomPoolIds = [];
    floorShow.judgedIds = (participants || []).map((monster) => monster.id);
    floorShow.safeIds = [];
    floorShow.judgedAsTeams = false;
    floorShow.judgedAsPairs = false;
    floorShow.pairJudgingMode = floorShow.format === "pairs" ? "individual" : "";
    floorShow.hesitantWinnerBottomId = null;
    return winnerId;
  }

  function buildSonicTransducer(episode, floorShow, participants, priorEpisodes = [], { winnerIdOverride = null, targetIdOverride = null, immuneIds = [] } = {}) {
    const winnerId = configureSonicTransducerFloorShow(floorShow, participants, winnerIdOverride);
    if (!winnerId) return null;
    const immuneKeys = new Set((immuneIds || []).map(normalizeContestantId));
    const eligible = (participants || []).filter((monster) => normalizeContestantId(monster.id) !== normalizeContestantId(winnerId) &&
      !immuneKeys.has(normalizeContestantId(monster.id)));
    if (!eligible.length) return null;
    let strategy = Math.random() < 0.80 ? "worstsister" : "best-ppe";
    let targetId = null;
    if (strategy === "worstsister") {
      targetId = dragulaWorstSisterId(winnerId, participants, [winnerId, ...immuneKeys]);
    } else {
      const rows = eligible.map((monster) => ({
        id: monster.id,
        ppe: dragulaCurrentPPEWithFloorShow(monster.id, priorEpisodes, floorShow, participants),
        tie: Math.random(),
      })).sort((a, b) => b.ppe - a.ppe || a.tie - b.tie);
      targetId = rows[0]?.id || null;
    }
    const forcedTargetId = eligible.map((monster) => monster.id).find((id) => normalizeContestantId(id) === normalizeContestantId(targetIdOverride));
    if (forcedTargetId) {
      strategy = "boulets";
      targetId = forcedTargetId;
    }
    if (!targetId) {
      strategy = "worstsister";
      targetId = pickRandom(eligible)?.id || eligible[0]?.id || null;
    }
    const trackResults = Object.fromEntries((participants || []).map((monster) => [monster.id, normalizeContestantId(monster.id) === normalizeContestantId(winnerId) ? "WIN" : "SAFE"]));
    if (targetId) trackResults[targetId] = "ELIM";
    return {
      occurs: true,
      winnerId,
      targetId,
      strategy,
      resultRevealed: false,
      trackResults,
      extermination: {
        occurs: true,
        id: "sonic-transducer",
        name: "None (Sonic Transducer)",
        description: "The Sonic Transducer has replaced the extermination.",
        bottomIds: targetId ? [targetId] : [],
        survivorIds: (participants || []).map((monster) => monster.id).filter((id) => normalizeContestantId(id) !== normalizeContestantId(targetId)),
        eliminatedIds: targetId ? [targetId] : [],
        trackResults: targetId ? { [targetId]: "ELIM" } : {},
        decisionMethod: strategy,
        resultType: "sonic-transducer",
        resultRevealed: false,
      },
    };
  }

  function generateHellboundShowdownPerformance(monster, challenge) {
    const weightedSkill = Object.entries(challenge?.requiredSkills || {}).reduce(
      (sum, [skill, weight]) => sum + (Number(monster?.skills?.[skill]) || 0) * Number(weight || 0),
      0
    );
    const baseRoll = performanceRoll(15, 35);
    const score = baseRoll - weightedSkill;
    const bracket = performanceBracket(score);
    return {
      id: monster.id,
      weightedSkill,
      baseRoll,
      score,
      adjustedScore: score,
      bracket,
      commentBracket: bracket,
    };
  }

  function buildHellboundShowdown(participantIds, challenge, wholeCast, { final = false } = {}) {
    const monsters = (participantIds || [])
      .map((id) => (wholeCast || []).find((monster) => normalizeContestantId(monster.id) === normalizeContestantId(id)))
      .filter(Boolean);
    if (monsters.length < 2) return null;

    const performances = monsters.map((monster) => generateHellboundShowdownPerformance(monster, challenge));
    assignPerformanceCommentBrackets(performances);
    const ordered = [...performances].sort((a, b) => Number(a.score) - Number(b.score) || Math.random() - 0.5);
    const winnerId = ordered[0]?.id || null;
    const loserIds = ordered.slice(1).map((item) => item.id);
    return {
      version: 1,
      final: Boolean(final),
      participantIds: monsters.map((monster) => monster.id),
      challenge: {
        id: challenge?.id || (final ? "hellbound-final-lipsync" : "hellbound-floor-show"),
        name: challenge?.name || (final ? "Lip Sync" : "Floor Show"),
        description: dragulaMonsterCopy(challenge?.description || "The exterminated monsters battle for another chance at life."),
        requiredSkills: structuredClone(challenge?.requiredSkills || challenge?.skills || {}),
        sourceType: challenge?.sourceType || challenge?.type || "performance",
      },
      performances,
      winnerId,
      loserIds,
      resultRevealed: false,
    };
  }

  function hellboundTrackResultsForShowdown(showdown, { final = false } = {}) {
    if (!showdown) return {};
    const results = {};
    if (showdown.winnerId) results[showdown.winnerId] = final ? "RTRN" : "WIN";
    (showdown.loserIds || []).forEach((id) => { results[id] = "LOSS"; });
    return results;
  }

