      const announcement = document.createElement("p");
      announcement.className = "golden-baguette-handoff__announcement";
      announcement.textContent = event.joint
        ? `${joinQueenNames(event.giverIds || [])} have chosen to pass the Golden Baguette to... ${joinQueenNames([event.recipientId])}!`
        : `${joinQueenNames(event.giverIds || [])} has chosen to pass the Golden Baguette to... ${joinQueenNames([event.recipientId])}!`;
      shell.append(announcement);

      const power = document.createElement("p");
