  function renderHeartSuccessorSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const event = episode?.heartInheritance;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--heart-successor";
    if (!event) return;

    const shell = document.createElement("section");
    shell.className = "heart-successor-handoff";
    const title = document.createElement("h2");
    title.className = "heart-successor-handoff__title";
    title.textContent = "Heart Successor";
    shell.append(title);

    if (event.ending) {
      shell.append(makeHeartObject("full"));
      const ending = document.createElement("p");
      ending.className = "heart-successor-copy heart-successor-copy--strong";
      ending.textContent = "With the finalists decided, the Heart Successor twist has come to an end. Any remaining half-hearts are now ceremonial.";
      shell.append(ending);
    } else {
      (event.transfers || []).forEach((transfer, index) => {
        if (index > 0) {
          const divider = document.createElement("hr");
          divider.className = "heart-successor-divider";
          shell.append(divider);
        }

        const giverLine = document.createElement("div");
        giverLine.className = "heart-successor-lineup";
        const giver = makeHeartSuccessorPortrait(transfer.giverId, "giver");
        if (giver) giverLine.append(giver);
        shell.append(giverLine);

        const before = document.createElement("p");
        before.className = "heart-successor-copy";
        before.textContent = transfer.emergency
          ? `${joinQueenNames([transfer.giverId])}'s half-heart must remain in the competition.`
          : `${joinQueenNames([transfer.giverId])}, before you leave the competition, you have one final decision to make. You must choose one remaining contestant to inherit your half of the heart.`;
        shell.append(before);

        const transferLine = document.createElement("div");
        transferLine.className = "heart-successor-transfer";
        const giverAgain = makeHeartSuccessorPortrait(transfer.giverId, "giver");
        if (giverAgain) transferLine.append(giverAgain);
        transferLine.append(makeHeartObject("half"));
        const arrow = document.createElement("span");
        arrow.className = "heart-successor-arrow";
        arrow.textContent = "→";
        transferLine.append(arrow);
        const recipient = makeHeartSuccessorPortrait(transfer.recipientId, transfer.completedHeart ? "ready" : "successor");
        if (recipient) transferLine.append(recipient);
        shell.append(transferLine);

        const announcement = document.createElement("p");
        announcement.className = "heart-successor-announcement";
        announcement.textContent = transfer.emergency
          ? `${joinQueenNames([transfer.recipientId])} inherits the departing contestant's half-heart.`
          : `${joinQueenNames([transfer.giverId])} has chosen ${joinQueenNames([transfer.recipientId])} as her Heart Successor!`;
        shell.append(announcement);

        if (transfer.completedHeart) {
          const revealDivider = document.createElement("hr");
          revealDivider.className = "heart-successor-divider";
          const reveal = document.createElement("div");
          reveal.className = "heart-successor-full-reveal";
          const formula = document.createElement("div");
          formula.className = "heart-successor-combine";
          formula.append(makeHeartObject("half"));
          const plus = document.createElement("span");
          plus.textContent = "+";
          formula.append(plus, makeHeartObject("half"));
          const equals = document.createElement("span");
          equals.textContent = "=";
          formula.append(equals, makeHeartObject("full"));
          const ready = makeHeartSuccessorPortrait(transfer.recipientId, "ready");
          const text = document.createElement("p");
          text.className = "heart-successor-announcement heart-successor-announcement--full";
          text.textContent = `${joinQueenNames([transfer.recipientId])} has completed the heart! At the next elimination, they must save one contestant from the Bottom 3 - including themselves. The heart must be used at the next opportunity.`;
          reveal.append(formula);
          if (ready) reveal.append(ready);
          reveal.append(text);
          shell.append(revealDivider, reveal);
        }
      });
    }

    els.runtimeContent.append(shell);
  }

