  function renderCuntTestSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.cuntTest;
    if (!data) return;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--maxi";

    const root = document.createElement("div");
    root.className = "cunt-test-maxi-sequence";

    const parts = Array.isArray(data.parts) ? data.parts : [];
    const revealedParts = Math.max(0, Number(data.revealedParts) || 0);
    const visibleCount = Math.min(parts.length, revealedParts + 1);

    parts.slice(0, visibleCount).forEach((part, index) => {
      const maxi = part?.maxiChallenge;
      if (!maxi) return;

      const shell = document.createElement("div");
      shell.className = "maxi-performance-view cunt-test-round";

      const header = document.createElement("header");
      header.className = "maxi-challenge-header";

      const name = document.createElement("h3");
      name.className = "maxi-challenge-name";
      name.textContent = maxi.displayName || maxi.name;

      const description = document.createElement("p");
      description.className = "maxi-challenge-description";
      description.textContent = maxi.description;

      header.append(name, description);
      shell.append(header);

      if (maxi.category === "snatch_game") {
        shell.append(buildSnatchGameCast(maxi));
      }

      if (maxi.category === "talent_show") {
        shell.append(buildTalentShowActs(maxi));
      }

      if (maxi.format === "pairs" || maxi.format === "pairs_rivals") {
        shell.append(buildPairFormationDisplay(maxi));
        appendMaxiWorkroomEvents(shell, maxi);
        shell.append(buildMaxiPerformanceGroups(maxi));
      } else if (isDraftTeamFormat(maxi.format)) {
        const announcement = document.createElement("p");
        announcement.className = "team-draft-announcement";
        announcement.textContent =
          `${captainAnnouncementNames(maxi.captainIds)}, you're the captains, so you pick your teams.`;
        shell.append(announcement);

        if (!maxi.teamsRevealed) {
          const button = document.createElement("button");
          button.type = "button";
          button.className = "control-btn team-draft-show";
          button.textContent = "SHOW TEAMS";

          button.addEventListener("click", () => {
            const draftStage = buildTeamDraftStage(maxi, false);
            shell.insertBefore(draftStage, button);
            animateTeamDraft(shell, maxi, draftStage, button);
          });

          shell.append(button);
        } else {
          shell.append(buildTeamDraftStage(maxi, true));
          appendMaxiWorkroomEvents(shell, maxi);
          shell.append(buildMaxiPerformanceGroups(maxi));
        }
      } else {
        appendMaxiWorkroomEvents(shell, maxi);
        shell.append(buildMaxiPerformanceGroups(maxi));
      }

      const winnerAlreadyShown = index < revealedParts;

      if (!winnerAlreadyShown) {
        const actions = document.createElement("div");
        actions.className = "cunt-test-winner-action";

        const reveal = document.createElement("button");
        reveal.type = "button";
        reveal.className = "control-btn control-btn--accent cunt-test-show-winner";
        reveal.textContent = "SHOW WINNER";
        reveal.addEventListener("click", () => {
          data.revealedParts = index + 1;
          persistState();
          renderCuntTestSection();

          requestAnimationFrame(() => {
            const rounds = els.runtimeContent.querySelectorAll(".cunt-test-round");
            rounds[index]?.scrollIntoView({ behavior: "smooth", block: "start" });
          });
        });

        actions.append(reveal);
        shell.append(actions);
      } else {
        const winner = queenFromId(part.winnerId);
        if (winner) {
          const result = document.createElement("section");
          result.className = "performance-group performance-group--great cunt-test-winner-reveal";

          const lineup = document.createElement("div");
          lineup.className = "performance-group__lineup";
          lineup.append(makePerformanceContestant(winner, "GREAT"));

          const text = document.createElement("p");
          text.className = "performance-group__comment";
          text.textContent =
            `${winner.nickname || winner.fullName}, condragulations! You have won the ${part.partNumber} round of The C.U.N.T. Test! And you've made it into the Grand Finale!`;

          result.append(lineup, text);
          shell.append(result);
        }
      }

      root.append(shell);
    });

    els.nextSectionBtn.disabled = revealedParts < parts.length;
    els.runtimeContent.append(root);
  }

