  function renderRunwaySection() {
    clearRuntimeTimers();

    const episode = currentEpisodeData();
    const maxi = episode?.maxiChallenge;
    const finale = episode?.isFinale ? episode.finale : null;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--runway";

    if (!finale && !maxi?.separateRunway) {
      renderPlaceholderSection();
      return;
    }

    const runwayTheme = finale?.runwayTheme || maxi?.runwayTheme || "Best Drag";
    const runwayResults = finale?.runwayResults || maxi?.runwayResults || [];

    const shell = document.createElement("div");
    shell.className = "runway-view";

    const hideLFTFCategory = Boolean(finale?.lftfFinale && !finale?.runwayTheme);
    if (!hideLFTFCategory) {
      const category = document.createElement("h3");
      category.className = "runway-category";
      category.textContent = `Category is... ${runwayTheme}!`;
      shell.append(category);
    }

    const groups = document.createElement("div");
    groups.className = "runway-groups";

    ["SLAY", "GREAT", "GOOD", "BAD"].forEach((bracket) => {
      const results = runwayResults
        .filter((result) => (result.commentBracket || result.result) === bracket)
        .sort((a, b) => (a.rawScore ?? 999) - (b.rawScore ?? 999));

      if (!results.length) return;

      const section = document.createElement("section");
      section.className = `runway-group runway-group--${bracket.toLowerCase()}`;

      const lineup = document.createElement("div");
      lineup.className = "runway-group__lineup";

      results.forEach((result) => {
        const card = makeRunwayContestant(result);
        if (card) lineup.append(card);
      });

      const comment = document.createElement("p");
      comment.className = "runway-group__comment";
      comment.textContent = runwayComment(
        bracket,
        results.map((result) => result.id)
      );

      section.append(lineup, comment);
      groups.append(section);
    });

    shell.append(groups);
    els.runtimeContent.append(shell);
  }

  function makeJudgingQueen(id, mode = "judged", placement = "") {
    const queen = queenFromId(id);
    if (!queen) return null;

    const card = document.createElement("article");
    card.className = `judging-queen judging-queen--${mode}`;
    if (placement) {
      card.classList.add(`placement-${placement.toLowerCase().replaceAll(" ", "-")}`);
    }

    const image = document.createElement("img");
    image.className = "judging-queen__image";
    image.src = imageSrc(queen);
    image.alt = queen.fullName || queen.nickname || "Contestant";
    image.addEventListener("error", () => image.removeAttribute("src"), { once: true });

    const name = document.createElement("span");
    name.className = "judging-queen__name";
    name.textContent = queen.nickname || queen.fullName || queen.id;

    card.append(image, name);

    if (placement) {
      const tag = document.createElement("span");
      tag.className = "judging-queen__placement";
      tag.textContent = placement;
      card.append(tag);
    }

    return card;
  }

  function appendQueenLineup(parent, ids, mode, placement = "") {
    const lineup = document.createElement("div");
    lineup.className = "judging-lineup";
    ids.forEach((id) => {
      const card = makeJudgingQueen(id, mode, placement);
      if (card) lineup.append(card);
    });
    parent.append(lineup);
    return lineup;
  }

