    renderClassicImmunitySave(shell, episode);
    renderPlacementGroup(shell, maxi, "LOW", "LOW");
    [...new Set(Object.values(maxi.placements || {}).filter((value) => /^BTM\d+$/.test(String(value || ""))))]
      .sort((a, b) => Number(a.slice(3)) - Number(b.slice(3)))
