          line.className = "legacy-lipstick-result__choice";
          line.textContent = `${joinQueenNames([lipSync.topAllStarId])} chose ${joinQueenNames([lipSync.lipstickVictimIds[0]])}'s lipstick!`;
          lipstickBlock.append(line);
