  function renderSheDoneAlreadyDoneHadHersesSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const consolation = episode?.finale?.consolation;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--she-done runtime-content--lipsync";
    if (!consolation) return;

    const shell = document.createElement("div");
    shell.className = "lalaparuza-view lipsync-performance-view she-done-view";
    const intro = document.createElement("p");
    intro.className = "finale-announcement she-done-intro";
    intro.textContent = "Every contestant outside the Top 4 will compete in the She Done Already Done Had Herses lip-sync smackdown.";
    shell.append(intro);

    const flatMatchups = Array.isArray(consolation.flatMatchups) && consolation.flatMatchups.length
      ? consolation.flatMatchups
      : (consolation.rounds || []).flatMap((round) => round.matchups || []);
    const visibleCount = Math.min(flatMatchups.length, Math.max(1, Number(consolation.visibleMatchupCount) || 1));

    flatMatchups.slice(0, visibleCount).forEach((matchup, flatIndex) => {
      const block = document.createElement("section");
      block.className = "lalaparuza-matchup porkchop-matchup she-done-match";
      const previous = flatMatchups[flatIndex - 1];
      if (flatIndex === 0 || previous?.round !== matchup.round) {
        const roundTitle = document.createElement("h3");
        roundTitle.className = "lalaparuza-progressive-round-title";
        roundTitle.textContent = matchup.final ? "FINAL LIP SYNC" : `ROUND ${matchup.round}`;
        block.append(roundTitle);
      }

      const song = document.createElement("header");
      song.className = "lipsync-song lalaparuza-matchup__song";
      const songTitle = document.createElement("h3");
      songTitle.className = "lipsync-song__title";
      songTitle.textContent = matchup.song?.song || "Lip Sync";
      const artist = document.createElement("p");
      artist.className = "lipsync-song__artist";
      artist.textContent = matchup.song?.artist || "";
      song.append(songTitle, artist);
      block.append(song);

      const performances = document.createElement("div");
      performances.className = "lipsync-performance-list lalaparuza-performance-list";
      (matchup.performances || []).forEach((performance) => {
        const card = makeLipSyncPerformanceCard(performance, matchup.event);
        if (card) performances.append(card);
      });
      block.append(performances);

      if (!matchup.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn lipsync-show-results lalaparuza-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          matchup.resultRevealed = true;
          consolation.visibleMatchupCount = Math.min(flatMatchups.length, flatIndex + 2);
          persistState();
          button.classList.add("is-leaving");
          window.setTimeout(() => renderSheDoneAlreadyDoneHadHersesSection(), 180);
        });
        block.append(button);
      } else {
        const lineup = document.createElement("div");
        lineup.className = "lipsync-result-lineup lalaparuza-result-lineup";
        (matchup.performerIds || []).forEach((id) => {
          const isWinner = normalizeContestantId(id) === normalizeContestantId(matchup.winnerId);
          const portrait = makeLipSyncResultQueen(id, isWinner ? "survivor" : "eliminated");
          if (portrait) lineup.append(portrait);
        });
        block.append(lineup);
        const result = document.createElement("div");
        result.className = "lipsync-result-copy lalaparuza-matchup__result";
        const winnerLine = document.createElement("p");
        winnerLine.textContent = `${joinQueenNames([matchup.winnerId])}, shantay you stay in the tournament.`;
        result.append(winnerLine);
        (matchup.loserIds || []).forEach((id) => {
          const lossLine = document.createElement("p");
          lossLine.textContent = `${joinQueenNames([id])}, sashay away from the tournament.`;
          result.append(lossLine);
        });
        block.append(result);
      }
      shell.append(block);
    });

    const allRevealed = flatMatchups.length && flatMatchups.every((matchup) => matchup.resultRevealed);
    if (allRevealed && consolation.winnerId) {
      const winner = document.createElement("section");
      winner.className = "she-done-winner";
      appendQueenLineup(winner, [consolation.winnerId], "placement", "WIN");
      const copy = document.createElement("p");
      copy.className = "finale-announcement";
      copy.textContent = `${joinQueenNames([consolation.winnerId])} is the Queen of She Done Already Done Had Herses!`;
      winner.append(copy);
      shell.append(winner);
    }

    els.runtimeContent.append(shell);
  }

