        winnerCard.className = "mini-winner-reveal__winner";

        const image = document.createElement("img");
        image.className = "mini-winner-reveal__image mx-con-winner__image finale-single-award__image";
        image.src = imageSrc(winnerQueen);
        image.alt = winnerQueen.fullName || winnerQueen.nickname || config.name;
