  function renderFinalResultsSection() {
    clearRuntimeTimers();

    const episode = currentEpisodeData();
    const finale = episode?.finale;
    const lipSync = finale?.finalLipSync;

    if (finale?.lftc) {
      renderLipSyncForTheCrownFinalResults();
      return;
    }

    if (finale?.lftfFinale) {
      renderLFTFFinalResults();
      return;
    }

    if (finale?.juryFinale) {
      renderJuryFinalResults();
      return;
    }

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className =
      "runtime-content runtime-content--final-results";

    if (!finale || !lipSync) return;

    const shell = document.createElement("div");
    shell.className = "finale-results-view";

    if (!lipSync.resultRevealed) {
      const button = document.createElement("button");
      button.type = "button";
      button.className =
        "control-btn lipsync-show-results finale-show-results";
      button.textContent = "SHOW RESULTS";

      button.addEventListener("click", () => {
        lipSync.resultRevealed = true;
        persistState();

        button.classList.add("is-leaving");
        window.setTimeout(() => {
          renderFinalResultsSection();
          if (runtimeHasHoliSlay()) {
            renderRuntimeSectionTabs();
            els.nextSectionBtn.disabled = false;
            updateUniverseSaveButton();
          }
          window.requestAnimationFrame(() => {
            launchFinaleConfetti();
          });
        }, 180);
      });

      shell.append(button);
      els.runtimeContent.append(shell);
      return;
    }

    const winnerIds = lipSync.winnerIds?.length ? lipSync.winnerIds : (lipSync.winnerId ? [lipSync.winnerId] : []);
    const winnerLineup = document.createElement("div");
    winnerLineup.className = "finale-lineup";
    winnerIds.forEach((id) => {
      const winner = makeFinaleQueen(id, "winner");
      if (winner) winnerLineup.append(winner);
    });
    if (winnerLineup.children.length) shell.append(winnerLineup);

    const winnerCopy = document.createElement("p");
    winnerCopy.className = "finale-winner-copy";
    winnerCopy.textContent = lipSync.doubleCrowning
      ? `For the FIRST TIME in Drag Race herstory, ${joinQueenNames(winnerIds)}, you are both winners, baby!`
      : `${joinQueenNames(winnerIds)}, condragulations, you are the winner of The Crown!`;
    shell.append(winnerCopy);

    if (lipSync.runnerUpIds?.length) {
      const runners = document.createElement("div");
      runners.className = "finale-runners";

      appendFinaleLineup(
        runners,
        lipSync.runnerUpIds,
        "runner-up"
      );

      const runnerCopy = document.createElement("p");
      runnerCopy.className = "finale-runner-copy";
      runnerCopy.textContent =
        lipSync.runnerUpIds.length === 1
          ? `${joinQueenNames(lipSync.runnerUpIds)} finishes as the runner-up.`
          : `${joinQueenNames(lipSync.runnerUpIds)} finish as the runners-up.`;

      runners.append(runnerCopy);
      shell.append(runners);
    }

    els.runtimeContent.append(shell);
  }

