    const shell = document.createElement('div');
    shell.className = 'rate-a-queen-view';
    const intro = document.createElement('p');
    intro.className = 'rate-a-queen-intro';
    intro.textContent = episode?.premiereMode === 'rateaqueen17'
      ? 'This week, the contestants watching the performances hold the power. Their rankings will determine the results.'
      : episode?.premiereMode === 'nonelimrateaqueen'
        ? 'This week, every contestant will rate every one of their competitors. Those rankings will determine the Top 2, the highs, the safes, and the bottoms of the premiere.'
        : 'This week, your fate lies in the hands of your competitors. It will be up to you to rate your fellow contestants.';
    shell.append(intro);

