  function renderPorkchopLipSyncsSection() {
    clearRuntimeTimers();
    const data = currentEpisodeData()?.porkchop;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = 'runtime-content runtime-content--porkchop';
    if (!data) return;

    const shell = document.createElement('div');
    shell.className = 'porkchop-view';

    const visibleCount = Math.min(
      data.matchups.length,
      Math.max(1, Number(data.visibleMatchupCount) || 1)
    );

    data.matchups.slice(0, visibleCount).forEach((matchup, index) => {
      const block = document.createElement('section');
      block.className = 'porkchop-matchup';

      const song = document.createElement('header');
      song.className = 'lipsync-song porkchop-song';
      const songName = document.createElement('h3');
      songName.className = 'lipsync-song__title';
      songName.textContent = matchup.song.song;
      const artist = document.createElement('p');
      artist.className = 'lipsync-song__artist';
      artist.textContent = matchup.song.artist;
      song.append(songName, artist);

      const performances = document.createElement('div');
      performances.className = 'lipsync-performance-list porkchop-performance-list';
      matchup.performances.forEach((performance) => {
        const card = makeLipSyncPerformanceCard(performance, matchup.event);
        if (card) performances.append(card);
      });

      block.append(song, performances);

      if (!matchup.resultRevealed) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'control-btn lipsync-show-results porkchop-show-results';
        button.textContent = 'SHOW RESULTS';
        button.addEventListener('click', () => {
          matchup.resultRevealed = true;
          data.visibleMatchupCount = Math.min(data.matchups.length, index + 2);
          persistState();
          button.classList.add('is-leaving');
          window.setTimeout(() => renderPorkchopLipSyncsSection(), 180);
        });
        block.append(button);
      } else {
        const lineup = document.createElement('div');
        lineup.className = 'porkchop-lineup';
        matchup.performerIds.forEach((id) => {
          const portrait = makeLipSyncResultQueen(
            id,
            normalizeContestantId(id) === normalizeContestantId(matchup.winnerId)
              ? 'porkchop-winner'
              : 'porkchop-loser'
          );
          if (portrait) lineup.append(portrait);
        });

        const result = document.createElement('div');
        result.className = 'porkchop-result-copy';
        const win = document.createElement('p');
        win.textContent = `${joinQueenNames([matchup.winnerId])}, shantay you stay!`;
        result.append(win);
        matchup.loserIds.forEach((id) => {
          const loss = document.createElement('p');
          loss.textContent = `${joinQueenNames([id])}, you're getting the porkchop...`;
          result.append(loss);
        });
        block.append(lineup, result);
      }

      shell.append(block);
    });

    els.runtimeContent.append(shell);
  }

  function renderPorkchopVoteSection() {
    clearRuntimeTimers();
    const data = currentEpisodeData()?.porkchop;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = 'runtime-content runtime-content--porkchop-vote';
    if (!data) return;

    const shell = document.createElement('div');
    shell.className = 'mini-challenge-view mx-con-view porkchop-vote-view';

    const intro = document.createElement('p');
    intro.className = 'porkchop-intro';
    intro.textContent = 'The porkchop contestants will vote for one contestant from their group.';
    shell.append(intro);

    const makeVoteRows = (ballots) => {
      const votes = document.createElement('div');
      votes.className = 'mini-performance-grid mx-con-votes porkchop-votes';

      ballots.forEach((vote) => {
        const row = document.createElement('article');
        row.className = 'mini-performance mx-con-vote-row';

        const portraits = document.createElement('div');
        portraits.className = 'mx-con-vote-portraits';
        const voter = makeMxCongVotePortrait(vote.voterId, 'voter');
        const recipient = makeMxCongVotePortrait(vote.targetId, 'recipient');
        if (voter) portraits.append(voter);
        if (recipient) portraits.append(recipient);

        const text = document.createElement('p');
        text.className = 'mini-performance__comment mx-con-vote-comment';
        text.textContent = `${joinQueenNames([vote.voterId])} voted for ${joinQueenNames([vote.targetId])}!`;

        row.append(portraits, text);
        votes.append(row);
      });

      return votes;
    };

    const makeTally = (totals, label = 'VOTE TALLY') => {
      const section = document.createElement('section');
      section.className = 'porkchop-tally-section';
      const heading = document.createElement('p');
      heading.className = 'porkchop-tally-title';
      heading.textContent = label;
      const row = document.createElement('div');
      row.className = 'porkchop-tally-row';

      [...totals]
        .sort((a, b) => b.votes - a.votes)
        .forEach((item) => {
          const queen = queenFromId(item.id);
          if (!queen) return;
          const card = document.createElement('article');
          card.className = 'porkchop-tally-contestant';
          const image = document.createElement('img');
          image.className = 'porkchop-tally-contestant__image';
          image.src = imageSrc(queen);
          image.alt = queen.fullName || queen.nickname || 'Contestant';
          image.addEventListener('error', () => image.removeAttribute('src'), { once: true });
          const name = document.createElement('strong');
          name.className = 'porkchop-tally-contestant__name';
          name.textContent = queen.nickname || queen.fullName || queen.id;
          const votes = document.createElement('span');
          votes.className = 'porkchop-tally-contestant__votes';
          votes.textContent = `${item.votes} VOTE${item.votes === 1 ? '' : 'S'}`;
          card.append(image, name, votes);
          row.append(card);
        });

      section.append(heading, row);
      return section;
    };

    shell.append(makeVoteRows(data.votes));
    shell.append(makeTally(data.initialVoteTotals || data.voteTotals || []));

    if (data.revote?.length) {
      const revoteTitle = document.createElement('p');
      revoteTitle.className = 'porkchop-revote-title';
      revoteTitle.textContent = "It's a tie! The porkchop contestants will revote...";
      shell.append(revoteTitle, makeVoteRows(data.revote));
      shell.append(makeTally(data.voteTotals || [], 'FINAL VOTE TALLY'));
    }

    const result = document.createElement('p');
    result.className = 'porkchop-voted-result';
    result.textContent = 'The contestant getting the porkchop is...';
    shell.append(result);
    const portrait = makeLipSyncResultQueen(data.votedId, 'returned');
    if (portrait) {
      const portraitWrap = document.createElement('div');
      portraitWrap.className = 'porkchop-voted-portrait-wrap';
      portraitWrap.append(portrait);
      shell.append(portraitWrap);
    }
    els.runtimeContent.append(shell);
  }

  function renderReunionLipSyncSmackdownSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.reunionSmackdown;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--reunion-smackdown runtime-content--lalaparuza runtime-content--lipsync";
    if (!data) return;

    const shell = document.createElement("div");
    shell.className = "lalaparuza-view lipsync-performance-view reunion-smackdown-view";

    const header = document.createElement("header");
    header.className = "reunion-smackdown-header";
    const title = document.createElement("h2");
    title.textContent = "Lip Sync Smackdown!!";
    const intro = document.createElement("p");
    intro.textContent = "All of the eliminated contestants return to battle it out in a Lip Sync Lalaparuza Smackdown for the title of Queen of She Done Already Done Had Herses and a cash prize on the line.";
    header.append(title, intro);
    shell.append(header);

    const flatMatchups = [];
    (data.rounds || []).forEach((round) => {
      (round.matchups || []).forEach((matchup, index) => {
        flatMatchups.push({ round, matchup, index });
      });
    });

    const visibleCount = Math.min(
      flatMatchups.length,
      Math.max(1, Number(data.visibleMatchupCount) || 1)
    );

    flatMatchups.slice(0, visibleCount).forEach(({ round, matchup }, flatIndex) => {
      const block = document.createElement("section");
      block.className = `lalaparuza-matchup porkchop-matchup reunion-smackdown-match lalaparuza-round--${round.round}`;

      const previous = flatMatchups[flatIndex - 1];
      const startsRound = flatIndex === 0 || previous?.round?.round !== round.round;
      if (startsRound) {
        const roundTitle = document.createElement("h3");
        roundTitle.className = "lalaparuza-progressive-round-title";
        roundTitle.textContent = round.final ? "FINAL ROUND" : `ROUND ${round.round}`;
        block.append(roundTitle);
      }

      const song = document.createElement("header");
      song.className = "lipsync-song lalaparuza-matchup__song";
      const songTitle = document.createElement("h3");
      songTitle.className = "lipsync-song__title";
      songTitle.textContent = matchup.song?.song || "Lip Sync";
      const artist = document.createElement("p");
      artist.className = "lipsync-song__artist";
      artist.textContent = matchup.song?.artist || "";
      song.append(songTitle, artist);
      block.append(song);

      const performances = document.createElement("div");
      performances.className = "lipsync-performance-list lalaparuza-performance-list reunion-smackdown-performance-list";
      (matchup.performances || []).forEach((performance) => {
        const card = makeLipSyncPerformanceCard(performance, matchup.event);
        if (card) performances.append(card);
      });
      block.append(performances);

      if (!matchup.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn lipsync-show-results lalaparuza-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          matchup.resultRevealed = true;
          data.visibleMatchupCount = Math.min(flatMatchups.length, flatIndex + 2);
          persistState();
          button.classList.add("is-leaving");
          window.setTimeout(() => renderReunionLipSyncSmackdownSection(), 180);
        });
        block.append(button);
      } else {
        const lineup = document.createElement("div");
        lineup.className = "lipsync-result-lineup lalaparuza-result-lineup reunion-smackdown-result-lineup";
        (matchup.performerIds || []).forEach((id) => {
          const isWinner = normalizeContestantId(id) === normalizeContestantId(matchup.winnerId);
          const portrait = makeLipSyncResultQueen(id, isWinner ? "winner" : "reunion-loser");
          if (portrait) lineup.append(portrait);
        });
        block.append(lineup);

        const result = document.createElement("div");
        result.className = "lipsync-result-copy lalaparuza-matchup__result reunion-smackdown-match__result";
        if (matchup.winnerId) {
          const win = document.createElement("p");
          win.textContent = `${joinQueenNames([matchup.winnerId])}, condragulations. You are a winner, baby!`;
          result.append(win);
        }
        (matchup.loserIds || []).forEach((id) => {
          const loss = document.createElement("p");
          loss.textContent = `${joinQueenNames([id])}, thank you for an unforgettable season.`;
          result.append(loss);
        });
        block.append(result);
      }

      shell.append(block);
    });

    const finalEntry = flatMatchups[flatMatchups.length - 1];
    const tournamentComplete = Boolean(
      finalEntry?.matchup?.resultRevealed && visibleCount >= flatMatchups.length
    );

    if (tournamentComplete && data.winnerId) {
      const crown = document.createElement("section");
      crown.className = "reunion-smackdown-crown";
      const reveal = document.createElement("p");
      reveal.className = "reunion-smackdown-crown__reveal";
      reveal.textContent = "The Queen of She Done Already Done Had Herses is...";
      const lineup = document.createElement("div");
      lineup.className = "lipsync-result-lineup reunion-smackdown-crown__lineup";
      const winner = makeLipSyncResultQueen(data.winnerId, "winner");
      if (winner) lineup.append(winner);
      const copy = document.createElement("p");
      copy.className = "reunion-smackdown-crown__copy";
      copy.textContent = `${joinQueenNames([data.winnerId])}, condragulations. You are a winner, baby!`;
      crown.append(reveal, lineup, copy);
      shell.append(crown);
    }

    els.runtimeContent.append(shell);
  }

  function renderGameWithinAGameSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.gameWithinGame;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--reunion-smackdown runtime-content--lalaparuza runtime-content--lipsync";
    if (!data) return;

    const rounds = Array.isArray(data.rounds) ? data.rounds : [];
    rounds.forEach((round) => {
      if (typeof round.resultRevealed !== "boolean") round.resultRevealed = false;
    });
    if (!Number.isFinite(Number(data.visibleRoundCount))) data.visibleRoundCount = 1;
    if (typeof data.resultsRevealed !== "boolean") {
      data.resultsRevealed = Boolean(rounds.length && rounds.every((round) => round.resultRevealed));
    }

    const shell = document.createElement("div");
    shell.className = "lalaparuza-view lipsync-performance-view reunion-smackdown-view";

    const header = document.createElement("header");
    header.className = "reunion-smackdown-header";
    const title = document.createElement("h2");
    title.textContent = "Game Within a Game";
    const intro = document.createElement("p");
    intro.textContent = "The eliminated contestants are back to compete in an epic Lip Sync Smackdown for a chance to return to the competition.";
    header.append(title, intro);
    shell.append(header);

    const visibleCount = Math.min(
      rounds.length,
      Math.max(1, Number(data.visibleRoundCount) || 1)
    );

    rounds.slice(0, visibleCount).forEach((round, index) => {
      const block = document.createElement("section");
      block.className = `lalaparuza-matchup porkchop-matchup reunion-smackdown-match lalaparuza-round--${round.round || index + 1}`;

      const roundTitle = document.createElement("h3");
      roundTitle.className = "lalaparuza-progressive-round-title";
      roundTitle.textContent = round.final ? "FINAL ROUND" : `ROUND ${round.round || index + 1}`;
      block.append(roundTitle);

      if (!(round.declinedId && round.advanceResult === "ADV")) {
        const song = document.createElement("header");
        song.className = "lipsync-song lalaparuza-matchup__song";
        const songTitle = document.createElement("h3");
        songTitle.className = "lipsync-song__title";
        songTitle.textContent = round.song?.song || "Lip Sync";
        const artist = document.createElement("p");
        artist.className = "lipsync-song__artist";
        artist.textContent = round.song?.artist || "";
        song.append(songTitle, artist);
        block.append(song);

        const performances = document.createElement("div");
        performances.className = "lipsync-performance-list lalaparuza-performance-list reunion-smackdown-performance-list";
        (round.performances || []).forEach((performance) => {
          const card = makeLipSyncPerformanceCard(performance, round.event);
          if (card) performances.append(card);
        });
        block.append(performances);
      }

      if (!round.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn lipsync-show-results lalaparuza-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          round.resultRevealed = true;
          data.visibleRoundCount = Math.min(rounds.length, index + 2);
          data.resultsRevealed = Boolean(rounds.length && rounds.every((item) => item.resultRevealed));
          persistState();
          button.classList.add("is-leaving");
          window.setTimeout(() => renderGameWithinAGameSection(), 180);
        });
        block.append(button);
      } else {
        const lineup = document.createElement("div");
        lineup.className = "lipsync-result-lineup lalaparuza-result-lineup reunion-smackdown-result-lineup";
        const winnerKeys = new Set((round.winnerIds || []).map((id) => normalizeContestantId(id)));
        (round.performerIds || []).forEach((id) => {
          const isWinner = winnerKeys.has(normalizeContestantId(id));
          const portrait = makeLipSyncResultQueen(id, isWinner ? "winner" : "reunion-loser");
          if (portrait) lineup.append(portrait);
        });
        block.append(lineup);

        const result = document.createElement("div");
        result.className = "lipsync-result-copy lalaparuza-matchup__result reunion-smackdown-match__result";
        if (round.doubleReturn) {
          const both = document.createElement("p");
          both.textContent = `${joinQueenNames(round.winnerIds || [])}, shantay you both stay!`;
          result.append(both);
        } else if (round.declinedId) {
          const declined = document.createElement("p");
          declined.textContent = `${joinQueenNames([round.declinedId])}, you have declined the invitation to return for your Rudemption.`;
          result.append(declined);
          const advance = document.createElement("p");
          advance.textContent = `${joinQueenNames([round.winnerId])}, you will advance in the Rudemption Smackdown.`;
          result.append(advance);
        } else {
          if (round.winnerId) {
            const win = document.createElement("p");
            win.textContent = `${joinQueenNames([round.winnerId])}, shantay you stay.`;
            result.append(win);
          }
          (round.loserIds || []).forEach((id) => {
            const loss = document.createElement("p");
            loss.textContent = `${joinQueenNames([id])}, sashay away.`;
            result.append(loss);
          });
        }
        block.append(result);
      }

      shell.append(block);
    });

    const tournamentComplete = Boolean(
      rounds.length &&
      rounds[rounds.length - 1]?.resultRevealed &&
      visibleCount >= rounds.length
    );

    if (tournamentComplete && (data.returneeIds || []).length) {
      const crown = document.createElement("section");
      crown.className = "reunion-smackdown-crown";
      const reveal = document.createElement("p");
      reveal.className = "reunion-smackdown-crown__reveal";
      reveal.textContent = data.returneeIds.length > 1
        ? "The contestants returning to the competition are..."
        : "The contestant returning to the competition is...";
      const lineup = document.createElement("div");
      lineup.className = "lipsync-result-lineup reunion-smackdown-crown__lineup";
      (data.returneeIds || []).forEach((id) => {
        const winner = makeLipSyncResultQueen(id, "winner");
        if (winner) lineup.append(winner);
      });
      const copy = document.createElement("p");
      copy.className = "reunion-smackdown-crown__copy";
      copy.textContent = `${joinQueenNames(data.returneeIds)}, you are back in the competition!`;
      crown.append(reveal, lineup, copy);
      shell.append(crown);
    }

    els.runtimeContent.append(shell);
  }

  function renderSlayOffExtravaganzaSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.slayOff;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--lalaparuza runtime-content--lipsync";
    if (!data) return;

    const shell = document.createElement("div");
    shell.className = "lalaparuza-view lipsync-performance-view";

    const rules = document.createElement("div");
    rules.className = "lalaparuza-rules";
    const ruleCopy = document.createElement("p");
    ruleCopy.textContent = "The contestants battle each other in a lip sync tournament extravaganza!";
    rules.append(ruleCopy);
    shell.append(rules);

    const flatMatchups = [];
    (data.rounds || []).forEach((round) => {
      (round.matchups || []).forEach((matchup, index) => {
        flatMatchups.push({ round, matchup, index });
      });
    });

    const visibleCount = Math.min(
      flatMatchups.length,
      Math.max(1, Number(data.visibleMatchupCount) || 1)
    );

    flatMatchups.slice(0, visibleCount).forEach(({ round, matchup }, flatIndex) => {
      const block = document.createElement("section");
      block.className = `lalaparuza-matchup porkchop-matchup lalaparuza-round--${round.round}`;

      const previous = flatMatchups[flatIndex - 1];
      const startsRound = flatIndex === 0 || previous?.round?.round !== round.round;
      if (startsRound) {
        const roundTitle = document.createElement("h3");
        roundTitle.className = "lalaparuza-progressive-round-title";
        roundTitle.textContent = round.final
          ? "FINAL ROUND"
          : round.round === 4
            ? "EXTRA ROUND"
            : `ROUND ${round.round}`;
        block.append(roundTitle);
      }

      const song = document.createElement("header");
      song.className = "lipsync-song lalaparuza-matchup__song";
      const songTitle = document.createElement("h3");
      songTitle.className = "lipsync-song__title";
      songTitle.textContent = matchup.song?.song || "Lip Sync";
      const artist = document.createElement("p");
      artist.className = "lipsync-song__artist";
      artist.textContent = matchup.song?.artist || "";
      song.append(songTitle, artist);
      block.append(song);

      const performances = document.createElement("div");
      performances.className = "lipsync-performance-list lalaparuza-performance-list";
      (matchup.performances || []).forEach((performance) => {
        const card = makeLipSyncPerformanceCard(performance, matchup.event);
        if (card) performances.append(card);
      });
      block.append(performances);

      if (!matchup.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn lipsync-show-results lalaparuza-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          matchup.resultRevealed = true;
          data.visibleMatchupCount = Math.min(flatMatchups.length, flatIndex + 2);
          persistState();
          button.classList.add("is-leaving");
          window.setTimeout(() => renderSlayOffExtravaganzaSection(), 180);
        });
        block.append(button);
      } else {
        const lineup = document.createElement("div");
        lineup.className = "lipsync-result-lineup lalaparuza-result-lineup";
        (matchup.performerIds || []).forEach((id) => {
          const isWinner =
            normalizeContestantId(matchup.winnerId) === normalizeContestantId(id);
          const dangerLoser = !isWinner && (round.round === 1 || round.round === 4);
          const kind = isWinner ? "survivor" : (dangerLoser ? "lalaparuza-danger" : "survivor");
          const portrait = makeLipSyncResultQueen(id, kind);
          if (portrait) lineup.append(portrait);
        });
        block.append(lineup);

        const result = document.createElement("div");
        result.className = "lipsync-result-copy lalaparuza-matchup__result";

        if (round.final) {
          const winner = document.createElement("p");
          winner.textContent = `${joinQueenNames([matchup.winnerId])}, condragulations. You are the winner of the Lip Sync Slay Off Extravaganza!!!`;
          result.append(winner);
          (matchup.loserIds || []).forEach((id) => {
            const safe = document.createElement("p");
            safe.textContent = `${joinQueenNames([id])}, incredible job, you are safe!`;
            result.append(safe);
          });
        } else if (round.round === 2) {
          const winner = document.createElement("p");
          winner.textContent = `${joinQueenNames([matchup.winnerId])}, condragulations. You will advance to the next round!`;
          result.append(winner);
          (matchup.loserIds || []).forEach((id) => {
            const safe = document.createElement("p");
            safe.textContent = `${joinQueenNames([id])}, excellent job, you are safe!`;
            result.append(safe);
          });
        } else if (round.round === 4) {
          const winner = document.createElement("p");
          winner.textContent = `${joinQueenNames([matchup.winnerId])}, condragulations. You are safe.`;
          result.append(winner);
          (matchup.loserIds || []).forEach((id) => {
            const danger = document.createElement("p");
            danger.textContent = `${joinQueenNames([id])}, I'm sorry my dear but you are up for elimination...`;
            result.append(danger);
          });
        } else {
          const winner = document.createElement("p");
          winner.textContent = `${joinQueenNames([matchup.winnerId])}, condragulations. You will advance to the next round!`;
          result.append(winner);
          (matchup.loserIds || []).forEach((id) => {
            const danger = document.createElement("p");
            danger.textContent = `${joinQueenNames([id])}, I'm sorry my dear, you are up for elimination!!`;
            result.append(danger);
          });
        }
        block.append(result);
      }

      shell.append(block);
    });

    const allTournamentResultsRevealed =
      flatMatchups.length > 0 &&
      flatMatchups.every(({ matchup }) => Boolean(matchup.resultRevealed));

    if (allTournamentResultsRevealed) {
      const beaver = episode?.goldenBeaver;
      if (beaver?.used && beaver.recipientId) {
        const block = document.createElement("section");
        block.className = "golden-beaver-decision";

        const title = document.createElement("h3");
        title.className = "golden-beaver-decision__title";
        title.textContent = "The Golden Beaver";

        const intro = document.createElement("p");
        intro.className = "golden-beaver-decision__copy";
        intro.textContent = `${joinQueenNames(beaver.winnerIds || [])}, as the winner of the Slay-Off Extravaganza, the power is in your hands. You must award the Golden Beaver to one of the four queens who lost Round 1, saving them from the final lip sync.`;
        block.append(title, intro);

        const bottomLineup = document.createElement("div");
        bottomLineup.className = "golden-beaver-lineup golden-beaver-lineup--bottoms";
        (beaver.preSaveBottomIds || []).forEach((id) => {
          const card = makeGoldenBeaverPortrait(id, "bottom");
          if (card) bottomLineup.append(card);
        });
        block.append(bottomLineup);

        const prompt = document.createElement("p");
        prompt.className = "golden-beaver-decision__prompt";
        prompt.textContent = `${joinQueenNames(beaver.winnerIds || [])}, who are you saving?`;
        block.append(prompt);

        const divider = document.createElement("hr");
        divider.className = "golden-beaver-divider";
        block.append(divider);

        const decisionLineup = document.createElement("div");
        decisionLineup.className = "golden-beaver-lineup golden-beaver-lineup--decision";
        (beaver.winnerIds || []).forEach((id) => {
          const card = makeGoldenBeaverPortrait(id, "winner");
          if (card) decisionLineup.append(card);
        });
        const arrow = document.createElement("span");
        arrow.className = "golden-beaver-decision__arrow";
        arrow.textContent = "→";
        decisionLineup.append(arrow);
        const recipient = makeGoldenBeaverPortrait(beaver.recipientId, "recipient");
        if (recipient) decisionLineup.append(recipient);
        block.append(decisionLineup);

        const announcement = document.createElement("p");
        announcement.className = "golden-beaver-decision__announcement";
        announcement.textContent = `${joinQueenNames(beaver.winnerIds || [])} has awarded the Golden Beaver to... ${joinQueenNames([beaver.recipientId])}!`;
        const safe = document.createElement("p");
        safe.className = "golden-beaver-decision__safe";
        safe.textContent = `${joinQueenNames([beaver.recipientId])}, you are safe.`;
        block.append(announcement, safe);
        shell.append(block);

        const finalDivider = document.createElement("hr");
        finalDivider.className = "golden-beaver-divider golden-beaver-divider--final";
        shell.append(finalDivider);
      }

      const immuneIds = classicImmunitySavedQueenIds(episode);
      if (immuneIds.length) {
        const immune = document.createElement("section");
        immune.className = "lalaparuza-exempt";
        appendQueenLineup(immune, immuneIds, "placement", "LOW");
        const copy = document.createElement("p");
        copy.textContent = `${joinQueenNames(immuneIds)}, you have immunity, you are safe.`;
        immune.append(copy);
        shell.append(immune);
      }

      if (data.finalDangerIds?.length) {
        const danger = document.createElement("section");
        danger.className = `placement-group ${data.finalDangerIds.length === 3 ? "placement-group--btm" : "placement-group--btm2"} golden-beaver-final-bottom`;
        appendQueenLineup(
          danger,
          data.finalDangerIds,
          "placement",
          data.finalDangerIds.length === 3 ? "BTM3" : "BTM2"
        );
        const copy = document.createElement("p");
        copy.className = "placement-group__copy";
        copy.textContent = data.finalDangerIds.length === 3
          ? `${joinQueenNames(data.finalDangerIds)}, I'm sorry my dears, but all three of you are up for elimination. Only one of you will stay.`
          : `${joinQueenNames(data.finalDangerIds)}, I'm sorry my dears, but you are both up for elimination.`;
        danger.append(copy);
        shell.append(danger);
      }
    }

    els.runtimeContent.append(shell);
  }

  function makeQueensOfComedyPairPortrait(id, role = "") {
    const queen = queenFromId(id);
    if (!queen) return null;
    const card = document.createElement("article");
    card.className = `conjoined-twins-queen queens-of-comedy-queen${role ? ` is-${role}` : ""}`;
    const image = document.createElement("img");
    image.className = "conjoined-twins-queen__image";
    image.src = imageSrc(queen);
    image.alt = queen.fullName || queen.nickname || "Contestant";
    image.addEventListener("error", () => image.removeAttribute("src"), { once: true });
    const name = document.createElement("strong");
    name.className = "conjoined-twins-queen__name";
    name.textContent = queen.nickname || queen.fullName || queen.id;
    card.append(image, name);
    return card;
  }

  function queensOfComedyActDisplayName(act) {
    return joinQueenNames(act?.memberIds || []);
  }

  function buildQueensOfComedyPairFormation(data) {
    const wrap = document.createElement("section");
    wrap.className = "pair-formation queens-of-comedy-formation";

    const intro = document.createElement("p");
    intro.className = "pair-formation__intro";
    intro.textContent =
      "The returning contestants get to choose their partner... Starting with the last eliminated contestant...";

    const list = document.createElement("div");
    list.className = "pair-formation__list";

    (data.acts || []).forEach((act) => {
      const pair = document.createElement("div");
      pair.className = "pair-formation__pair queens-of-comedy-formation__pair";

      const portraits = document.createElement("div");
      portraits.className = "pair-formation__portraits";

      (act.memberIds || []).forEach((id) => {
        const queen = queenFromId(id);
        if (!queen) return;
        const image = document.createElement("img");
        image.className = "pair-formation__image";
        image.src = imageSrc(queen);
        image.alt = queen.fullName || queen.nickname || "Contestant";
        image.addEventListener("error", () => image.removeAttribute("src"), { once: true });
        portraits.append(image);
      });

      const text = document.createElement("p");
      text.className = "pair-formation__text";
      if (act.kind === "return-pair") {
        const activeId = (act.activeIds || [])[0];
        text.textContent = `${joinQueenNames([act.returneeId])} chose ${joinQueenNames([activeId])}`;
      } else if (act.kind === "active-pair") {
        text.textContent = `${joinQueenNames(act.memberIds || [])} will work together!`;
      } else {
        text.textContent = `That means ${joinQueenNames(act.memberIds || [])} will work solo as the emcee of the show.`;
      }

      pair.append(portraits, text);
      list.append(pair);
    });

    wrap.append(intro, list);
    return wrap;
  }

  function makeQueensOfComedyPerformanceAct(act, bracket) {
    const card = document.createElement("article");
    card.className = `performance-contestant performance-contestant--${bracket.toLowerCase()} queens-of-comedy-performance-act`;

    const portraits = document.createElement("div");
    portraits.className = "queens-of-comedy-performance-act__portraits";

    (act.memberIds || []).forEach((id) => {
      const queen = queenFromId(id);
      if (!queen) return;

      const imageWrap = document.createElement("div");
      imageWrap.className = "performance-contestant__image-wrap queens-of-comedy-performance-act__image-wrap";

      const image = document.createElement("img");
      image.className = "performance-contestant__image";
      image.src = imageSrc(queen);
      image.alt = queen.fullName || queen.nickname || "Contestant";
      image.addEventListener("error", () => image.removeAttribute("src"), { once: true });

      imageWrap.append(image);
      portraits.append(imageWrap);
    });

    const name = document.createElement("span");
    name.className = "performance-contestant__name queens-of-comedy-performance-act__name";
    name.textContent = queensOfComedyActDisplayName(act);

    card.append(portraits, name);
    return card;
  }

  function queensOfComedyPerformanceSentence(bracket, acts) {
    const names = (acts || []).map((act) => queensOfComedyActDisplayName(act)).filter(Boolean);
    const joined = names.length <= 1
      ? (names[0] || "The pair")
      : names.length === 2
        ? `${names[0]} and ${names[1]}`
        : `${names.slice(0, -1).join(", ")}, and ${names[names.length - 1]}`;
    if (bracket === "SLAY") return `${joined} slayed the challenge!`;
    if (bracket === "GREAT") return `${joined} had a great performance!`;
    if (bracket === "GOOD") return `${joined} had a good performance.`;
    if (bracket === "BAD") return `${joined} had a bad performance...`;
    return `${joined} flopped the challenge...`;
  }

  function buildQueensOfComedyPerformanceGroups(data) {
    const groups = document.createElement("div");
    groups.className = "performance-groups queens-of-comedy-performance-groups";

    ["SLAY", "GREAT", "GOOD", "BAD", "FLOP"].forEach((bracket) => {
      const acts = (data.acts || [])
        .filter((act) => String(act.bracket || "GOOD").toUpperCase() === bracket)
        .sort((a, b) => Number(a.score || 999) - Number(b.score || 999));
      if (!acts.length) return;

      const section = document.createElement("section");
      section.className = `performance-group performance-group--${bracket.toLowerCase()}`;

      const label = document.createElement("h4");
      label.className = "performance-group__label";
      label.textContent = bracket;

      const lineup = document.createElement("div");
      lineup.className = "performance-group__lineup";
      acts.forEach((act) => lineup.append(makeQueensOfComedyPerformanceAct(act, bracket)));

      const comment = document.createElement("p");
      comment.className = "performance-group__comment";
      comment.textContent = queensOfComedyPerformanceSentence(bracket, acts);

      section.append(label, lineup, comment);
      groups.append(section);
    });

    return groups;
  }

  function renderQueensOfComedySection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.queensOfComedy || episode?.reinasDeLaComedia;
    const maxi = episode?.maxiChallenge;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--maxi";
    if (!data || !maxi) return;

    const shell = document.createElement("div");
    shell.className = "maxi-performance-view";

    const header = document.createElement("header");
    header.className = "maxi-challenge-header";

    const title = document.createElement("h3");
    title.className = "maxi-challenge-name";
    title.textContent = maxi.displayName || maxi.name || "Comedy";

    const description = document.createElement("p");
    description.className = "maxi-challenge-description";
    description.textContent = maxi.description || data.description || "";

    header.append(title, description);
    shell.append(header);
    shell.append(buildQueensOfComedyPairFormation(data));
    shell.append(buildQueensOfComedyPerformanceGroups(data));

    els.runtimeContent.append(shell);
  }

  function renderQueensOfComedyJudgingSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.queensOfComedy;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--judging runtime-content--queens-of-comedy";
    if (!data) return;

    const shell = document.createElement("div");
    shell.className = "judging-view";

    const topCopy = document.createElement("p");
    topCopy.className = "judging-copy";
    const topPairNames = (data.topActMemberIds || []).map((ids) => joinQueenNames(ids));
    topCopy.textContent = `${topPairNames.join(" and ")}. You are the top All Stars of the week.`;
    shell.append(topCopy);

    const winners = document.createElement("div");
    winners.className = "judging-lineup";
    (data.activeWinnerIds || []).forEach((id) => {
      const card = makeJudgingQueen(id, "winner", "WIN");
      if (card) winners.append(card);
    });
    if (winners.children.length) shell.append(winners);

    const returnCopy = document.createElement("p");
    returnCopy.className = "judging-copy";
    returnCopy.textContent = `${joinQueenNames(data.top2ReturneeIds || [])}, you are the two eliminated contestants still in the running to return to the competition.`;
    shell.append(returnCopy);

    const finalists = document.createElement("div");
    finalists.className = "judging-lineup";
    (data.top2ReturneeIds || []).forEach((id) => {
      const card = makeJudgingQueen(id, "judged", "TOP2");
      if (card) finalists.append(card);
    });
    shell.append(finalists);

    const bottomCopy = document.createElement("p");
    bottomCopy.className = "judging-copy";
    bottomCopy.textContent = `${joinQueenNames(data.bottomActiveIds || [])}, you represent the two weakest active performances of the week.`;
    shell.append(bottomCopy);

    const bottoms = document.createElement("div");
    bottoms.className = "judging-lineup";
    (data.bottomActiveIds || []).forEach((id) => {
      const card = makeJudgingQueen(id, "bottom", "BTM2");
      if (card) bottoms.append(card);
    });
    shell.append(bottoms);

    els.runtimeContent.append(shell);
  }

  function renderQueensOfComedyLipstickChoicesSection() {
    clearRuntimeTimers();
    const data = currentEpisodeData()?.queensOfComedy;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--lipsticks runtime-content--queens-of-comedy";
    if (!data) return;

    const shell = document.createElement("div");
    shell.className = "lipstick-view";
    (data.lipstickChoices || []).forEach((choice) => {
      const row = document.createElement("section");
      row.className = "lipstick-choice";
      const lineup = document.createElement("div");
      lineup.className = "lipsync-result-lineup";
      const chooser = makeLipSyncResultQueen(choice.returneeId, "returned");
      const target = makeLipSyncResultQueen(choice.targetId, "eliminated");
      if (chooser) lineup.append(chooser);
      if (target) lineup.append(target);
      const copy = document.createElement("p");
      copy.className = "lipsync-result-copy";
      copy.textContent = `${joinQueenNames([choice.returneeId])} chose ${joinQueenNames([choice.targetId])}'s lipstick!`;
      row.append(lineup, copy);
      shell.append(row);
    });
    els.runtimeContent.append(shell);
  }

