  function renderQueensOfComedyResultsSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.queensOfComedy;
    const lipSync = data?.lipSync;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--results runtime-content--queens-of-comedy";
    if (!lipSync) return;

    const shell = document.createElement("div");
    shell.className = "results-view";

    if (!lipSync.resultRevealed) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "control-btn lipsync-show-results";
      button.textContent = "SHOW RESULT";
      button.addEventListener("click", () => {
        lipSync.resultRevealed = true;
        persistState();
        renderQueensOfComedyResultsSection();
      });
      shell.append(button);
      els.runtimeContent.append(shell);
      return;
    }

    const returnees = document.createElement("div");
    returnees.className = "lipsync-result-lineup";
    (data.returneeIds || []).forEach((id) => {
      const card = makeLipSyncResultQueen(id, "winner");
      if (card) returnees.append(card);
    });
    shell.append(returnees);

    const winnerCopy = document.createElement("p");
    winnerCopy.className = "lipsync-result-copy";
    winnerCopy.textContent = data.returneeIds?.length > 1
      ? `${joinQueenNames(data.returneeIds)}, condragulations, you're both winners baby!`
      : `${joinQueenNames(data.returneeIds || [])}, you're a winner, baby!`;
    shell.append(winnerCopy);

    (data.losingTop2Ids || []).forEach((id) => {
      const lineup = document.createElement("div");
      lineup.className = "lipsync-result-lineup";
      const card = makeLipSyncResultQueen(id, "eliminated");
      if (card) lineup.append(card);
      const copy = document.createElement("p");
      copy.className = "lipsync-result-copy";
      copy.textContent = `${joinQueenNames([id])}, sashay away.`;
      shell.append(lineup, copy);
    });

    const targets = [...new Map(
      (data.returneeIds || [])
        .map((id) => data.lipstickTargetByReturnee?.[id])
        .filter(Boolean)
        .map((id) => [normalizeContestantId(id), id])
    ).values()];
    if (targets.length) {
      const lipstickCopy = document.createElement("p");
      lipstickCopy.className = "lipsync-result-copy";
      lipstickCopy.textContent = targets.length > 1
        ? `${joinQueenNames(data.returneeIds || [])} chose these lipsticks...`
        : `${joinQueenNames(data.returneeIds || [])} chose ${joinQueenNames(targets)}'s lipstick.`;
      shell.append(lipstickCopy);
    }

    if ((data.chocolateRevealIds || []).length) {
      appendChocolateRevealBlock(shell, data.chocolateRevealIds, data.chocolateSavedIds, { allStars: true, stateTarget: data });
    }

    (data.eliminatedActiveIds || []).forEach((id) => {
      const lineup = document.createElement("div");
      lineup.className = "lipsync-result-lineup";
      const card = makeLipSyncResultQueen(id, "eliminated");
      if (card) lineup.append(card);
      const copy = document.createElement("p");
      copy.className = "lipsync-result-copy";
      copy.textContent = `${joinQueenNames([id])}, you will always be an All Star, now, sashay away...`;
      shell.append(lineup, copy);
    });

    els.runtimeContent.append(shell);
  }

  function renderLaLaPaRUZaSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const data = episode?.lalaparuza;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--lalaparuza runtime-content--lipsync";
    if (!data) return;

    const shell = document.createElement("div");
    shell.className = "lalaparuza-view lipsync-performance-view";

    const rules = document.createElement("div");
    rules.className = "lalaparuza-rules";
    const ruleCopy = document.createElement("p");
    ruleCopy.textContent = data.comeback
      ? (data.description || "All of the eliminated contestants get a chance to return to the competition. But first they have to send home a competing contestant in a mid season lip sync smackdown.")
      : "Win your lip sync and you are safe. Lose, and you continue until only two contestants remain. In the final round, one contestant may be eliminated.";
    rules.append(ruleCopy);
    shell.append(rules);

    const exemptWinnerIds = data.comeback
      ? [...(data.exemptWinnerIds || [])]
      : (data.exemptWinnerId ? [data.exemptWinnerId] : []);
    if (exemptWinnerIds.length) {
      const exempt = document.createElement("section");
      exempt.className = "lalaparuza-exempt";
      appendQueenLineup(exempt, exemptWinnerIds, "placement", data.comeback ? "RUN" : "SAFE");
      const copy = document.createElement("p");
      copy.textContent = data.comeback
        ? `${joinQueenNames(exemptWinnerIds)}, as ${exemptWinnerIds.length === 1 ? "the winner" : "the winners"} of last week's challenge, ${exemptWinnerIds.length === 1 ? "you have" : "you all have"} immunity.`
        : `${joinQueenNames(exemptWinnerIds)}, you are the exception. You are safe from elimination tonight.`;
      exempt.append(copy);
      shell.append(exempt);
    }

    const flatMatchups = [];
    (data.rounds || []).forEach((round) => {
      (round.matchups || []).forEach((matchup, index) => {
        flatMatchups.push({ round, matchup, index });
      });
    });

    const visibleCount = Math.min(
      flatMatchups.length,
      Math.max(1, Number(data.visibleMatchupCount) || 1)
    );

    flatMatchups.slice(0, visibleCount).forEach(({ round, matchup, index }, flatIndex) => {
      const block = document.createElement("section");
      block.className = `lalaparuza-matchup porkchop-matchup lalaparuza-round--${round.round}`;

      const previous = flatMatchups[flatIndex - 1];
      const startsRound = flatIndex === 0 || previous?.round?.round !== round.round;
      if (startsRound) {
        const title = document.createElement("h3");
        title.className = "lalaparuza-progressive-round-title";
        title.textContent = round.final ? "FINAL ROUND" : `ROUND ${round.round}`;
        block.append(title);
      }

      const song = document.createElement("header");
      song.className = "lipsync-song lalaparuza-matchup__song";
      const songTitle = document.createElement("h3");
      songTitle.className = "lipsync-song__title";
      songTitle.textContent = matchup.song?.song || "Lip Sync";
      const artist = document.createElement("p");
      artist.className = "lipsync-song__artist";
      artist.textContent = matchup.song?.artist || "";
      song.append(songTitle, artist);
      block.append(song);

      const performances = document.createElement("div");
      performances.className = "lipsync-performance-list lalaparuza-performance-list";
      (matchup.performances || []).forEach((performance) => {
        const card = makeLipSyncPerformanceCard(performance, matchup.event);
        if (card) performances.append(card);
      });
      block.append(performances);

      if (!matchup.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn lipsync-show-results lalaparuza-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          matchup.resultRevealed = true;
          data.visibleMatchupCount = Math.min(flatMatchups.length, flatIndex + 2);
          persistState();
          button.classList.add("is-leaving");
          window.setTimeout(() => renderLaLaPaRUZaSection(), 180);
        });
        block.append(button);
      } else {
        const lineup = document.createElement("div");
        lineup.className = "lipsync-result-lineup lalaparuza-result-lineup";
        (matchup.performerIds || []).forEach((id) => {
          let kind = "survivor";
          if (data.comeback) {
            const key = normalizeContestantId(id);
            const returned = (matchup.returnedIds || []).some((candidate) => normalizeContestantId(candidate) === key);
            const safe = (matchup.safeActiveIds || []).some((candidate) => normalizeContestantId(candidate) === key);
            const out = (matchup.outReturneeIds || []).some((candidate) => normalizeContestantId(candidate) === key);
            const eliminated = (matchup.eliminatedActiveIds || []).some((candidate) => normalizeContestantId(candidate) === key);
            const chocolate = (matchup.chocolateSavedIds || []).some((candidate) => normalizeContestantId(candidate) === key);
            const badonkaDraw = badonkaDrawForId(matchup, id);
            if (badonkaDraw) {
              kind = !badonkaDraw.opened
                ? "badonka-pending"
                : (badonkaDraw.save ? "badonka-save" : "eliminated");
            }
            else if (chocolate) kind = "chocolate";
            else if (returned) kind = "returned";
            else if (safe) kind = "survivor";
            else if (out || eliminated) kind = "eliminated";
          } else {
            const isWinner = (matchup.winnerIds || []).some((winnerId) => normalizeContestantId(winnerId) === normalizeContestantId(id)) ||
              normalizeContestantId(matchup.winnerId) === normalizeContestantId(id);
            const isEliminated = (matchup.eliminatedIds || []).some((elimId) => normalizeContestantId(elimId) === normalizeContestantId(id));
            const isChocolateRevealTarget = (matchup.chocolateRevealIds || []).some((revealId) => normalizeContestantId(revealId) === normalizeContestantId(id));
            if (round.final && isChocolateRevealTarget && !matchup.chocolateRevealOpened) kind = "eliminated";
            else if (round.final && matchup.goldenChocolateSaveId && normalizeContestantId(matchup.goldenChocolateSaveId) === normalizeContestantId(id)) kind = "chocolate";
            else if (round.final && isEliminated && !matchup.goldenChocolateSaveId) kind = "eliminated";
            else if (isWinner) kind = "survivor";
            else if (!round.final) kind = "lalaparuza-danger";
          }
          const portrait = makeLipSyncResultQueen(id, kind);
          if (portrait) lineup.append(portrait);
        });
        block.append(lineup);

        const result = document.createElement("div");
        result.className = "lipsync-result-copy lalaparuza-matchup__result";
        if (data.comeback) {
          const survivorIds = matchup.survivorIds || matchup.winnerIds || [];
          const allStay = Boolean(matchup.allStay);
          const intro = document.createElement("p");
          if (allStay && (matchup.performerIds || []).length === 3) {
            intro.textContent = `${joinQueenNames(matchup.performerIds || [])}, shantay, you three stay, baby!`;
          } else if (allStay && (matchup.performerIds || []).length === 2) {
            intro.textContent = `${joinQueenNames(matchup.performerIds || [])}, shantay you both stay, baby!`;
          } else if (survivorIds.length === 2) {
            intro.textContent = `${joinQueenNames(survivorIds)}, shantay you both stay, baby!`;
          } else {
            intro.textContent = `${joinQueenNames(survivorIds)}, shantay you stay.`;
          }
          result.append(intro);

          (matchup.returnedIds || []).forEach((id) => {
            const line = document.createElement("p");
            line.textContent = `${joinQueenNames([id])}, you are back in the competition!`;
            result.append(line);
          });
          (matchup.outReturneeIds || []).forEach((id) => {
            const line = document.createElement("p");
            line.textContent = `${joinQueenNames([id])}, I'm sorry my dear, but you will not be returning to the competition.`;
            result.append(line);
          });

          if ((matchup.chocolateRevealIds || []).length) {
            appendChocolateRevealBlock(result, matchup.chocolateRevealIds, matchup.chocolateSavedIds, { stateTarget: matchup });
          } else if ((matchup.badonkaDraws || []).length) {
            appendBadonkaDunkTankBlock(result, matchup);
          } else {
            (matchup.eliminatedActiveIds || []).forEach((id) => {
              const line = document.createElement("p");
              line.textContent = `${joinQueenNames([id])}, sashay away.`;
              result.append(line);
            });
          }
        } else if (round.final) {
          if (data.finalDoubleShantay) {
            const line = document.createElement("p");
            line.textContent = `${joinQueenNames(matchup.winnerIds || matchup.performerIds || [])}, shantay you both stay!`;
            result.append(line);
          } else {
            const winnerId = matchup.winnerIds?.[0] || matchup.winnerId;
            const loserId = matchup.eliminatedIds?.[0];
            const winLine = document.createElement("p");
            winLine.textContent = `${joinQueenNames([winnerId])}, shantay you stay.`;
            result.append(winLine);
            if ((matchup.chocolateRevealIds || []).length) {
              appendChocolateRevealBlock(result, matchup.chocolateRevealIds, matchup.chocolateSavedIds, { stateTarget: matchup });
            } else if (loserId) {
              const lossLine = document.createElement("p");
              lossLine.textContent = `${joinQueenNames([loserId])}, sashay away.`;
              result.append(lossLine);
            }
          }
        } else {
          const winLine = document.createElement("p");
          winLine.textContent = `${joinQueenNames([matchup.winnerId])}, shantay you stay.`;
          result.append(winLine);
          (matchup.loserIds || []).forEach((id) => {
            const lossLine = document.createElement("p");
            lossLine.textContent = `${joinQueenNames([id])}, you are still up for elimination.`;
            result.append(lossLine);
          });
        }
        block.append(result);
      }

      shell.append(block);
    });

    els.runtimeContent.append(shell);
  }

  function tournamentBracketForEpisode(episode) {
    const snap=state.seasonRuntime?.tournamentSetupSnapshot; return snap?.brackets?.find(b=>Number(b.id)===Number(episode?.tournamentBracketId)) || null;
  }

  function makeTournamentPortrait(id,color,mode="") { const queen=queenFromId(id); if(!queen)return null; const card=document.createElement("article");card.className=`tournament-runtime-queen${mode?` is-${mode}`:""}`;card.style.setProperty("--bracket-color",color||"#f0188c");const img=document.createElement("img");img.src=imageSrc(queen);img.alt=queen.fullName||queen.nickname||"Contestant";const name=document.createElement("strong");name.textContent=queen.nickname||queen.fullName||queen.id;card.append(img,name);return card; }

  function renderTournamentStandingsSection() {
    const episode = currentEpisodeData();
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--tournament-standings";

    const shell = document.createElement("div");
    shell.className = "tournament-runtime-view";
    shell.style.setProperty("--bracket-color", episode?.tournamentBracketColor || "#f0188c");

    const title = document.createElement("h3");
    title.className = "tournament-runtime-title";
    title.textContent = `${episode?.sections?.includes("Final Bracket Standings") ? "Final " : ""}${episode?.tournamentBracketName || "Tournament"} Bracket Standings`;
    shell.append(title);

    const roster = document.createElement("div");
    roster.className = "tournament-standings-roster";

    [...(episode?.tournamentStandings || [])]
      .sort((a,b)=>
        (Number(b.total||0)-Number(a.total||0)) ||
        (Number(b.mvqs||0)-Number(a.mvqs||0)) ||
        (Number(a.rank||0)-Number(b.rank||0))
      )
      .forEach((row) => {
      const status = episode.tournamentAdvancingIds?.some(
        (id) => normalizeContestantId(id) === normalizeContestantId(row.id)
      )
        ? "advancing"
        : (episode.tournamentCutIds?.some(
            (id) => normalizeContestantId(id) === normalizeContestantId(row.id)
          ) ? "cut" : "");

      const card = makeTournamentPortrait(row.id, episode.tournamentBracketColor, status);
      if (!card) return;
      card.classList.add("tournament-standing-card");

      const points = document.createElement("span");
      points.className = "tournament-standing-points";
      const total = Number(row.total || 0);
      points.textContent = `${total} POINT${total === 1 ? "" : "S"}`;
      card.append(points);
      roster.append(card);
    });

    shell.append(roster);

    if (episode.tournamentAdvancingIds?.length) {
      const line = document.createElement("p");
      line.className = "tournament-runtime-copy tournament-cut-copy";
      line.textContent = `${joinQueenNames(episode.tournamentAdvancingIds)}, condragulations. You are advancing to the Merge!`;
      shell.append(line);

      if (episode.tournamentCutIds?.length) {
        const cut = document.createElement("p");
        cut.className = "tournament-runtime-copy tournament-cut-copy is-cut";
        cut.textContent = `${joinQueenNames(episode.tournamentCutIds)}... I'm sorry my dears, but your journey ends here. Now, sashay away.`;
        shell.append(cut);
      }
    }

    els.runtimeContent.append(shell);
  }

  function renderTournamentMVQSection() {
    const episode = currentEpisodeData();
    const mvq = episode?.mvq;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--tournament-mvq runtime-content--miss-con";
    if (!mvq) return;

    const shell = document.createElement("div");
    shell.className = "mini-challenge-view mx-con-view tournament-mvq-view";

    const title = document.createElement("h3");
    title.className = "miss-con-title";
    title.textContent = "MVQ Vote";

    const copy = document.createElement("p");
    copy.className = "tournament-runtime-copy tournament-mvq-copy";
    copy.textContent = "The bottom contestants will give out their MVQ votes.";
    shell.append(title, copy);

    const votes = document.createElement("div");
    votes.className = "mini-performance-grid mx-con-votes tournament-mvq-votes";

    (mvq.votes || []).forEach((vote) => {
      const row = document.createElement("article");
      row.className = "mini-performance mx-con-vote-row tournament-mvq-vote-row";

      const portraits = document.createElement("div");
      portraits.className = "mx-con-vote-portraits";

      const voter = makeMxCongVotePortrait(vote.voterId, "voter");
      const recipient = makeMxCongVotePortrait(vote.targetId, "recipient");
      if (recipient) {
        recipient.style.borderColor = mvq.bracketColor || "#d4b56f";
        recipient.style.boxShadow = `0 0 0 3px color-mix(in srgb, ${mvq.bracketColor || "#d4b56f"} 18%, transparent), 0 12px 32px rgba(0,0,0,.45)`;
      }
      if (voter) portraits.append(voter);
      if (recipient) portraits.append(recipient);

      const text = document.createElement("p");
      text.className = "mini-performance__comment mx-con-vote-comment";
      text.textContent = `${joinQueenNames([vote.voterId])} gave 1 MVQ point to ${joinQueenNames([vote.targetId])}!`;

      row.append(portraits, text);
      votes.append(row);
    });

    shell.append(votes);

    const awarded = document.createElement("p");
    awarded.className = "tournament-mvq-awarded";
    awarded.textContent = "The MVQ points have been awarded.";
    shell.append(awarded);

    els.runtimeContent.append(shell);
  }

  function renderTournamentMergeSection() { const episode=currentEpisodeData();els.runtimeContent.replaceChildren();els.runtimeContent.className="runtime-content runtime-content--tournament-merge";const shell=document.createElement("div");shell.className="tournament-runtime-view";const title=document.createElement("h3");title.className="tournament-runtime-title";title.textContent="The Merge";const copy=document.createElement("p");copy.className="tournament-runtime-copy";copy.textContent="The brackets are officially over. From this point forward, all remaining queens will compete together. And from now on... eliminations begin.";const lineup=document.createElement("div");lineup.className="tournament-runtime-lineup";(episode.castIds||[]).forEach(id=>{const record=state.seasonRuntime?.tournamentRecords?.[id];const bracket=state.seasonRuntime?.tournamentSetupSnapshot?.brackets?.find(b=>Number(b.id)===Number(record?.bracketId));const card=makeTournamentPortrait(id,bracket?.color||"#f0188c");if(card)lineup.append(card);});shell.append(title,copy,lineup);els.runtimeContent.append(shell); }

  function renderTournamentWildcardSection() {
    const episode = currentEpisodeData();
    const data = episode?.wildcard;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--tournament-wildcard";
    if (!data) return;

    if (typeof data.choicesRevealed !== "boolean") data.choicesRevealed = false;
    if (typeof data.wildcardRevealed !== "boolean") data.wildcardRevealed = false;

    const shell = document.createElement("div");
    shell.className = "tournament-runtime-view tournament-wildcard-view";

    const title = document.createElement("h3");
    title.className = "tournament-runtime-title";
    title.textContent = "Wildcard Lottery";

    const copy = document.createElement("p");
    copy.className = "tournament-runtime-copy";
    copy.textContent = "Not everyone who left the tournament is out of the race just yet...";
    shell.append(title, copy);

    if (!data.choicesRevealed) {
      const reveal = document.createElement("button");
      reveal.type = "button";
      reveal.className = "control-btn control-btn--accent tournament-wildcard-button";
      reveal.textContent = "REVEAL CHOICES";
      reveal.addEventListener("click", () => {
        data.choicesRevealed = true;
        persistState();
        renderTournamentWildcardSection();
      });
      shell.append(reveal);
      els.runtimeContent.append(shell);
      return;
    }

    const choicesCopy = document.createElement("p");
    choicesCopy.className = "tournament-runtime-copy tournament-wildcard-choice-copy";
    choicesCopy.textContent = "One of these three contestants will return to the competition...";
    shell.append(choicesCopy);

    const lineup = document.createElement("div");
    lineup.className = "tournament-runtime-lineup tournament-wildcard-choices";
    (data.candidateIds || []).forEach((id) => {
      const card = makeTournamentPortrait(id, "#d4b56f", "wildcard-choice");
      if (card) lineup.append(card);
    });
    shell.append(lineup);

    if (!data.wildcardRevealed) {
      const show = document.createElement("button");
      show.type = "button";
      show.className = "control-btn control-btn--accent tournament-wildcard-button";
      show.textContent = "SHOW WILDCARD";
      show.addEventListener("click", () => {
        data.wildcardRevealed = true;
        persistState();
        renderTournamentWildcardSection();
      });
      shell.append(show);
      els.runtimeContent.append(shell);
      return;
    }

    const winner = document.createElement("div");
    winner.className = "tournament-wildcard-winner";
    const card = makeTournamentPortrait(data.returneeId, "aquamarine", "wildcard-returnee");
    if (card) winner.append(card);
    const result = document.createElement("p");
    result.className = "tournament-wildcard-result";
    result.textContent = `${joinQueenNames([data.returneeId])}... welcome back to the competition!`;
    winner.append(result);
    shell.append(winner);

    els.runtimeContent.append(shell);
  }

  function renderTournamentFinaleOpening() { const episode=currentEpisodeData();els.runtimeContent.replaceChildren();els.runtimeContent.className="runtime-content runtime-content--tournament-finale";const shell=document.createElement("div");shell.className="tournament-runtime-view";const title=document.createElement("h3");title.className="tournament-runtime-title";title.textContent="The Grand Finale!";const copy=document.createElement("p");copy.className="tournament-runtime-copy";copy.textContent=`Tonight, our Top ${episode.finale?.finalistIds?.length||episode.castIds?.length||0} will compete in a Lip Sync Smackdown for the Crown! One by one, the field will be narrowed until only one queen remains.`;const lineup=document.createElement("div");lineup.className="tournament-runtime-lineup";(episode.finale?.finalistIds||[]).forEach(id=>{const card=makeTournamentPortrait(id,"royalblue");if(card)lineup.append(card);});shell.append(title,copy,lineup);els.runtimeContent.append(shell); }

  function renderTournamentFinaleLipSyncs() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const finale = episode?.finale;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--lalaparuza runtime-content--lipsync runtime-content--tournament-finale-lipsyncs";
    if (!finale) return;

    const shell = document.createElement("div");
    shell.className = "lalaparuza-view lipsync-performance-view tournament-finale-smackdown-view";

    const flatMatchups = [];
    (finale.rounds || []).forEach((round) => {
      (round.matches || []).forEach((matchup, index) => {
        flatMatchups.push({ round, matchup, index });
      });
    });
    if (!flatMatchups.length) return;

    if (!Number.isFinite(Number(finale.visibleMatchupCount))) finale.visibleMatchupCount = 1;
    const visibleCount = Math.min(
      flatMatchups.length,
      Math.max(1, Number(finale.visibleMatchupCount) || 1)
    );

    flatMatchups.slice(0, visibleCount).forEach(({ round, matchup }, flatIndex) => {
      const isFinalMatch = flatIndex === flatMatchups.length - 1;
      const block = document.createElement("section");
      block.className = `lalaparuza-matchup porkchop-matchup tournament-finale-matchup lalaparuza-round--${round.roundNumber}`;

      const previous = flatMatchups[flatIndex - 1];
      const startsRound = flatIndex === 0 || Number(previous?.round?.roundNumber) !== Number(round.roundNumber);
      if (startsRound) {
        const title = document.createElement("h3");
        title.className = "lalaparuza-progressive-round-title";
        title.textContent = isFinalMatch ? "FINAL ROUND" : `ROUND ${round.roundNumber}`;
        block.append(title);
      }

      const song = document.createElement("header");
      song.className = "lipsync-song lalaparuza-matchup__song";
      const songTitle = document.createElement("h3");
      songTitle.className = "lipsync-song__title";
      songTitle.textContent = matchup.song?.song || "Lip Sync";
      const artist = document.createElement("p");
      artist.className = "lipsync-song__artist";
      artist.textContent = matchup.song?.artist || "";
      song.append(songTitle, artist);
      block.append(song);

      const performances = document.createElement("div");
      performances.className = "lipsync-performance-list lalaparuza-performance-list tournament-finale-performance-list";
      (matchup.performances || []).forEach((performance) => {
        const card = makeLipSyncPerformanceCard(performance, matchup.event);
        if (card) performances.append(card);
      });
      block.append(performances);

      if (isFinalMatch) {
        const finalCopy = document.createElement("p");
        finalCopy.className = "finale-lipsync-intro tournament-finale-final-copy";
        finalCopy.textContent = `${joinQueenNames(matchup.performerIds || [])}, the final decision will be revealed at the crowning.`;
        block.append(finalCopy);
      } else if (!matchup.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn lipsync-show-results lalaparuza-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          matchup.resultRevealed = true;
          finale.visibleMatchupCount = Math.min(flatMatchups.length, flatIndex + 2);
          persistState();
          button.classList.add("is-leaving");
          window.setTimeout(() => renderTournamentFinaleLipSyncs(), 180);
        });
        block.append(button);
      } else {
        const lineup = document.createElement("div");
        lineup.className = "lipsync-result-lineup lalaparuza-result-lineup tournament-finale-result-lineup";
        (matchup.performerIds || []).forEach((id) => {
          const isWinner = normalizeContestantId(id) === normalizeContestantId(matchup.winnerId);
          const portrait = makeLipSyncResultQueen(id, isWinner ? "survivor" : "reunion-loser");
          if (portrait) lineup.append(portrait);
        });
        block.append(lineup);

        const result = document.createElement("div");
        result.className = "lipsync-result-copy lalaparuza-matchup__result tournament-finale-matchup__result";
        const win = document.createElement("p");
        win.textContent = `${joinQueenNames([matchup.winnerId])}, shantay you stay. You advance to the next round.`;
        result.append(win);
        (matchup.loserIds || []).forEach((id) => {
          const loss = document.createElement("p");
          loss.textContent = `${joinQueenNames([id])}, I'm sorry my dear. Sashay away.`;
          result.append(loss);
        });
        block.append(result);
      }

      shell.append(block);
    });

    els.runtimeContent.append(shell);
  }

  function renderPlaceholderSection() {
    clearRuntimeTimers();
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--placeholder";
  }

  function rupaulUnlockedSectionForEpisode(episodeIndex = state.seasonRuntime.currentEpisode) {
    if (!directorModeEnabled()) return Number.POSITIVE_INFINITY;
    if (!state.seasonRuntime.rupaulUnlockedSections || typeof state.seasonRuntime.rupaulUnlockedSections !== "object") {
      state.seasonRuntime.rupaulUnlockedSections = {};
    }
    const key = String(Math.max(0, Number(episodeIndex) || 0));
    const stored = Number(state.seasonRuntime.rupaulUnlockedSections[key]);
    if (Number.isFinite(stored)) return Math.max(0, stored);
    return 0;
  }

  function rupaulUnlockSection(episodeIndex, sectionIndex) {
    if (!directorModeEnabled()) return;
    if (!state.seasonRuntime.rupaulUnlockedSections || typeof state.seasonRuntime.rupaulUnlockedSections !== "object") {
      state.seasonRuntime.rupaulUnlockedSections = {};
    }
    const key = String(Math.max(0, Number(episodeIndex) || 0));
    const current = Number(state.seasonRuntime.rupaulUnlockedSections[key]);
    state.seasonRuntime.rupaulUnlockedSections[key] = Math.max(Number.isFinite(current) ? current : 0, Math.max(0, Number(sectionIndex) || 0));
  }

  function renderRuntimeSectionTabs() {
    const episode = currentEpisodeData();
    const section = currentSectionName();
    if (!episode || section === "Intro" || state.seasonRuntime.statisticsOpen) {
      els.runtimeSectionTabs.hidden = true;
      return;
    }
    els.runtimeSectionTabs.hidden = false;
    els.runtimeSectionTabsInner.replaceChildren();
    const unlockedSection = directorModeEnabled() ? rupaulUnlockedSectionForEpisode(state.seasonRuntime.currentEpisode) : Number.POSITIVE_INFINITY;

    episode.sections
      .map((name, index) => ({ name, index }))
      .filter((item) => item.name !== "Intro")
      .forEach(({ name, index }) => {
        const button = document.createElement("button");
        button.type = "button"; button.className = "runtime-section-tab"; button.dataset.sectionIndex = String(index); button.setAttribute("role", "tab");
        const selected = index === state.seasonRuntime.currentSection;
        button.classList.toggle("is-active", selected); button.setAttribute("aria-selected", selected ? "true" : "false"); button.textContent = name.toUpperCase();
        if (directorModeEnabled() && index > unlockedSection) button.disabled = true;
        if (runtimeHasHoliSlay()) {
          const smackdownIndex = episode.sections.indexOf("Holi-Slay Smackdown");
          const resultIndex = episode.sections.indexOf("Final Results");
          if (index > smackdownIndex && !episode.holiSmackdown?.complete) button.disabled = true;
          if (index > resultIndex && !episode.finale?.finalLipSync?.resultRevealed) button.disabled = true;
        }
        button.addEventListener("click", () => {
          if (currentSectionName() === "Intro" && !state.seasonRuntime.introCompleted) return;
          if (index === state.seasonRuntime.currentSection || button.disabled) return;
            transitionRuntimeView(() => { state.seasonRuntime.currentSection = index; state.seasonRuntime.statisticsOpen = false; });
        });
        els.runtimeSectionTabsInner.append(button);
      });

    const indicator = document.createElement("span"); indicator.className = "runtime-section-tabs__indicator"; indicator.setAttribute("aria-hidden", "true");
    els.runtimeSectionTabsInner.append(indicator); els.runtimeSectionIndicator = indicator;
    const active = els.runtimeSectionTabsInner.querySelector(".runtime-section-tab.is-active");
    requestAnimationFrame(() => {
      positionIndicator(active, els.runtimeSectionIndicator, els.runtimeSectionTabsInner, false);
      const scroller = els.runtimeSectionTabs?.querySelector(".runtime-section-tabs__scroll");
      if (active && scroller) {
        const targetLeft = active.offsetLeft + active.offsetWidth / 2 - scroller.clientWidth / 2;
        scroller.scrollTo({ left: Math.max(0, targetLeft), behavior: "smooth" });
      }
    });
  }

