  function heartSuccessorChoicesRows() {
    const episodes = (state.seasonRuntime.episodes || [])
      .filter((episode) => episode?.heartSuccessorFormat)
      .slice()
      .sort((a, b) => Number(a?.number || 0) - Number(b?.number || 0));

    const rowsByEpisode = new Map();
    const completedHeartTransferByHolder = new Map();

    const rowForEpisode = (episodeNumber) => {
      const key = Number(episodeNumber) || 0;
      if (!rowsByEpisode.has(key)) {
        rowsByEpisode.set(key, {
          episodeNumber: key,
          eliminatedIds: [],
          successorIds: [],
          savedIds: [],
        });
      }
      return rowsByEpisode.get(key);
    };

    episodes.forEach((episode) => {
      (episode?.fullHeart?.saves || []).filter(Boolean).forEach((save) => {
        const holderKey = normalizeContestantId(save.holderId);
        const source = completedHeartTransferByHolder.get(holderKey);
        if (!source || !save.savedId) return;
        source.row.savedIds.push(save.savedId);
        completedHeartTransferByHolder.delete(holderKey);
      });

      const transfers = (episode?.heartInheritance?.transfers || []).filter(Boolean);
      if (!transfers.length) return;
      const row = rowForEpisode(episode.number);

      transfers.forEach((transfer) => {
        if (transfer.giverId) row.eliminatedIds.push(transfer.giverId);
        if (transfer.recipientId) row.successorIds.push(transfer.recipientId);

        if (transfer.completedHeart && transfer.recipientId) {
          completedHeartTransferByHolder.set(
            normalizeContestantId(transfer.recipientId),
            { row, transfer }
          );
        }
      });
    });

    return [...rowsByEpisode.values()]
      .sort((a, b) => a.episodeNumber - b.episodeNumber)
      .filter((row) => row.eliminatedIds.length || row.successorIds.length || row.savedIds.length);
  }

