    const shell = document.createElement("div");
    shell.className = "maxi-performance-view floor-show-view hellbound-showdown-view";

    const header = document.createElement("header");
    header.className = "maxi-challenge-header hellbound-showdown-header";
    const title = document.createElement("h2");
    title.className = "maxi-challenge-name";
    title.textContent = "Hellbound Showdown";
    const intro = document.createElement("p");
    intro.className = "maxi-challenge-description";
    intro.textContent = "Welcome to The Hellbound Showdown! Here, you'll fight for your life to return from the pits of hell into the competition by battling your fellow monsters.";
    header.append(title, intro);
    shell.append(header);

    const lineup = document.createElement("div");
    lineup.className = "status-lineup hellbound-showdown-lineup";
    (data.participantIds || []).forEach((id) => {
      const card = makeStatusContestant(id, false, "");
      if (card) lineup.append(card);
    });
