  function renderDragulaExterminationSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const extermination = episode?.extermination;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--lipsync runtime-content--dragula-extermination";
    if (!extermination) return;

    const shell = document.createElement("div");
    shell.className = "lipsync-performance-view dragula-extermination-view";

    const challenge = document.createElement("header");
    challenge.className = "lipsync-song dragula-extermination-heading";
    const title = document.createElement("h3");
    title.className = "lipsync-song__title";
    title.textContent = extermination.name || "Extermination";
    const description = document.createElement("p");
    description.className = "lipsync-song__artist dragula-extermination-description";
    description.textContent = dragulaMonsterCopy(extermination.description || "");
    challenge.append(title, description);
    shell.append(challenge);

    if (extermination.abnormalExit?.kind === "refuse-extermination") {
      appendAbnormalExitBlock(shell, extermination.abnormalExit, "is-lipsync-refusal");
      els.runtimeContent.append(shell);
      return;
    }

    const performances = document.createElement("div");
    performances.className = "lipsync-performance-list";
    (extermination.performances || []).forEach((performance) => {
      const card = makeLipSyncPerformanceCard({
        ...performance,
        bracket: String(performance.bracket || "mixed").toUpperCase(),
        summary: performance.summary || "",
        highlight: "",
      });
      if (card) performances.append(card);
    });
    shell.append(performances);
    els.runtimeContent.append(shell);
  }

  function appendDragulaStoryWithBlur(parent, story, name, revealed) {
    const text = String(story || "");
    const parts = text.split("{name}");
    parts.forEach((part, index) => {
      if (part) parent.append(document.createTextNode(part));
      if (index < parts.length - 1) {
        const span = document.createElement("span");
        span.className = `dragula-result-name${revealed ? " is-revealed" : ""}`;
        span.textContent = name;
        parent.append(span);
      }
    });
  }

  function launchDragulaBloodSplatter() {
    const existing = document.querySelector(".dragula-blood-splatter");
    if (existing) existing.remove();
    const layer = document.createElement("div");
    layer.className = "dragula-blood-splatter";
    layer.setAttribute("aria-hidden", "true");
    const colors = ["#4d0008", "#71000d", "#920014", "#b20b1d", "#65000b"];
    for (let index = 0; index < 105; index += 1) {
      const drop = document.createElement("i");
      drop.className = `dragula-blood-splatter__drop${index < 12 ? " is-splash" : ""}`;
      const angle = Math.random() * Math.PI * 2;
      const distance = 18 + Math.random() * 62;
      const x = Math.cos(angle) * distance;
      const y = Math.sin(angle) * distance;
      const size = index < 12 ? 22 + Math.random() * 44 : 3 + Math.random() * 14;
      drop.style.left = `${47 + Math.random() * 6}%`;
      drop.style.top = `${43 + Math.random() * 12}%`;
      drop.style.width = `${size}px`;
      drop.style.height = `${index < 12 ? size * (0.55 + Math.random() * 0.55) : size * (0.8 + Math.random() * 1.7)}px`;
      drop.style.background = colors[index % colors.length];
      drop.style.setProperty("--blood-x", `${x}vw`);
      drop.style.setProperty("--blood-y", `${y}vh`);
      drop.style.setProperty("--blood-rot", `${Math.round(Math.random() * 540 - 270)}deg`);
      drop.style.animationDelay = `${Math.random() * 120}ms`;
      drop.style.animationDuration = `${750 + Math.random() * 650}ms`;
      layer.append(drop);
    }
    document.body.append(layer);
    window.setTimeout(() => layer.classList.add("is-fading"), 1450);
    window.setTimeout(() => layer.remove(), 2450);
  }

  function renderDragulaResurrectionKillOrder(episode) {
    const data = episode?.resurrectionKillOrder || {};
    const rankingIds = Array.isArray(data.rankingIds) ? data.rankingIds : [];
    const killOrderIds = Array.isArray(data.killOrderIds) ? data.killOrderIds : [];
    const revealCount = Math.max(0, Math.min(killOrderIds.length, Number(data.revealCount) || 0));
    const revealedIds = killOrderIds.slice(0, revealCount);
    const killedKeys = new Set(revealedIds.map(normalizeContestantId));
    const winnerId = data.winnerId || rankingIds[0] || null;

    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--final-results runtime-content--dragula-winner runtime-content--resurrection-kill-order";
    const shell = document.createElement("div");
    shell.className = "resurrection-kill-order-view";

    const intro = document.createElement("p");
    intro.className = "resurrection-kill-order__intro";
    intro.textContent = "One by one, the monsters will be cut from the running until only one remains.";
    shell.append(intro);

    if (revealedIds.length) {
      const list = document.createElement("div");
      list.className = "resurrection-kill-order__kills";
      revealedIds.forEach((id, index) => {
        const monster = queenFromId(id);
        const rankIndex = rankingIds.findIndex((rankId) => normalizeContestantId(rankId) === normalizeContestantId(id));
        const place = rankIndex >= 0 ? rankIndex + 1 : rankingIds.length - index;
        const card = document.createElement("article");
        card.className = `resurrection-kill-order__kill${index === revealedIds.length - 1 ? " is-latest" : ""}`;
        if (monster) {
          const image = document.createElement("img");
          image.src = imageSrc(monster);
          image.alt = monster.fullName || monster.nickname || "Monster";
          image.addEventListener("error", () => image.removeAttribute("src"), { once: true });
          card.append(image);
        }
        const copy = document.createElement("div");
        copy.className = "resurrection-kill-order__kill-copy";
        const placement = document.createElement("span");
        placement.textContent = ordinal(place).toUpperCase();
        const name = document.createElement("strong");
        name.textContent = monster?.nickname || monster?.fullName || String(id);
        copy.append(placement, name);
        card.append(copy);
        list.append(card);
      });
      shell.append(list);
    }

    const aliveIds = rankingIds.filter((id) => !killedKeys.has(normalizeContestantId(id)));
    if (aliveIds.length > 1) {
      const aliveLabel = document.createElement("p");
      aliveLabel.className = "resurrection-kill-order__alive-label";
      aliveLabel.textContent = "STILL ALIVE";
      const lineup = document.createElement("div");
      lineup.className = "finale-lineup resurrection-kill-order__alive";
      aliveIds.forEach((id) => {
        const card = makeFinaleQueen(id, "finalist");
        if (card) lineup.append(card);
      });
      shell.append(aliveLabel, lineup);
    }

    if (revealCount < killOrderIds.length) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "control-btn control-btn--accent resurrection-kill-order__button";
      button.textContent = revealCount === 0 ? "BEGIN KILL ORDER" : "NEXT KILL";
      button.addEventListener("click", () => {
        data.revealCount = revealCount + 1;
        episode.dragulaFinaleResult.resultRevealed = data.revealCount >= killOrderIds.length;
        persistState();
        renderDragulaResurrectionKillOrder(episode);
        window.requestAnimationFrame(() => launchDragulaBloodSplatter());
      });
      shell.append(button);
    } else {
      const end = document.createElement("h3");
      end.className = "finale-title resurrection-kill-order__survivor-title";
      end.textContent = "One monster remains.";
      const winnerLineup = document.createElement("div");
      winnerLineup.className = "finale-lineup";
      const winnerCard = makeFinaleQueen(winnerId, "winner");
      if (winnerCard) winnerLineup.append(winnerCard);
      const winnerCopy = document.createElement("p");
      winnerCopy.className = "finale-winner-copy";
      winnerCopy.textContent = `${joinQueenNames([winnerId])}, you have been Resurrected!`;
      shell.append(end, winnerLineup, winnerCopy);
    }

    els.runtimeContent.append(shell);
  }

  function renderDragulaWinnerSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    if (episode?.dragulaResurrectionFinale) {
      renderDragulaResurrectionKillOrder(episode);
      return;
    }
    const result = episode?.dragulaFinaleResult || {};
    const winnerId = result.winnerId;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--final-results runtime-content--dragula-winner";
    const shell = document.createElement("div");
    shell.className = "finale-results-view dragula-finale-winner-view";

    if (!result.resultRevealed) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "control-btn lipsync-show-results finale-show-results";
      button.textContent = "SHOW RESULTS";
      button.addEventListener("click", () => {
        result.resultRevealed = true;
        persistState();
        button.classList.add("is-leaving");
        window.setTimeout(() => {
          renderDragulaWinnerSection();
          window.requestAnimationFrame(() => launchDragulaBloodSplatter());
        }, 180);
      });
      shell.append(button);
      els.runtimeContent.append(shell);
      return;
    }

    const end = document.createElement("h3");
    end.className = "finale-title";
    end.textContent = "The end.";
    const decision = document.createElement("p");
    decision.className = "finale-winner-copy";
    decision.textContent = "Monsters, we've made our decision. The World's Next Drag Supermonster is...";
    shell.append(end, decision);

    const winnerLineup = document.createElement("div");
    winnerLineup.className = "finale-lineup";
    const winnerCard = makeFinaleQueen(winnerId, "winner");
    if (winnerCard) winnerLineup.append(winnerCard);
    if (winnerLineup.children.length) shell.append(winnerLineup);

    const winnerCopy = document.createElement("p");
    winnerCopy.className = "finale-winner-copy";
    winnerCopy.textContent = `${joinQueenNames([winnerId])}, condragulations, you are the World's Next Drag Supermonster!`;
    shell.append(winnerCopy);
    els.runtimeContent.append(shell);
  }

