  function renderDragulaResultsSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--dragula-results";
    const shell = document.createElement("div");
    shell.className = "dragula-results-view";

    if (episode?.sonicTransducer?.occurs) {
      const sonic = episode.sonicTransducer;
      const winner = queenFromId(sonic.winnerId);
      const winnerBlock = document.createElement("section");
      winnerBlock.className = "sonic-transducer-result__winner";
      appendQueenLineup(winnerBlock, sonic.winnerId ? [sonic.winnerId] : [], "placement", "WIN");
      const prompt = document.createElement("p");
      prompt.className = "placement-group__copy sonic-transducer-result__prompt";
      prompt.textContent = `${winner?.nickname || winner?.fullName || "Monster"}, who have you chosen to exterminate using the Sonic Transducer?`;
      winnerBlock.append(prompt);
      shell.append(winnerBlock);

      if (!sonic.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn control-btn--accent dragula-show-results sonic-transducer-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          sonic.resultRevealed = true;
          if (episode.extermination) episode.extermination.resultRevealed = true;
          persistState();
          renderDragulaResultsSection();
        });
        shell.append(button);
      } else if (sonic.targetId) {
        const target = queenFromId(sonic.targetId);
        const reveal = document.createElement("section");
        reveal.className = "sonic-transducer-result__target";
        const circle = document.createElement("div");
        circle.className = "dragula-result-circle sonic-transducer-result__circle";
        if (target) {
          const image = document.createElement("img");
          image.src = imageSrc(target);
          image.alt = target.fullName || target.nickname || "Eliminated monster";
          circle.append(image);
        }
        const text = document.createElement("p");
        text.className = "placement-group__copy sonic-transducer-result__message";
        text.textContent = `${target?.nickname || target?.fullName || "The monster"} has been exterminated by the Sonic Transducer.`;
        reveal.append(circle, text);
        shell.append(reveal);
      }
      els.runtimeContent.append(shell);
      return;
    }

    const specialExit = episode?.extermination?.abnormalExit || null;
    if (specialExit) {
      if (!episode.extermination.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn control-btn--accent dragula-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          episode.extermination.resultRevealed = true;
          persistState();
          renderDragulaResultsSection();
        });
        shell.append(button);
      } else {
        appendAbnormalExitBlock(shell, specialExit, "is-results-exit");
      }
      els.runtimeContent.append(shell);
      return;
    }

    if (episode?.isFinale && episode?.dragulaFinale) {
      const result = episode.dragulaFinaleResult || {};
      const winner = queenFromId(result.winnerId);
      const card = document.createElement("section");
      card.className = `dragula-finale-result${result.resultRevealed ? " is-revealed" : ""}`;
      const circle = document.createElement("div");
      circle.className = "dragula-result-circle dragula-finale-result__circle";
      if (winner) {
        const image = document.createElement("img");
        image.src = imageSrc(winner);
        image.alt = winner.fullName || winner.nickname || "Winner";
        circle.append(image);
      }
      const copy = document.createElement("p");
      copy.className = "dragula-result-story";
      copy.textContent = result.resultRevealed
        ? `${winner?.nickname || winner?.fullName || "The winner"} has conquered the final Floor Show and wins the season!`
        : "One monster has conquered the final Floor Show and claimed the crown.";
      card.append(circle, copy);
      shell.append(card);
      if (!result.resultRevealed) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "control-btn control-btn--accent dragula-show-results";
        button.textContent = "SHOW RESULTS";
        button.addEventListener("click", () => {
          result.resultRevealed = true;
          persistState();
          renderDragulaResultsSection();
        });
        shell.append(button);
      }
      els.runtimeContent.append(shell);
      return;
    }

    const extermination = episode?.extermination;
    if (!extermination) { els.runtimeContent.append(shell); return; }
    if (extermination.resultType === "double-save") {
      const save = document.createElement("section");
      save.className = "dragula-double-save";
      appendQueenLineup(save, extermination.bottomIds || [], "placement", "SAFE");
      const copy = document.createElement("p");
      copy.textContent = extermination.resultRevealed ? "No one is exterminated. All of the monsters survive." : "The extermination is over. The Boulets have made their decision.";
      save.append(copy);
      shell.append(save);
    } else {
      (extermination.eliminatedIds || []).forEach((id) => {
        const queen = queenFromId(id);
        if (!queen) return;
        const card = document.createElement("section");
        card.className = `dragula-result-card${extermination.resultRevealed ? " is-revealed" : ""}`;
        const circle = document.createElement("div");
        circle.className = "dragula-result-circle";
        const image = document.createElement("img");
        image.src = imageSrc(queen);
        image.alt = queen.fullName || queen.nickname || "Exterminated contestant";
        circle.append(image);
        const title = document.createElement("h3");
        title.className = "dragula-result-title";
        title.textContent = extermination.resultScene?.title || extermination.name || "Exterminated";
        const story = document.createElement("p");
        story.className = "dragula-result-story";
        appendDragulaStoryWithBlur(story, extermination.resultScene?.story || "{name} has been exterminated.", queen.nickname || queen.fullName || queen.id, extermination.resultRevealed);
        card.append(circle, title, story);
        shell.append(card);
      });
    }

    if (!extermination.resultRevealed) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "control-btn control-btn--accent dragula-show-results";
      button.textContent = "SHOW RESULTS";
      button.addEventListener("click", () => {
        extermination.resultRevealed = true;
        persistState();
        renderDragulaResultsSection();
      });
      shell.append(button);
    }
    els.runtimeContent.append(shell);
  }

  function renderDragulaExterminationStatistics(shell) {
    const allEpisodes = state.seasonRuntime.episodes || [];
    const rows = allEpisodes
      .map((episode, episodeIndex) => ({ episode, episodeIndex }))
      .filter(({ episode }) => episode?.dragula && !episode?.isFinale && episode?.extermination?.occurs);

    const wrap = document.createElement("div");
    wrap.className = "statistics-table-wrap lip-sync-statistics-wrap dragula-extermination-statistics-wrap";
    const table = document.createElement("table");
    table.className = "statistics-table lip-sync-statistics-table dragula-extermination-table";
    table.style.minWidth = "860px";
    const thead = document.createElement("thead");
    appendLipSyncStatisticsHeader(thead, ["Episode", "Monsters", "Extermination", "Eliminated"]);
    table.append(thead);
    const tbody = document.createElement("tbody");

    rows.forEach(({ episode, episodeIndex }) => {
      const ex = episode.extermination;
      const row = document.createElement("tr");
      row.className = "lip-sync-statistics-row";

      const episodeCell = document.createElement("td");
      episodeCell.className = "lip-sync-statistics-episode";
      const episodeMain = document.createElement("strong");
      episodeMain.textContent = `Ep. ${episode.number}`;
      episodeCell.append(episodeMain);

      const monstersCell = document.createElement("td");
      monstersCell.className = "lip-sync-statistics-contestants-cell";
      monstersCell.append(statisticsLipSyncContestants(ex.bottomIds || []));

      const exterminationCell = document.createElement("td");
      exterminationCell.className = "lip-sync-statistics-song-cell";
      exterminationCell.append(statisticsLipSyncSong({ song: ex.name || "Extermination", artist: "" }));

      const resultCell = document.createElement("td");
      const eliminatedIds = [...(ex.eliminatedIds || [])];
      if (ex.resultType === "double-save") {
        resultCell.className = "lip-sync-statistics-result is-double-shantay";
        resultCell.textContent = "DOUBLE SAVE";
      } else if (eliminatedIds.length) {
        resultCell.className = "lip-sync-statistics-result is-eliminated";
        resultCell.append(statisticsContestantList(eliminatedIds, { compact: true }));
        applyStatisticsLipSyncEliminationColor(resultCell, eliminatedIds, episodeIndex);
      } else {
        resultCell.className = "lip-sync-statistics-result is-neutral";
        resultCell.textContent = "-";
      }

      row.append(episodeCell, monstersCell, exterminationCell, resultCell);
      tbody.append(row);
    });

    if (!rows.length) {
      const empty = document.createElement("tr");
      const td = document.createElement("td");
      td.colSpan = 4;
      td.className = "lip-sync-statistics-empty";
      td.textContent = "-";
      empty.append(td);
      tbody.append(empty);
    }
    table.append(tbody);
    wrap.append(table);
    shell.append(wrap);
  }

