  function luckyCoinImageSrc(side) {
    return `images/${String(side || "heads").toLowerCase() === "tails" ? "tails" : "heads"}.webp`;
  }

  function renderLuckyCoinFlipSection() {
    clearRuntimeTimers();
    const episode = currentEpisodeData();
    const event = episode?.luckyCoin;
    els.runtimeContent.replaceChildren();
    els.runtimeContent.className = "runtime-content runtime-content--lucky-coin runtime-content--coin-flip";
    if (!event?.active) return;

    setRuntimeLocked(!event.flipRevealed);

    const shell = document.createElement("section");
    shell.className = "lucky-coin-view lucky-coin-flip-view";

    const prompt = document.createElement("p");
    prompt.className = "lucky-coin-prompt";
    prompt.textContent = "Are you ready? It's time to flip the coin.";

    const coinStage = document.createElement("div");
    coinStage.className = "lucky-coin-stage";
    const coin = document.createElement("img");
    coin.className = "lucky-coin-image";
    coin.alt = event.flipRevealed ? `${event.coinResult} side of the Lucky Coin` : "Lucky Coin";
    coin.src = luckyCoinImageSrc(event.flipRevealed ? event.coinResult : "heads");
    coin.addEventListener("error", () => coin.removeAttribute("src"), { once: true });
    coinStage.append(coin);

    const result = document.createElement("p");
    result.className = "lucky-coin-result";
    if (event.flipRevealed) {
      result.classList.add(`is-${event.coinResult}`);
      result.textContent = `The coin landed on ${event.coinResult === "heads" ? "HEADS" : "TAILS"}!`;
    } else {
      result.hidden = true;
    }

    const actions = document.createElement("div");
    actions.className = "lucky-coin-actions";
    if (!event.flipRevealed) {
      const flip = document.createElement("button");
      flip.type = "button";
      flip.className = "control-btn control-btn--accent lucky-coin-flip-btn";
      flip.textContent = "FLIP COIN";
      flip.addEventListener("click", () => {
        flip.disabled = true;
        setRuntimeLocked(true);
        coin.classList.remove("is-landed");
        coin.classList.add("is-flipping");

        let visibleSide = "heads";
        let step = 0;
        const totalSteps = 22;
        const tick = () => {
          step += 1;
          visibleSide = visibleSide === "heads" ? "tails" : "heads";
          coin.src = luckyCoinImageSrc(visibleSide);

          if (step >= totalSteps) {
            coin.src = luckyCoinImageSrc(event.coinResult);
            coin.alt = `${event.coinResult} side of the Lucky Coin`;
            coin.classList.remove("is-flipping");
            void coin.offsetWidth;
            coin.classList.add("is-landed");
            event.flipRevealed = true;
            result.hidden = false;
            result.className = `lucky-coin-result is-${event.coinResult}`;
            result.textContent = `The coin landed on ${event.coinResult === "heads" ? "HEADS" : "TAILS"}!`;
            actions.replaceChildren();
            persistState();
            setRuntimeLocked(false);
            return;
          }

          const slowdown = Math.max(0, step - 10);
          const delay = step <= 10
            ? 52
            : Math.min(390, 70 + Math.round(Math.pow(slowdown, 1.55) * 18));
          const timer = window.setTimeout(tick, delay);
          luckyCoinTimers.push(timer);
        };

        const timer = window.setTimeout(tick, 45);
        luckyCoinTimers.push(timer);
      });
      actions.append(flip);
    }

    shell.append(prompt, coinStage, result, actions);
    els.runtimeContent.append(shell);
  }

