    shell.append(lineup);
    const revealArea=cmmNode('div','mini-winner-area');
    if(!mini.winnerRevealed){revealArea.append(cmmButton('SHOW WINNER',()=>{mini.winnerRevealed=true;persistState();cmmRenderActiveSection();},'control-btn mini-show-winner'));}
    else revealArea.append(cmmNativeReveal([mini.winnerId],`${cmmName(mini.winnerId)} wins the mini-challenge!`));
    shell.append(revealArea);els.runtimeContent.append(shell);
