    const strategy=bmStrategicEvents(phase,round);
    const ratio=bmRoundPool(round).length/Math.max(1,s.all.length);const min=ratio>=.72?6:ratio>=.43?5:3;const count=min+Math.floor(Math.random()*3);
    const events=[],used=new Set();
