      const arr=c.results.filter(x=>x.bracket===bracket);if(!arr.length)continue;
      const g=bmNode('section',`performance-group performance-group--${bracket.toLowerCase()}`);
      g.append(bmNode('h4','performance-group__label',bracket));const line=bmNode('div','performance-group__lineup');
      for(const x of arr){const q=bmQueen(x.id);if(q)line.append(makePerformanceContestant(q,bracket));}
      g.append(line);groups.append(g);
